begin;
    with j as (select * from jsonb_to_recordset($law7v029$[{"code_id":"NK_RF_2","article_number":"382","version_date":"2000-07-31","article_text":"Рассмотрение налоговым органом заявления о гибели или уничтожении объекта налогообложения, в том числе направление запроса сведений, подтверждающих факт гибели или уничтожения объекта налогообложения, и рассмотрение такого запроса, направление налогоплательщику уведомления о прекращении исчисления налога в связи с гибелью или уничтожением объекта налогообложения либо сообщения об отсутствии основания для прекращения исчисления налога в связи с гибелью или уничтожением объекта налогообложения осуществляются в порядке, аналогичном порядку, предусмотренному пунктом 31 статьи 362 настоящего Кодекса.\n\nФорма заявления о гибели или уничтожении объекта налогообложения, порядок ее заполнения, формат представления такого заявления в электронной форме, формы уведомления о прекращении исчисления налога в связи с гибелью или уничтожением объекта налогообложения, сообщения об отсутствии основания для прекращения исчисления налога в связи с гибелью или уничтожением объекта налогообложения утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если налогоплательщик не представил в налоговый орган заявление о гибели или уничтожении объекта налогообложения, исчисление налога прекращается с 1-го числа месяца гибели или уничтожения такого объекта на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nЕсли возникновение права собственности (права хозяйственного ведения) на объекты недвижимого имущества, указанные в статье 3782 настоящего Кодекса, произошло до 15-го числа соответствующего месяца включительно или прекращение указанного права произошло после 15-го числа соответствующего месяца, за полный месяц принимается месяц возникновения (прекращения) указанного права. (Дополнение абзацем - Федеральный закон от 29.12.2015 № 396-ФЗ) (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nЕсли возникновение права собственности (права хозяйственного ведения) на объекты недвижимого имущества, указанные в статье 3782 настоящего Кодекса, произошло после 15-го числа соответствующего месяца или прекращение указанного права произошло до 15-го числа соответствующего месяца включительно, месяц возникновения (прекращения) указанного права не учитывается при определении коэффициента, указанного в настоящем пункте. (Дополнение абзацем - Федеральный закон от 29.12.2015 № 396-ФЗ) (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nПредставление заявления о предоставлении налоговой льготы, подтверждение права налогоплательщика на налоговую льготу, рассмотрение налоговым органом такого заявления, направление налогоплательщику уведомления о предоставлении налоговой льготы либо сообщения об отказе от предоставления налоговой льготы осуществляются в порядке, аналогичном порядку, предусмотренному пунктом 3 статьи 3611 настоящего Кодекса.\n\nФорма заявления налогоплательщика о предоставлении налоговой льготы, порядок ее заполнения, формат представления такого заявления в электронной форме, формы уведомления о предоставлении налоговой льготы, сообщения об отказе от предоставления налоговой льготы утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если налогоплательщик, имеющий право на налоговую льготу, не представил в налоговый орган заявление о предоставлении налоговой льготы или не сообщил об отказе от применения налоговой льготы, налоговая льгота предоставляется на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами, начиная с налогового периода, в котором у налогоплательщика возникло право на налоговую льготу.\n\nВ случае возникновения (прекращения) у налогоплательщика в течение налогового (отчетного) периода права на налоговую льготу исчисление суммы налога (суммы авансового платежа по налогу) в отношении объекта налогообложения, по которому предоставляется налоговая льгота, производится с учетом коэффициента, определяемого как отношение числа полных месяцев, в течение которых отсутствует налоговая льгота, к числу календарных месяцев в налоговом (отчетном) периоде. При этом месяц возникновения права на налоговую льготу, а также месяц прекращения указанного права принимается за полный месяц.\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)","article_title":"Статья 382. Порядок исчисления суммы налога и сумм авансовых платежей по налогу","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ebe0d964296250875dc00cbe78bb10a9d64fdcd472a4bab730f76211b8a9d81"},{"code_id":"NK_RF_2","article_number":"382.1","version_date":"2000-07-31","article_text":"1. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений вправе уменьшить сумму налога (авансового платежа по налогу), исчисленную им в соответствии со статьей 382 настоящего Кодекса в отношении имущества, созданного (построенного), модернизированного, реконструированного в рамках реализации инвестиционного проекта, который предусмотрен соглашением о защите и поощрении капиталовложений, и используемого им при реализации указанного инвестиционного проекта, на сумму налогового вычета для СЗПК в порядке и на условиях, которые установлены настоящей статьей.\n\n2. Размер налогового вычета для СЗПК определяется суммой, отраженной в уведомлении о налоговом вычете для СЗПК применительно к налогу (авансовому платежу по налогу) в отношении соответствующего объекта налогообложения, которое представлено в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в соответствии со статьей 2518 настоящего Кодекса (далее в настоящей статье - уведомление).\n\n3. Налоговый вычет для СЗПК применяется начиная с налогового периода, следующего за годом представления уведомления.\n\n4. В результате применения налогового вычета для СЗПК сумма налога (авансового платежа по налогу) может быть снижена до нуля.\n\nНеиспользованная часть налогового вычета для СЗПК учитывается при исчислении суммы налога (авансового платежа по налогу) в последующие налоговые (отчетные) периоды, если применение налогового вычета в этих последующих налоговых (отчетных) периодах предусмотрено уведомлением применительно к налогу (авансовому платежу по налогу) в отношении соответствующего объекта налогообложения.\n\n5. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений имеет право уменьшать сумму налога (авансового платежа по налогу) до наступления хотя бы одного из следующих оснований:\n\n1) общая сумма налога (авансового платежа по налогу), не уплаченная в связи с применением налогового вычета для СЗПК, стала равна сумме, отраженной в уведомлении применительно к налогу в отношении соответствующего объекта налогообложения;\n\n2) истек срок применения налогового вычета для СЗПК, указанный в уведомлении применительно к налогу в отношении соответствующего объекта налогообложения;\n\n3) налогоплательщик утратил статус участника соглашения о защите и поощрении капиталовложений.\n\n6. В случае, если в уведомлении указаны налоговые вычеты для СЗПК с различными сроками их применения в отношении соответствующего объекта налогообложения, в первую очередь сумма налога (авансового платежа по налогу) уменьшается на суммы налоговых вычетов для СЗПК с меньшим сроком применения.\n\n7. Если по одному соглашению о защите и поощрении капиталовложений представляется несколько уведомлений в отношении соответствующего объекта налогообложения, уменьшение суммы налога (авансового платежа по налогу) осуществляется в хронологическом порядке представления таких уведомлений.\n\n8. Для применения налогового вычета, предусмотренного настоящей статьей, налогоплательщик обязан обеспечить ведение раздельного учета недвижимого имущества, используемого при реализации инвестиционного проекта в рамках каждого соглашения о защите и поощрении капиталовложений, и недвижимого имущества, используемого при осуществлении иной деятельности, в порядке, закрепленном в учетной политике организации.\n\n(Дополнение статьей - Федеральный закон от 28.06.2022 № 225-ФЗ)","article_title":"Статья 382.1. Налоговый вычет для налогоплательщиков - участников соглашений о защите и поощрении капиталовложений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"78246bd973f5c8a1185ddcf24daffda9681d74d7d2613d4ba5a0c7e69c1d62ae"},{"code_id":"NK_RF_2","article_number":"384","version_date":"2000-07-31","article_text":"Организация, в состав которой входят обособленные подразделения, имеющие отдельный баланс, уплачивает налог (авансовые платежи по налогу) в бюджет по местонахождению каждого из обособленных подразделений в отношении имущества, признаваемого объектом налогообложения в соответствии со статьей 374 настоящего Кодекса, находящегося на отдельном балансе каждого из них, в сумме, определяемой как произведение налоговой ставки, действующей на территории соответствующего субъекта Российской Федерации, федеральной территории \"Сириус\", на которых расположены эти обособленные подразделения, и налоговой базы (одной четвертой средней стоимости имущества), определенной за налоговый (отчетный) период в соответствии со статьей 376 настоящего Кодекса, в отношении каждого обособленного подразделения с учетом особенностей, установленных статьей 3782 настоящего Кодекса. (В редакции федеральных законов от 24.07.2007 № 216-ФЗ, от 02.11.2013 № 307-ФЗ, от 11.06.2021 № 199-ФЗ)","article_title":"Статья 384. Особенности исчисления и уплаты налога по местонахождению обособленных подразделений организации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"07a250c415635f7fd7c21e132e574082779ddf1a432b7e4c57c23ca8aab53b52"},{"code_id":"NK_RF_2","article_number":"385","version_date":"2000-07-31","article_text":"Организация, учитывающая на балансе объекты недвижимого имущества, находящиеся вне местонахождения организации или ее обособленного подразделения, имеющего отдельный баланс, уплачивает налог (авансовые платежи по налогу) в бюджет по местонахождению каждого из указанных объектов недвижимого имущества в сумме, определяемой как произведение налоговой ставки, действующей на территории соответствующего субъекта Российской Федерации, федеральной территории \"Сириус\", на которых расположены эти объекты недвижимого имущества, и налоговой базы (одной четвертой средней стоимости имущества), определенной за налоговый (отчетный) период в соответствии со статьей 376 настоящего Кодекса, в отношении каждого объекта недвижимого имущества с учетом особенностей, установленных стат\n\nьей 3782 настоящего Кодекса. (В редакции федеральных законов от 24.07.2007 № 216-ФЗ, от 02.11.2013 № 307-ФЗ, от 11.06.2021 № 199-ФЗ)","article_title":"Статья 385. Особенности исчисления и уплаты налога в отношении объектов недвижимого имущества, находящихся вне местонахождения организации или ее обособленного подразделения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e1628fcf390e87ebcd9653980128ee8cd9783bd1425eb29309d587c1ae3c3144"},{"code_id":"NK_RF_2","article_number":"385.1","version_date":"2000-07-31","article_text":"В этом случае резидент обязан исчислить сумму налога в отношении имущества, созданного или приобретенного им при реализации инвестиционного проекта в соответствии с Федеральным законом \"Об Особой экономической зоне в Калининградской области и о внесении изменений в некоторые законодательные акты Российской Федерации\", по налоговой ставке, установленной в соответствии со статьей 380 настоящего Кодекса. (В редакции Федерального закона от 27.11.2017 № 353-ФЗ)\n\nИсчисление суммы налога производится за период применения особого порядка налогообложения.\n\nИсчисленная сумма налога подлежит уплате резидентом по истечении отчетного или налогового периода, в котором он был исключен из единого реестра резидентов Особой экономической зоны в Калининградской области, не позднее сроков, установленных для уплаты авансовых платежей по налогу за отчетный период или налога за налоговый период в соответствии с пунктом 1 статьи 383 настоящего Кодекса.\n\nПри проведении выездной налоговой проверки резидента, исключенного из единого реестра резидентов Особой экономической зоны в Калининградской области, в части правильности исчисления и полноты уплаты суммы налога в отношении имущества, созданного или приобретенного им при реализации инвестиционного проекта, ограничения, установленные абзацем вторым пункта 4 и пунктом 5 статьи 89 настоящего Кодекса, не действуют при условии, если решение о назначении такой проверки вынесено не позднее чем в течение трех месяцев с момента уплаты резидентом указанной суммы налога.\n\n(Дополнение пунктом - Федеральный закон от 17.05.2007 № 84-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 10.01.2006 № 16-ФЗ)","article_title":"Статья 385.1. Особенности исчисления и уплаты налога на имущество организаций резидентами Особой экономической зоны в Калининградской области","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bbc30e39f956b71f13f67d37bcd2b9c39d3678fa2ddf2f550479cb7868496e32"},{"code_id":"NK_RF_2","article_number":"385.2","version_date":"2000-07-31","article_text":"1. В отношении имущества, входящего в состав Единой системы газоснабжения, налог (авансовые платежи по налогу) исчисляется (исчисляются) исходя из налоговой базы, определенной в целом по субъекту Российской Федерации, и уплачивается (уплачиваются) в бюджеты субъектов Российской Федерации по фактическому месту нахождения этого имущества.\n\n2. В целях настоящей главы фактическим местом нахождения имущества, входящего в состав Единой системы газоснабжения, признается территория соответствующего субъекта Российской Федерации, в котором осуществляются добыча, транспортировка, хранение и (или) поставки газа.\n\n3. Организация - собственник имущества, входящего в состав Единой системы газоснабжения, обязана обеспечить учет указанного имущества с указанием в первичных документах бухгалтерского учета его фактического места нахождения.\n\n(Дополнение статьей - Федеральный закон от 28.11.2009 № 284-ФЗ)","article_title":"Статья 385.2. Особенности исчисления и уплаты налога в отношении имущества, входящего в состав Единой системы газоснабжения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28c4d518fc0cf718710012112bf86e474ce44962558d4b0155af7ea48eb14a0c"},{"code_id":"NK_RF_2","article_number":"385.3","version_date":"2000-07-31","article_text":"1. В отношении железнодорожных путей общего пользования и сооружений, являющихся их неотъемлемой технологической частью, соответствующих требованиям, установленным Правительством Российской Федерации, впервые принятых на учет в качестве объектов основных средств начиная с 1 января 2017 года, сумма налога исчисляется с применением коэффициента Кжд, значение которого определяется в соответствии с пунктом 2 настоящей статьи.\n\n2. В течение шести налоговых периодов начиная с 1-го числа налогового периода, в котором соответствующее имущество было впервые принято на учет в качестве объекта основных средств, коэффициент Кжд принимается равным:\n\n0 - в течение первого налогового периода;\n\n0,1 - в течение второго налогового периода;\n\n0,2 - в течение третьего налогового периода;\n\n0,4 - в течение четвертого налогового периода;\n\n0,6 - в течение пятого налогового периода;\n\n0,8 - в течение шестого налогового периода.\n\n(Дополнение статьей - Федеральный закон от 28.12.2016 № 464-ФЗ)","article_title":"Статья 385.3. Особенности исчисления налога в отношении железнодорожных путей общего пользования и сооружений, являющихся их неотъемлемой технологической частью","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b30b34db48acfd64d22df5acb64d52ccbe916f06f0a45899e00f458f9d7ffce0"},{"code_id":"NK_RF_2","article_number":"386","version_date":"2000-07-31","article_text":"В отношении имущества, место нахождения которого во внутренних морских водах Российской Федерации, в территориальном море Российской Федерации, на континентальном шельфе Российской Федерации, в исключительной экономической зоне Российской Федерации и (или) за пределами территории Российской Федерации (для российских организаций), налоговая декларация по налогу представляется в налоговый орган по месту нахождения российской организации (месту учета в налоговых органах постоянного представительства иностранной организации). (В редакции федеральных законов от 30.09.2013 № 268-ФЗ, от 15.04.2019 № 63-ФЗ, от 02.07.2021 № 305-ФЗ)\n\nНалогоплательщики, в соответствии со статьей 83 настоящего Кодекса отнесенные к категории крупнейших, представляют налоговые декларации в налоговый орган по месту учета в качестве крупнейших налогоплательщиков. (Дополнение абзацем - Федеральный закон от 30.12.2006 № 268-ФЗ) (В редакции Федерального закона от 15.04.2019 № 63-ФЗ)\n\nВ налоговую декларацию включаются сведения о среднегодовой стоимости объектов движимого имущества, учтенных на балансе организации в качестве объектов основных средств в порядке, установленном для ведения бухгалтерского учета. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n11. Налогоплательщик, состоящий на учете в нескольких налоговых органах по месту нахождения принадлежащих ему объектов недвижимого имущества, налоговая база по которым определяется как их среднегодовая стоимость, на территории субъекта Российской Федерации, вправе представлять налоговую декларацию в отношении всех таких объектов недвижимого имущества в один из указанных налоговых органов по своему выбору, уведомив об этом налоговый орган по субъекту Российской Федерации.\n\nУведомление о порядке представления налоговой декларации в налоговый орган на территории субъекта Российской Федерации представляется ежегодно до 1 февраля года, являющегося налоговым периодом, в котором применяется предусмотренный настоящим пунктом порядок представления налоговой декларации. Изменение выбранного налогоплательщиком порядка представления налоговой декларации в течение налогового периода не допускается. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nУведомление о порядке представления налоговой декларации в налоговый орган на территории субъекта Российской Федерации рассматривается налоговым органом по субъекту Российской Федерации в течение 10 дней со дня его получения. В случае направления налоговым органом запроса в соответствии с пунктом 13 статьи 85 настоящего Кодекса в связи с отсутствием сведений, необходимых для рассмотрения уведомления о порядке представления налоговой декларации, руководитель (заместитель руководителя) налогового органа вправе продлить срок рассмотрения такого уведомления не более чем на 10 дней, уведомив об этом налогоплательщика. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nПри выявлении оснований, препятствующих применению предусмотренного настоящим пунктом порядка представления налоговой декларации, налоговый орган по субъекту Российской Федерации информирует об этом налогоплательщика. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nФорма уведомления о порядке представления налоговой декларации в налоговый орган на территории субъекта Российской Федерации утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nПоложения настоящего пункта не применяются в случае, если законом субъекта Российской Федерации установлены нормативы отчислений от налога в местные бюджеты.\n\n(Дополнение пунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ) (Утратил силу - Федеральный закон от 20.04.2021 № 100-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nВ случае, если у налогоплательщика - российской организации в истекшем налоговом периоде имелись только объекты налогообложения, указанные в абзаце первом настоящего пункта, налоговая декларация не представляется.\n\nВ целях обеспечения полноты уплаты налога в отношении объектов налогообложения, указанных в абзаце первом настоящего пункта, составление, передача (направление) налоговыми органами налогоплательщикам - российским организациям сообщений об исчисленных налоговыми органами суммах налога в отношении таких объектов налогообложения, представление такими налогоплательщиками в налоговые органы пояснений и (или) документов, подтверждающих правильность исчисления, полноту и своевременность уплаты налога, обоснованность применения пониженных налоговых ставок, налоговых льгот или наличие оснований для освобождения от уплаты налога, предусмотренных законодательством о налогах и сборах, рассмотрение налоговыми органами представленных такими налогоплательщиками пояснений и (или) документов и передача (направление) налоговыми органами таким налогоплательщикам уточненных сообщений об исчисленных суммах налога осуществляются в порядке и сроки, аналогичные порядку и срокам, которые предусмотрены пунктами 4 - 7 статьи 363 настоящего Кодекса.\n\nНалогоплательщику - российской организации направляется требование об уплате налога в соответствии с пунктом 1 статьи 70 настоящего Кодекса в случае, если выявлена недоимка по результатам рассмотрения налоговым органом представленных налогоплательщиком пояснений и (или) документов, подтверждающих правильность исчисления, полноту и своевременность уплаты налога, обоснованность применения пониженных налоговых ставок, налоговых льгот или наличие оснований для освобождения от уплаты налога, предусмотренных законодательством о налогах и сборах, либо если недоимка выявлена при отсутствии необходимых пояснений и (или) документов.\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)","article_title":"Статья 386. Налоговая декларация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ac0d52bca7d2d9ca388fac8e3a62167fec21f91d6acb0c1cc4a637e66b50d1ae"},{"code_id":"NK_RF_2","article_number":"386.1","version_date":"2000-07-31","article_text":"1. Фактически уплаченные российской организацией за пределами территории Российской Федерации в соответствии с законодательством другого государства суммы налога на имущество в отношении имущества, принадлежащего российской организации и расположенного на территории этого государства, засчитываются при уплате налога в Российской Федерации в отношении указанного имущества.\n\nПри этом размер засчитываемых сумм налога, выплаченных за пределами территории Российской Федерации, не может превышать размер суммы налога, подлежащего уплате этой организацией в Российской Федерации в отношении имущества, указанного в настоящем пункте.\n\n2. Для зачета налога российская организация должна представить в налоговые органы документ об уплате налога за пределами территории Российской Федерации, подтвержденный налоговым органом соответствующего иностранного государства.\n\nУказанный документ подается российской организацией в налоговый орган по месту нахождения российской организации вместе с налоговой декларацией за налоговый период, в котором был уплачен налог за пределами территории Российской Федерации.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 24.07.2007 № 216-ФЗ)\n\nРАЗДЕЛ X. МЕСТНЫЕ НАЛОГИ И СБОРЫ\n\n(Наименование в редакции Федерального закона от 29.11.2014 № 382-ФЗ)\n\n(Дополнение разделом - Федеральный закон от 29.11.2004 № 141-ФЗ)\n\nГЛАВА 31. ЗЕМЕЛЬНЫЙ НАЛОГ","article_title":"Статья 386.1. Устранение двойного налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdbf286ca955a8562e4ddf7750a23309094af0050b24229c51d23694542a8ecc"},{"code_id":"NK_RF_2","article_number":"387","version_date":"2000-07-31","article_text":"1. Земельный налог (далее в настоящей главе - налог) устанавливается настоящим Кодексом и нормативными правовыми актами представительных органов муниципальных образований, вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и нормативными правовыми актами представительных органов муниципальных образований и обязателен к уплате на территориях этих муниципальных образований.\n\nВ городах федерального значения Москве, Санкт-Петербурге и Севастополе налог устанавливается настоящим Кодексом и законами указанных субъектов Российской Федерации, вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и законами указанных субъектов Российской Федерации и обязателен к уплате на территориях указанных субъектов Российской Федерации. (В редакции Федерального закона от 29.11.2014 № 379-ФЗ)\n\nВ федеральной территории \"Сириус\" налог устанавливается настоящим Кодексом и нормативными право\n\nвыми актами представительного органа федеральной территории \"Сириус\", вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и нормативными правовыми актами представительного органа федеральной территории \"Сириус\" и обязателен к уплате в федеральной территории \"Сириус\". (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\nПри установлении налога нормативными правовыми актами представительных органов муниципальных образований (законами городов федерального значения Москвы, Санкт-Петербурга и Севастополя, нормативными правовыми актами представительного органа федеральной территории \"Сириус\") могут также устанавливаться налоговые льготы, основания и порядок их применения, включая установление величины налогового вычета для отдельных категорий налогоплательщиков. (В редакции федеральных законов от 29.11.2014 № 379-ФЗ, от 28.12.2017 № 436-ФЗ, от 11.06.2021 № 199-ФЗ)","article_title":"Статья 387. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"031cc186782e04753d1ef92c335d5c2c7d6ae05f10131adb3b3f7cdc04984e10"},{"code_id":"NK_RF_2","article_number":"388","version_date":"2000-07-31","article_text":"В отношении земельных участков, входящих в имущество, составляющее паевой инвестиционный фонд, налогоплательщиками признаются управляющие компании. При этом налог уплачивается за счет имущества, составляющего этот паевой инвестиционный фонд. (Дополнение абзацем - Федеральный закон от 27.11.2010 № 308-ФЗ)\n\nНе признаются налогоплательщиками организации, зарегистрированные на территории Курильских островов, в течение периода использования такими организациями права на освобождение от исполнения обязанностей налогоплательщика налога на прибыль организаций в соответствии со статьей 2463 настоящего Кодекса. В случае утраты организацией в соответствии с пунктом 3 статьи 2463 настоящего Кодекса такого права она признается налогоплательщиком с 1-го числа налогового периода, в котором утрачено такое право, и сумма налога (авансового платежа по налогу) подлежит восстановлению и уплате в бюджет в установленном порядке с уплатой соответствующих пеней, начисляемых со дня, следующего за установленным статьей 397 настоящего Кодекса днем уплаты налога (авансового платежа по налогу). (Дополнение абзацем - Федеральный закон от 09.03.2022 № 50-ФЗ)","article_title":"Статья 388. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"339c6a99e86d8f64909225739bf0e713ea38e0db9f2611fca2a13172c54d34b6"},{"code_id":"NK_RF_2","article_number":"389","version_date":"2000-07-31","article_text":"1) земельные участки, изъятые из оборота в соответствии с законодательством Российской Федерации;\n\n2) земельные участки, ограниченные в обороте в соответствии с законодательством Российской Федерации, которые заняты особо ценными объектами культурного наследия народов Российской Федерации, объектами, включенными в Список всемирного наследия, историко-культурными заповедниками, объектами археологического наследия, музеями-заповедниками; (В редакции Федерального закона от 22.10.2014 № 315-ФЗ)\n\n3) (Подпункт утратил силу - Федеральный закон от 29.11.2012 № 202-ФЗ)\n\n4) земельные участки из состава земель лесного фонда; (В редакции Федерального закона от 04.12.2006 № 201-ФЗ)\n\n5) земельные участки, ограниченные в обороте в соответствии с законодательством Российской Федерации, занятые находящимися в государственной собственности водными объектами в составе водного фонда; (В редакции Федерального закона от 04.12.2006 № 201-ФЗ)\n\n6) земельные участки, входящие в состав общего имущества многоквартирного дома. (Дополнение подпунктом - Федеральный закон от 04.10.2014 № 284-ФЗ)","article_title":"Статья 389. Объект налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a63f28aa032930e1b63c49cd486d1d8a0c3ebe700895cd9739ffa02fad6a8c56"},{"code_id":"NK_RF_2","article_number":"390","version_date":"2000-07-31","article_text":"1. Налоговая база определяется как кадастровая стоимость земельных участков, признаваемых объектом налогообложения в соответствии со статьей 389 настоящего Кодекса.","article_title":"Статья 390. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9a21312ae057ffac5f86173c8f581e326aa6111e2da737f18a14f8c5a3b8918d"},{"code_id":"NK_RF_2","article_number":"391","version_date":"2000-07-31","article_text":"В отношении земельного участка, образованного в течение налогового периода, налоговая база в данном налоговом периоде определяется как его кадастровая стоимость на день внесения в Единый государственный реестр недвижимости сведений, являющихся основанием для определения кадастровой стоимости такого земельного участка. (Дополнение абзацем - Федеральный закон от 28.11.2009 № 283-ФЗ) (В редакции федеральных законов от 04.10.2014 № 284-ФЗ; от 30.11.2016 № 401-ФЗ)\n\nНалоговая база в отношении земельного участка, находящегося на территориях нескольких муниципальных образований (на территориях муниципального образования и городов федерального значения Москвы, Санкт-Петербурга, Севастополя или федеральной территории \"Сириус\"), определяется по каждому муниципальному образованию (городам федерального значения Москве, Санкт-Петербургу и Севастополю, федеральной территории \"Сириус\"). При этом налоговая база в отношении части земельного участка, расположенной в границах соответствующего муниципального образования (городов федерального значения Москвы, Санкт-Петербурга и Севастополя, федеральной территории \"Сириус\"), определяется как доля кадастровой стоимости всего земельного участка, пропорциональная указанной части земельного участка. (Дополнение абзацем - Федеральный закон от 24.07.2007 № 216-ФЗ) (В редакции  федеральных законов от 29.11.2014 № 379-ФЗ, от 11.06.2021 № 199-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 04.10.2014 № 284-ФЗ) (Утратил силу - Федеральный закон от 03.08.2018 № 334-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 04.10.2014 № 284-ФЗ) (Утратил силу - Федеральный закон от 03.08.2018 № 334-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 04.10.2014 № 284-ФЗ) (Утратил силу - Федеральный закон от 03.08.2018 № 334-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ) (Утратил силу - Федеральный закон от 03.08.2018 № 334-ФЗ)\n\nНалоговая база в отношении земельного участка за налоговый период 2023 года определяется как его кадастровая стоимость, внесенная в Единый государственный реестр недвижимости и подлежащая применению с 1 января 2022 года с учетом особенностей, предусмотренных настоящей статьей, в случае, если кадастровая стоимость такого земельного участка, внесенная в Единый государственный реестр недвижимости и подлежащая применению с 1 января 2023 года, превышает кадастровую стоимость такого земельного участка, внесенную в Единый государственный реестр недвижимости и подлежащую применению с 1 января 2022 года, за исключением случаев, если кадастровая стоимость соответствующего земельного участка увеличилась вследствие изменения его характеристик. (Дополнение абзацем - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\n11. Изменение кадастровой стоимости земельного участка в течение налогового периода не учитывается при определении налоговой базы в этом и предыдущих налоговых периодах, если иное не предусмотрено законодательством Российской Федерации, регулирующим проведение государственной кадастровой оценки, и настоящим пунктом.\n\nВ случае изменения кадастровой стоимости земельного участка вследствие установления его рыночной стоимости сведения об измененной кадастровой стоимости, внесенные в Единый государственный реестр недвижимости, учитываются при определении налоговой базы начиная с даты начала применения для целей налогообложения сведений об изменяемой кадастровой стоимости.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 334-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nДля определения налоговой базы в соответствии с настоящим пунктом налогоплательщик представляет в налоговый орган по своему выбору уведомление о наличии на земельном участке жилищного фонда и (или) объектов инженерной инфраструктуры жилищно-коммунального комплекса, о площади части земельного участка, приходящейся на объект недвижимого имущества, не относящийся к жилищному фонду и (или) к объектам инженерной инфраструктуры жилищно-коммунального комплекса (далее в настоящем пункте - уведомление), с приложением предусмотренных законодательством Российской Федерации документов, подтверждающих наличие на земельном участке жилищного фонда и (или) объектов инженерной инфраструктуры жилищно-коммунального комплекса, а также площадь части земельного участка, приходящейся на объект недвижимого имущества, не относящийся к жилищному фонду и (или) объектам инженерной инфраструктуры жилищно-коммунального комплекса. Уведомление и указанные документы могут быть представлены в налоговый орган налогоплательщиками - физическими лицами через многофункциональный центр предоставления государственных и муниципальных услуг.\n\nУведомление рассматривается налоговым органом в течение 30 дней со дня его получения. В случае направления налоговым органом запроса в соответствии с пунктом 13 статьи 85 настоящего Кодекса в связи с отсутствием сведений, необходимых для рассмотрения уведомления, руководитель (заместитель руководителя) налогового органа вправе продлить срок рассмотрения такого уведомления не более чем на 30 дней, уведомив об этом налогоплательщика.\n\nПри выявлении оснований, препятствующих определению налоговой базы в соответствии с уведомлением, налоговый орган информирует об этом налогоплательщика.\n\nВ случае, если налогоплательщик не представил в налоговый орган уведомление, определение налоговой базы в соответствии с настоящим пунктом осуществляется на основании сведений о наличии на земельном участке жилищного фонда и (или) объектов инженерной инфраструктуры жилищно-коммунального комплекса, о площади части земельного участка, приходящейся на объект недвижимого имущества, не относящийся к жилищному фонду и (или) к объектам инженерной инфраструктуры жилищно-коммунального комплекса, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами.\n\nФорма уведомления, порядок ее заполнения, формат представления уведомления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Пункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\n1) Героев Советского Союза, Героев Российской Федерации, полных кавалеров ордена Славы;\n\n2) инвалидов I и II групп инвалидности; (В редакции Федерального закона от 04.10.2014 № 284-ФЗ)\n\n3) инвалидов с детства, детей-инвалидов; (В редакции Федерального закона от 03.08.2018 № 334-ФЗ)\n\n4) ветеранов и инвалидов Великой Отечественной войны, а также ветеранов и инвалидов боевых действий;\n\n5) физических лиц, имеющих право на получение социальной поддержки в соответствии с Законом Российской Федерации \"О социальной защите граждан, подвергшихся воздействию радиации вследствие катастрофы на Чернобыльской АЭС\" (в редакции Закона Российской Федерации от 18 июня 1992 года № 3061-I), в соответствии с Федеральным законом от 26 ноября 1998 года № 175-ФЗ \"О социальной защите граждан Российской Федерации, подвергшихся воздействию радиации вследствие аварии в 1957 году на производственном объединении \"Маяк\" и сбросов радиоактивных отходов в реку Теча\" и в соответствии с Федеральным законом от 10 января 2002 года № 2-ФЗ \"О социальных гарантиях гражданам, подвергшимся радиационному воздействию вследствие ядерных испытаний на Семипалатинском полигоне\";\n\n6) физических лиц, принимавших в составе подразделений особого риска непосредственное участие в испытаниях ядерного и термоядерного оружия, ликвидации аварий ядерных установок на средствах вооружения и военных объектах;\n\n7) физических лиц, получивших или перенесших лучевую болезнь или ставших инвалидами в результате испытаний, учений и иных работ, связанных с любыми видами ядерных установок, включая ядерное оружие и космическую технику;\n\n8) пенсионеров, получающих пенсии, назначаемые в порядке, установленном пенсионным законодательством, а также лиц, достигших возраста 60 и 55 лет (соответственно мужчины и женщины), которым в соответствии с законодательством Российской Федерации выплачивается ежемесячное пожизненное содержание; (Дополнение подпунктом - Федеральный закон от 28.12.2017 № 436-ФЗ)\n\n9) физических лиц, соответствующих условиям, необходимым для назначения пенсии в соответствии с законодательством Российской Федерации, действовавшим на 31 декабря 2018 года; (Дополнение подпунктом - Федеральный закон от 30.10.2018 № 378-ФЗ)\n\n10) физических лиц, имеющих трех и более несовершеннолетних детей. (Дополнение подпунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nУведомление о выбранном земельном участке, в отношении которого применяется налоговый вычет, представляется налогоплательщиком в налоговый орган по своему выбору не позднее 31 декабря года, являющегося налоговым периодом, начиная с которого в отношении указанного земельного участка применяется налоговый вычет. Уведомление о выбранном земельном участке может быть представлено в налоговый орган через многофункциональный центр предоставления государственных или муниципальных услуг. (В редакции федеральных законов от 15.04.2019 № 63-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nУведомление о выбранном земельном участке рассматривается налоговым органом в течение 30 дней со дня его получения. В случае направления налоговым органом запроса в соответствии с пунктом 13 статьи 85 настоящего Кодекса в связи с отсутствием сведений, необходимых для рассмотрения уведомления о выбранном земельном участке, руководитель (заместитель руководителя) налогового органа вправе продлить срок рассмотрения такого уведомления не более чем на 30 дней, уведомив об этом налогоплательщика. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nПри выявлении оснований, препятствующих применению налогового вычета в соответствии с уведомлением о выбранном земельном участке, налоговый орган информирует об этом налогоплательщика. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nПри непредставлении налогоплательщиком, имеющим право на применение налогового вычета, уведомления о выбранном земельном участке налоговый вычет предоставляется в отношении одного земельного участка с максимальной исчисленной суммой налога.\n\nФорма уведомления утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 28.12.2017 № 436-ФЗ)","article_title":"Статья 391. Порядок определения налоговой базы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d76d5a69c45450e61b267a25a4efece895a382de3a910050766a169371701b66"},{"code_id":"NK_RF_2","article_number":"392","version_date":"2000-07-31","article_text":"ся в общей собственности\n\n1. Налоговая база в отношении земельных участков, находящихся в общей долевой собственности, определяется для каждого из налогоплательщиков, являющихся собственниками данного земельного участка, пропорционально его доле в общей долевой собственности.\n\n2. Налоговая база в отношении земельных участков, находящихся в общей совместной собственности, определяется для каждого из налогоплательщиков, являющихся собственниками данного земельного участка, в равных долях.","article_title":"Статья 392. Особенности определения налоговой базы в отношении земельных участков, находящих","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"94da1598dd235adb0fd7b586ad0a955bf78f72dab256bb6b0e1e1cef0a9e3143"},{"code_id":"NK_RF_2","article_number":"393","version_date":"2000-07-31","article_text":"1. Налоговым периодом признается календарный год.","article_title":"Статья 393. Налоговый период. Отчетный период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"df7db53b1c65079aa069588bd1eee803ea383c2cb4631f0415ec8f2efc4346a0"},{"code_id":"NK_RF_2","article_number":"394","version_date":"2000-07-31","article_text":"1) 0,3 процента в отношении земельных участков:\n\nотнесенных к землям сельскохозяйственного назначения или к землям в составе зон сельскохозяйственного использования в населенных пунктах и используемых для сельскохозяйственного производства; (В редакции Федерального закона от 28.11.2009 № 283-ФЗ)\n\nзанятых жилищным фондом и (или) объектами инженерной инфраструктуры жилищно-коммунального комплекса (за исключением части земельного участка, приходящейся на объект недвижимого имущества, не относящийся к жилищному фонду и (или) к объектам инженерной инфраструктуры жилищно-коммунального комплекса) или приобретенных (предоставленных) для жилищного строительства, за исключением указанных в настоящем абзаце земельных участков, приобретенных (предоставленных) для индивидуального жилищного строительства, используемых в предпринимательской деятельности, и земельных участков, кадастровая стоимость каждого из которых превышает 300 миллионов рублей; (В редакции  федеральных законов от 24.07.2007 № 216-ФЗ, от 29.09.2019 № 325-ФЗ, от 31.07.2023 № 389-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nне используемых в предпринимательской деятельности, приобретенных (предоставленных) для ведения личного подсобного хозяйства, садоводства или огородничества, а также земельных участков общего назначения, предусмотренных Федеральным законом от 29 июля 2017 года № 217-ФЗ \"О ведении гражданами садоводства и огородничества для собственных нужд и о внесении изменений в отдельные законодательные акты Российской Федерации\", за исключением указанных в настоящем абзаце земельных участков, кадастровая стоимость каждого из которых превышает 300 миллионов рублей; (В редакции  федеральных законов от 15.04.2019 № 63-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nограниченных в обороте в соответствии с законодательством Российской Федерации, предоставленных для обеспечения обороны, безопасности и таможенных нужд; (Дополнение абзацем - Федеральный закон от 29.11.2012 № 202-ФЗ)\n\n2) 1,5 процента в отношении прочих земельных участков.","article_title":"Статья 394. Налоговая ставка","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89ea9b73a48bc0dbb1007f4bc59114dfb01c5efbffc0ce7df17b14a7897ede03"},{"code_id":"NK_RF_2","article_number":"395","version_date":"2000-07-31","article_text":"1) учреждения и органы уголовно-исполнительной системы - в отношении земельных участков, предоставленных для непосредственного выполнения возложенных на эти учреждения и органы функций; (В редакции Федерального закона от 29.05.2019 № 108-ФЗ)\n\n2) организации - в отношении земельных участков, занятых государственными автомобильными дорогами общего пользования;\n\n3) (Подпункт утратил силу - Федеральный закон от 29.11.2004 № 141-ФЗ)\n\n4) религиозные организации - в отношении принадлежащих им земельных участков, на которых расположены здания, строения и сооружения религиозного и благотворительного назначения, а также земельных участков, предназначенных для размещения указанных объектов; (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n5) общероссийские общественные организации инвалидов (в том числе созданные как союзы общественных организаций инвалидов), среди членов которых инвалиды и их законные представители составляют не менее 80 процентов, - в отношении земельных участков, используемых ими для осуществления уставной деятельности;\n\nорганизации, уставный капитал которых полностью состоит из вкладов указанных общероссийских общественных организаций инвалидов, если среднесписочная численность инвалидов среди их работников составляет не менее 50 процентов, а их доля в фонде оплаты труда - не менее 25 процентов, - в отношении земельных участков, используемых ими для производства и (или) реализации товаров (за исключением подакцизных товаров, минерального сырья и иных полезных ископаемых, а также иных товаров по перечню, утверждаемому Правительством Российской Федерации по согласованию с общероссийскими общественными организациями инвалидов), работ и услуг (за исключением брокерских и иных посреднических услуг);\n\nучреждения, единственными собственниками имущества которых являются указанные общероссийские общественные организации инвалидов, - в отношении земельных участков, используемых ими для достижения образовательных, культурных, лечебно-оздоровительных, физкультурно-спортивных, научных, информационных и иных целей социальной защиты и реабилитации инвалидов, а также для оказания правовой и иной помощи инвалидам, детям-инвалидам и их родителям;\n\n6) организации народных художественных промыслов - в отношении земельных участков, находящихся в местах традиционного бытования народных художественных промыслов и используемых для производства и реализации изделий народных художественных промыслов;\n\n7) физические лица, относящиеся к коренным малочисленным народам Севера, Сибири и Дальнего Востока Российской Федерации, а также общины таких народов - в отношении земельных участков, расположенных в местах их традиционного проживания и традиционной хозяйственной деятельности в соответствии с перечнем таких мест, утвержденным Правительством Российской Федерации; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n8) (Подпункт утратил силу - Федеральный закон от 29.11.2004 № 141-ФЗ)\n\n9) организации - резиденты особой экономической зоны, за исключением организаций, указанных в подпункте 11 настоящего пункта, - в отношении земельных участков, расположенных на территории особой экономической зоны, сроком на пять лет с месяца возникновения права собственности на каждый земельный участок. (Дополнение подпунктом - Федеральный закон от 22.07.2005 № 117-ФЗ) (В редакции федеральных законов от 03.06.2006 № 75-ФЗ, от 07.11.2011 № 305-ФЗ, от 30.11.2011 № 365-ФЗ, от 28.12.2017 № 436-ФЗ, от 29.11.2021 № 381-ФЗ)\n\nВ случае исключения резидента из единого реестра резидентов Особой экономической зоны в Калининградской области до получения им свидетельства о выполнении условий инвестиционной декларации резидент обязан исчислить сумму налога в отношении земельных участков, к которым была применена налоговая льгота, указанная в настоящем подпункте, за весь период применения такой льготы. (Дополнение абзацем - Федеральный закон от 29.11.2021 № 381-ФЗ)\n\nИсчисленная сумма налога подлежит уплате резидентом по истечении отчетного или налогового периода, в котором он был исключен из единого реестра резидентов Особой экономической зоны в Калининградской области, не позднее сроков, установленных для уплаты авансовых платежей по налогу за отчетный период или налога за налоговый период в соответствии со статьей 397 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 381-ФЗ)\n\n10) организации, признаваемые управляющими компаниями в соответствии с Федеральным законом \"Об инновационном центре \"Сколково\", - в отношении земельных участков, входящих в состав территории инновационного центра \"Сколково\" и предоставленных (приобретенных) для непосредственного выполнения возложенных на эти организации функций в соответствии с указанным Федеральным законом; (Дополнение подпунктом - Федеральный закон от 28.09.2010 № 243-ФЗ) (В редакции Федерального закона от 28.11.2011 № 339-ФЗ)\n\n11) судостроительные организации, имеющие статус резидента промышленно-производственной особой экономической зоны, - в отношении земельных участков, занятых принадлежащими им на праве собственности и используемыми в целях строительства и ремонта судов зданиями, строениями, сооружениями производственного назначения, с даты регистрации таких организаций в качестве резидента особой экономической зоны сроком на десять лет; (Дополнение подпунктом - Федеральный закон от 07.11.2011 № 305-ФЗ)\n\n12) организации - участники свободной экономической зоны на территориях Республики Крым и города федерального значения Севастополя - в отношении земельных участков, расположенных на территории свободной экономической зоны и используемых в целях выполнения договора об условиях деятельности в свободной экономической зоне, сроком на три года с месяца возникновения права собственности на каждый земельный участок. В случае расторжения договора об условиях деятельности в свободной экономической зоне по решению суда сумма налога подлежит исчислению и уплате в бюджет. Исчисление налога производится без учета применения налоговой льготы, предусмотренной настоящим подпунктом, за весь период реализации инвестиционного проекта в свободной экономической зоне. Исчисленная сумма налога подлежит уплате по истечении отчетного или налогового периода, в котором был расторгнут договор об условиях деятельности в свободной экономической зоне, не позднее сроков, установленных для уплаты авансовых платежей по налогу за отчетный период или налога за налоговый период; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 379-ФЗ) (В редакции  федеральных законов от 03.08.2018 № 297-ФЗ, от 24.06.2023 № 268-ФЗ)\n\n13) организации, признаваемые фондами в соответствии с Федеральным законом от 29 июля 2017 года № 216-ФЗ \"Об инновационных научно-технологических центрах и о внесении изменений в отдельные законодательные акты Российской Федерации\", - в отношении земельных участков, входящих в состав территории инновационного научно-технологического центра; (Дополнение подпунктом - Федеральный закон от 30.10.2018 № 373-ФЗ)\n\n14) организации - участники свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях - в отношении земельных участков, расположенных в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях и используемых в целях выполнения договора об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, сроком на три года с месяца возникновения права собственности на каждый земельный участок. В случае расторжения договора об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области в одностороннем порядке (в свободной экономической зоне на прилегающих территориях - по соглашению сторон или по решению суда) в соответствии с Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\" сумма налога подлежит исчислению и уплате в бюджет. Исчисление налога производится без учета применения налоговой льготы, предусмотренной настоящим подпунктом, за весь период реализации инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях. Исчисленная сумма налога подлежит уплате по истечении отчетного или налогового периода, в котором был расторгнут указанный договор, не позднее сроков, установленных для уплаты авансовых платежей по налогу за отчетный период или налога за налоговый период. (Дополнение подпунктом - Федеральный закон от 24.06.2023 № 268-ФЗ) (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)","article_title":"Статья 395. Налоговые льготы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"710d11da0d70e26870d299ccae261baab32b1f0fe7e947a7e9c64b089c316fd8"},{"code_id":"NK_RF_2","article_number":"396","version_date":"2000-07-31","article_text":"Налогоплательщики-организации исчисляют сумму налога (сумму авансового платежа по налогу) самостоятельно.\n\nСумма налога, подлежащая уплате налогоплательщиками - физическими лицами, исчисляется налоговыми органами.\n\n(Пункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nЕсли возникновение права собственности (постоянного (бессрочного) пользования, пожизненного наследуемого владения) на земельный участок произошло до 15-го числа соответствующего месяца включительно или прекращение указанного права произошло после 15-го числа соответствующего месяца, за полный месяц принимается месяц возникновения (прекращения) указанного права. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nЕсли возникновение права собственности (постоянного (бессрочного) пользования, пожизненного наследуемого владения) на земельный участок произошло после 15-го числа соответствующего месяца или прекращение указанного права произошло до 15-го числа соответствующего месяца включительно, месяц возникновения (прекращения) указанного права не учитывается при определении коэффициента, указанного в настоящем пункте. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 04.10.2014 № 284-ФЗ)\n\nного значения Москвы, Санкт-Петербурга и Севастополя, представительный орган федеральной территории \"Сириус\") при установлении налога вправе предусмотреть для отдельных категорий налогоплательщиков право не исчислять и не уплачивать авансовые платежи по налогу в течение налогового периода. (В редакции  федеральных законов от 29.11.2014 № 379-ФЗ, от 11.06.2021 № 199-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nПредставление заявления о предоставлении налоговой льготы, подтверждение права налогоплательщика на налоговую льготу, рассмотрение налоговым органом такого заявления, направление налогоплательщику уведомления о предоставлении налоговой льготы либо сообщения об отказе от предоставления налоговой льготы осуществляются в порядке, аналогичном порядку, предусмотренному пунктом 3 статьи 3611 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 30.09.2017 № 286-ФЗ) (В редакции федеральных законов от 15.04.2019 № 63-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nФормы заявлений налогоплательщиков - организаций и физических лиц о предоставлении налоговых льгот, порядок их заполнения, форматы представления таких заявлений в электронной форме, формы уведомления о предоставлении налоговой льготы, сообщения об отказе от предоставления налоговой льготы утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 30.09.2017 № 286-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nВ случае, если налогоплательщик, имеющий право на налоговую льготу, в том числе в виде налогового вычета, не представил в налоговый орган заявление о предоставлении налоговой льготы или не сообщил об отказе от применения налоговой льготы, налоговая льгота предоставляется на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами, начиная с налогового периода, в котором у налогоплательщика возникло право на налоговую льготу. (Дополнение абзацем - Федеральный закон от 15.04.2019 № 63-ФЗ) (В редакции федеральных законов от 23.11.2020 № 374-ФЗ, от 02.07.2021 № 305-ФЗ)\n\nВ случае возникновения (прекращения) у налогоплательщиков в течение налогового (отчетного) периода права на налоговую льготу исчисление суммы налога (суммы авансового платежа по налогу) в отношении земельного участка, по которому предоставляется налоговая льгота, производится с учетом коэффициента, определяемого как отношение числа полных месяцев, в течение которых отсутствует налоговая льгота, к числу календарных месяцев в налоговом (отчетном) периоде. При этом месяц возникновения права на налоговую льготу, а также месяц прекращения указанного права принимается за полный месяц. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nВ отношении земельных участков, приобретенных (предоставленных) в собственность физическими и юридическими лицами на условиях осуществления на них жилищного строительства (за исключением индивидуального жилищного строительства, осуществляемого физическими лицами, и жилищного строительства, осуществляемого на основании договора о комплексном развитии территории, заключенного в соответствии с законодательством Российской Федерации о градостроительной деятельности), исчисление суммы налога (суммы авансовых платежей по налогу) производится с учетом коэффициента 4 в течение периода, превышающего три года с даты государственной регистрации прав на данные земельные участки, вплоть до даты государственной регистрации прав на построенные жилой дом (многоквартирный дом) или на любое помещение в указанном жилом доме (многоквартирном доме). (В редакции  федеральных законов от 28.11.2009 № 283-ФЗ, от 27.07.2010 № 229-ФЗ, от 04.11.2014 № 347-ФЗ, от 29.11.2014 № 382-ФЗ, от 02.07.2021 № 305-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nВ случае, если разрешенное использование земельных участков, предусматривающее жилищное строительство (за исключением индивидуального жилищного строительства, осуществляемого физическими лицами, и жилищного строительства, осуществляемого на основании договора о комплексном развитии территории, заключенного в соответствии с законодательством Российской Федерации о градостроительной деятельности), установлено после государственной регистрации прав на данные земельные участки, исчисление суммы налога (суммы авансовых платежей по налогу) производится в порядке, аналогичном порядку, предусмотренному абзацами первым и вторым настоящего пункта, начиная с 1-го числа месяца, следующего за месяцем внесения в Единый государственный реестр недвижимости сведений об указанном разрешенном использовании данных земельных участков. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 24.07.2007 № 216-ФЗ)\n\nВ случае, если разрешенное использование земельных участков, предусматривающее индивидуальное жилищное строительство, установлено после государственной регистрации прав на данные земельные участки, исчисление суммы налога производится в порядке, аналогичном порядку, предусмотренному абзацем первым настоящего пункта, начиная с 1-го числа месяца, следующего за месяцем внесения в Единый государственный реестр недвижимости сведений об указанном разрешенном использовании данных земельных участков. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПоложения настоящего пункта не применяются при исчислении налога с учетом положений пунктов 71, 72, 15, 16 и 161 настоящей статьи. (В редакции  федеральных законов от 29.11.2021 № 382-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nПредставление заявления о перерасчете суммы ранее исчисленного налога, рассмотрение налоговым органом такого заявления, направление налогоплательщику - физическому лицу уведомления о перерасчете суммы ранее исчисленного налога, сообщения об отказе в перерасчете суммы ранее исчисленного налога, налогового уведомления в связи с перерасчетом суммы ранее исчисленного налога осуществляются в порядке, аналогичном порядку, предусмотренному пунктом 8 статьи 362 настоящего Кодекса.\n\nФорма заявления о перерасчете суммы ранее исчисленного налога, порядок ее заполнения, формат представления такого заявления в электронной форме, формы уведомления о перерасчете суммы ранее исчисленного налога, сообщения об отказе в перерасчете суммы ранее исчисленного налога утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если налогоплательщик - физическое лицо не представил в налоговый орган заявление о перерасчете суммы ранее исчисленного налога, перерасчет суммы ранее исчисленного налога осуществляется на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами, начиная с налогового периода, в котором возникло основание для данного перерасчета, если иное не предусмотрено настоящим Кодексом.\n\nВ случае, если заявление о перерасчете суммы ранее исчисленного налога представлено при наличии оснований, предусмотренных пунктом 10 настоящей статьи и пунктами 2, 61 статьи 391 настоящего Кодекса, рассмотрение такого заявления осуществляется в соответствии с настоящим пунктом без учета положений пункта 10 настоящей статьи и пунктов 2, 61 статьи 391 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n1) сведения о неиспользовании для сельскохозяйственного производства земельного участка, принадлежащего организации или физическому лицу на праве собственности, праве постоянного (бессрочного) пользования или праве пожизненного наследуемого владения, отнесенного к землям сельскохозяйственного назначения или к землям в составе зон сельскохозяйственного использования в населенных пунктах (за исключением земельных участков, указанных в абзацах четвертом и пятом подпункта 1 пункта 1 статьи 394 настоящего Кодекса); (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n2) сведения об использовании не по целевому назначению земельного участка, принадлежащего организации или физическому лицу на праве собственности, праве постоянного (бессрочного) пользования или праве пожизненного наследуемого владения, предназначенного для индивидуального жилищного строительства, ведения личного подсобного хозяйства, садоводства или огородничества, в случае выявления факта использования такого земельного участка в предпринимательской деятельности; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n3) о фактах устранения указанных в подпунктах 1 и 2 настоящего пункта нарушений обязательных требований к использованию и охране объектов земельных отношений либо об отмене документов, на основании которых сформированы указанные сведения. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nСведения, предусмотренные настоящим пунктом, представляются в налоговые органы органами, осуществляющими государственный земельный надзор, а также органами, осуществляющими муниципальный земельный контроль, ежегодно до 1 марта года, следующего за годом, за который представляются такие сведения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nФорма, порядок ее заполнения, формат и порядок представления сведений, предусмотренных настоящим пунктом, в электронной форме, перечень документов, в соответствии с которыми формируются указанные сведения, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с федеральными органами исполнительной власти, уполномоченными Правительством Российской Федерации на осуществление федерального государственного земельного контроля (надзора). (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nСведения, предусмотренные настоящим пунктом, представляются также органами, осуществляющими государственный земельный надзор, органами, осуществляющими муниципальный земельный контроль, в налоговый орган по его запросу в течение пяти дней со дня получения соответствующего запроса. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nСведения, предусмотренные настоящим пунктом, представляются в налоговые органы бесплатно.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nФорма, порядок ее заполнения, формат и порядок представления сведений, предусмотренных настоящим пунктом, в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nСведения, предусмотренные настоящим пунктом, представляются также уполномоченным органом исполнительной власти субъекта Российской Федерации или находящимся в его ведении учреждением, которые в соответствии с законодательством субъекта Российской Федерации осуществляют функции в сфере социальной защиты населения, в налоговый орган по его запросу в течение пяти дней со дня получения соответствующего запроса.\n\nСведения, предусмотренные настоящим пунктом, представляются в налоговые органы бесплатно.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nФорма представления сведений, предусмотренных настоящим пунктом, порядок ее заполнения, формат и порядок представления таких сведений утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nСведения, предусмотренные настоящим пунктом, представляются также органом или иным лицом, уполномоченными федеральным органом исполнительной власти, федеральным государственным органом, в которых федеральными законами предусмотрена военная служба (приравненная к ней служба), федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела, федеральным органом исполнительной власти, осуществляющим управление государственным резервом, федеральным органом исполнительной власти, осуществляющим функции по контролю и надзору в сфере обеспечения санитарно-эпидемиологического благополучия населения, в налоговый орган по его запросу в течение пяти дней со дня получения соответствующего запроса. (В редакции  федеральных законов от 29.11.2021 № 382-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nСведения, предусмотренные настоящим пунктом, представляются в налоговые органы бесплатно.\n\nПоложения настоящего пункта не распространяются на органы федеральной службы безопасности и федеральный орган исполнительной власти, уполномоченный на решение задач в области защиты населения и территорий от чрезвычайных ситуаций.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nдату выдачи ими разрешения на строительство жилых домов (многоквартирных домов) на земельных участках, приобретенных (предоставленных) в собственность физическими и (или) юридическими лицами для осуществления жилищного строительства на основани\n\nи договора о комплексном развитии территории, заключенного в соответствии с законодательством Российской Федерации о градостроительной деятельности;\n\nсведения об изменении даты выдачи разрешения на строительство, указанного в абзаце втором настоящего пункта, о прекращении действия такого разрешения на строительство.\n\nСведения, предусмотренные настоящим пунктом, представляются в налоговые органы органом или иным лицом, уполномоченными на выдачу разрешения на строительство жилых домов (многоквартирных домов) в соответствии с законодательством Российской Федерации о градостроительной деятельности, ежегодно до 1 марта года, следующего за годом, за который представляются указанные сведения.\n\nФорма, порядок ее заполнения, формат и порядок представления сведений, предусмотренных настоящим пунктом, в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nСведения, предусмотренные настоящим пунктом, представляются также органом или иным лицом, уполномоченными на выдачу разрешения на строительство жилых домов (многоквартирных домов) в соответствии с законодательством Российской Федерации о градостроительной деятельности, в налоговый орган по его запросу в течение пяти дней со дня получения соответствующего запроса.\n\nСведения, предусмотренные настоящим пунктом, представляются в налоговые органы бесплатно.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 396. Порядок исчисления налога и авансовых платежей по налогу","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f50a1758a720018af23edca75ea75495314458426917f250f6d401505df30ac7"},{"code_id":"NK_RF_2","article_number":"396.1","version_date":"2000-07-31","article_text":"1. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений вправе уменьшить сумму налога (авансового платежа по налогу), исчисленную им в соответствии со статьей 396 настоящего Кодекса в отношении земельных участков, используемых им при реализации инвестиционного проекта, предусмотренного соглашением о защите и поощрении капиталовложений, на сумму налогового вычета для СЗПК в порядке и на условиях, которые установлены настоящей статьей.\n\n2. Размер налогового вычета для СЗПК определяется суммой, отраженной в уведомлении о налоговом вычете для СЗПК применительно к налогу (авансовому платежу по налогу) в отношении соответствующего объекта налогообложения, которое представлено в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в соответствии со статьей 2518 настоящего Кодекса (далее в настоящей статье - уведомление).\n\n3. Налоговый вычет для СЗПК применяется начиная с налогового периода, следующего за годом представления уведомления.\n\n4. В результате применения налогового вычета для СЗПК сумма налога (авансового платежа по налогу) может быть снижена до нуля.\n\nНеиспользованная часть налогового вычета для СЗПК учитывается при исчислении суммы налога (авансового платежа по налогу) в последующие налоговые (отчетные) периоды, если применение налогового вычета в этих последующих налоговых (отчетных) периодах предусмотрено уведомлением применительно к налогу (авансовому платежу по налогу) в отношении соответствующего объекта налогообложения.\n\n5. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений имеет право уменьшать сумму налога (авансового платежа по налогу) до наступления хотя бы одного из следующих оснований:\n\n1) общая сумма налога (авансового платежа по налогу), не уплаченная в связи с применением налогового вычета для СЗПК, стала равна сумме, отраженной в уведомлении применительно к налогу в отношении соответствующего объекта налогообложения;\n\n2) истек срок применения налогового вычета для СЗПК, указанный в уведомлении применительно к налогу в отношении соответствующего объекта налогообложения;\n\n3) налогоплательщик утратил статус участника соглашения о защите и поощрении капиталовложений.\n\n6. В случае, если в уведомлении указаны налоговые вычеты для СЗПК с различными сроками их применения в отношении соответствующего объекта налогообложения, в первую очередь сумма налога (авансового платежа по налогу) уменьшается на суммы налоговых вычетов для СЗПК с меньшим сроком применения.\n\n7. Если по одному соглашению о защите и поощрении капиталовложений представляется несколько уведомлений в отношении соответствующего объекта налогообложения, уменьшение суммы налога (авансового платежа по налогу) осуществляется в хронологическом порядке представления таких уведомлений.\n\n8. Для применения налогового вычета, предусмотренного настоящей статьей, налогоплательщик обязан обеспечить ведение раздельного учета земельных участков, используемых при реализации инвестиционного проекта в рамках каждого соглашения о защите и поощрении капиталовложений, и земельных участков, используемых при осуществлении иной деятельности, в порядке, закрепленном в учетной политике организации.\n\n(Дополнение статьей - Федеральный закон от 28.06.2022 № 225-ФЗ)","article_title":"Статья 396.1. Налоговый вычет для налогоплательщиков - участников соглашений о защите и поощрении капиталовложений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4cb6397c269e660362ff904648a08ebc1fc2001f72860870cf04b56bbb3427d6"},{"code_id":"NK_RF_2","article_number":"397","version_date":"2000-07-31","article_text":"Налог подлежит уплате налогоплательщиками-организациями в срок не позднее 28 февраля года, следующего за истекшим налоговым периодом. Авансовые платежи по налогу подлежат уплате налогоплательщиками-организациями в срок не позднее 28-го числа месяца, следующего за истекшим отчетным периодом. (В редакции  федеральных законов от 29.09.2019 № 325-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nНалог подлежит уплате налогоплательщиками - физическими лицами в срок не позднее 1 декабря года, следующего за истекшим налоговым периодом, если иное не предусмотрено настоящим пунктом. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции  федеральных законов от 02.12.2013 № 334-ФЗ, от 23.11.2015 № 320-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nНалог, исчисленный по результатам перерасчета суммы ранее исчисленного налога, подлежит уплате налогоплательщиками - физическими лицами в срок не позднее 28-го числа третьего месяца, следующего за месяцем, в котором сформировано налоговое уведомление в связи с данным перерасчетом. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nНаправление налогового уведомления допускается не более чем за три налоговых периода, предшествующих календарному году его направления. (Дополнение абзацем - Федеральный закон от 28.11.2009 № 283-ФЗ)\n\nНалогоплательщики, указанные в абзаце первом настоящего пункта, уплачивают налог не более чем за три налоговых периода, предшествующих календарному году направления налогового уведомления, указанного в абзаце втором настоящего пункта. (Дополнение абзацем - Федеральный закон от 28.11.2009 № 283-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 28.11.2009 № 283-ФЗ) (Утратил силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)","article_title":"Статья 397. Порядок и сроки уплаты налога и авансовых платежей по налогу","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"278807fa32ab083237e7b12c38d605a556cd7d8d59b4ce63a272bb661283007e"},{"code_id":"NK_RF_2","article_number":"398","version_date":"2000-07-31","article_text":"(Статья утратила силу  - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nГЛАВА 32. НАЛОГ НА ИМУЩЕСТВО ФИЗИЧЕСКИХ ЛИЦ\n\n(Дополнение главой - Федеральный закон от 04.10.2014 № 284-ФЗ)","article_title":"Статья 398. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a092ec0f9e0faccf9306c86ea36cb067d1850f9c8e10d747bbd61031e5ec96b"},{"code_id":"NK_RF_2","article_number":"399","version_date":"2000-07-31","article_text":"1. Налог на имущество физических лиц (далее в настоящей главе - налог) устанавливается настоящим Кодексом и нормативными правовыми актами представительных органов муниципальных образований, вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и нормативными правовыми актами представительных органов муниципальных образований и обязателен к уплате на территориях этих муниципальных образований.\n\nВ городах федерального значения Москве, Санкт-Петербурге и Севастополе налог устанавливается настоящим Кодексом и законами указанных субъектов Российской Федерации, вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и законами указанных субъектов Российской Федерации и обязателен к уплате на территориях этих субъектов Российской Федерации.\n\nВ федеральной территории \"Сириус\" налог устанавливается настоящим Кодексом и нормативными правовыми актами представительного органа федеральной территории \"Сириус\", вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и нормативными правовыми актами представительного органа федеральной территории \"Сириус\" и обязателен к уплате в федеральной территории \"Сириус\". (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\nПри установлении налога нормативными правовыми актами представительных органов муниципальных образований (законами городов федерального значения Москвы, Санкт-Петербурга и Севастополя, нормативными правовыми актами представительного органа федеральной территории \"Сириус\") могут также устанавливаться налоговые льготы, не предусмотренные настоящей главой, основания и порядок их применения налогоплательщиками. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)","article_title":"Статья 399. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81ea5c6133d314f1bbec8763317d944043642061aff98ffc21d9d5963492966e"},{"code_id":"NK_RF_2","article_number":"400","version_date":"2000-07-31","article_text":"Налогоплательщиками налога (далее в настоящей главе - налогоплательщики) признаются физические лица, обладающие правом собственности на имущество, признаваемое объектом налогообложения в соответствии со статьей 401 настоящего Кодекса.","article_title":"Статья 400. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ac9af1423f710a1f42e55464457d55c30329f1a4a65eda44adcb64cdff695ac"},{"code_id":"NK_RF_2","article_number":"401","version_date":"2000-07-31","article_text":"1) жилой дом;\n\n2) квартира, комната; (В редакции Федерального закона от 30.09.2017 № 286-ФЗ)\n\n3) гараж, машино-место;\n\n4) единый недвижимый комплекс;\n\n5) объект незавершенного строительства;\n\n6) иные здание, строение, сооружение, помещение.","article_title":"Статья 401. Объект налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e0d7b9d857b4f74af9f193130a7f296f747737455a24755227cacf06cd07403"},{"code_id":"NK_RF_2","article_number":"402","version_date":"2000-07-31","article_text":"(Статья утратила силу  - Федеральный закон от 23.11.2020 № 374-ФЗ)","article_title":"Статья 402. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22d9ff2fe6e8f6a492bc6419860925b8b6c09e5670e37587038303bb60ed1d14"},{"code_id":"NK_RF_2","article_number":"403","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nНалоговая база в отношении объекта налогообложения за налоговый период 2023 года определяется как его кадастровая стоимость, внесенная в Единый государственный реестр недвижимости и подлежащая применению с 1 января 2022 года с учетом особенностей, предусмотренных настоящей статьей, в случае, если кадастровая стоимость такого объекта налогообложения, внесенная в Единый государственный реестр недвижимости и подлежащая применению с 1 января 2023 года, превышает кадастровую стоимость такого объекта налогообложения, внесенную в Единый государственный реестр недвижимости и подлежащую применению с 1 января 2022 года, за исключением случаев, если кадастровая стоимость соответствующего объекта налогообложения увеличилась вследствие изменения его характеристик. (Дополнение абзацем - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\nИзменение кадастровой стоимости объекта налогообложения в течение налогового периода не учитывается при определении налоговой базы в этом и предыдущих налоговых периодах, если иное не предусмотрено законодательством Российской Федерации, регулирующим проведение государственной кадастровой оценки, и настоящим пунктом. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nАбзац. (Утратил силу  - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nВ случае изменения кадастровой стоимости объекта налогообложения вследствие установления его рыночной стоимости сведения об измененной кадастровой стоимости, внесенные в Единый государственный реестр недвижимости, учитываются при определении налоговой базы начиная с даты начала применения для целей налогообложения сведений об изменяемой кадастровой стоимости. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n(Пункт в редакции Федерального закона от 03.08.2018 № 334-ФЗ)\n\nНалоговый вычет, предусмотренный настоящим пунктом, предоставляется в отношении одного объекта налогообложения каждого вида (квартира, часть квартиры, комната, жилой дом, часть жилого дома) в порядке, аналогичном порядку, предусмотренному пунктами 6 и 7 статьи 407 настоящего Кодекса, в том числе в случае непредставления в налоговый орган соответствующего заявления, уведомления.\n\n(Дополнение пунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)","article_title":"Статья 403. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"acaf3a981cb7d02504effa807e26423346858e6b04519501ef0c8df0047e515d"},{"code_id":"NK_RF_2","article_number":"404","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 23.11.2020 № 374-ФЗ)","article_title":"Статья 404. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e7574d5f87c4f9df9ce3b9b5d59c49207656aa4fc1d7fbfb42d00fefbee8bb6f"},{"code_id":"NK_RF_2","article_number":"405","version_date":"2000-07-31","article_text":"Налоговым периодом признается календарный год.","article_title":"Статья 405. Налоговый период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27c27acc719a5f99ee4a14d968e27d895653031d5fb8439543902e3f3367186e"},{"code_id":"NK_RF_2","article_number":"406","version_date":"2000-07-31","article_text":"1) 0,1 процента в отношении:\n\nжилых домов, частей жилых домов, квартир, частей квартир, комнат; (В редакции Федерального закона от 03.08.2018 № 334-ФЗ)\n\nобъектов незавершенного строительства в случае, если проектируемым назначением таких объектов является жилой дом;\n\nединых недвижимых комплексов, в состав которых входит хотя бы один жилой дом; (В редакции Федерального закона от 30.09.2017 № 286-ФЗ)\n\nгаражей и машино-мест, в том числе расположенных в объектах налогообложения, указанных в подпункте 2 настоящего пункта; (В редакции Федерального закона от 03.08.2018 № 334-ФЗ)\n\nхозяйственных строений или сооружений, площадь каждого из которых не превышает 50 квадратных метров и которые расположены на земельных участках для ведения личного подсобного хозяйства, огородничества, садоводства или индивидуального жилищного строительства;\n\n(В редакции Федерального закона от 29.09.2019 № 321-ФЗ)\n\n2) 2 процентов в отношении объектов налогообложения, включенных в перечень, определяемый в соответствии с пунктом 7 статьи 3782 настоящего Кодекса, в отношении объектов налогообложения, предусмотренных абзацем вторым пункта 10 статьи 3782 настоящего Кодекса; (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n21) 2,5 процента в отношении объектов налогообложения, кадастровая стоимость каждого из которых превышает 300 миллионов рублей; (Дополнение подпунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n3) 0,5 процента в отношении прочих объектов налогообложения.\n\n1) кадастровой стоимости объекта налогообложения; (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n2) вида объекта налогообложения;\n\n3) места нахождения объекта налогообложения;\n\n4) (Подпункт утратил силу  - Федеральный закон от 29.09.2019 № 325-ФЗ)","article_title":"Статья 406. Налоговые ставки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"17142236d426970ff94d28737f7c46ba430d933acb603786f8704b00244f1612"},{"code_id":"NK_RF_2","article_number":"407","version_date":"2000-07-31","article_text":"1. С учетом положений настоящей статьи право на налоговую льготу имеют следующие категории налогоплательщиков:\n\n1) Герои Советского Союза и Герои Российской Федерации, а также лица, награжденные орденом Славы трех степеней;\n\n2) инвалиды I и II групп инвалидности;\n\n3) инвалиды с детства, дети-инвалиды; (В редакции Федерального закона от 03.08.2018 № 334-ФЗ)\n\n4) участники гражданской войны, Великой Отечественной войны, других боевых операций по защите СССР из числа военнослужащих, проходивших службу в воинских частях, штабах и учреждениях, входивших в состав действующей армии, и бывших партизан, а также ветераны боевых действий; (В редакции Федерального закона от 29.12.2015 № 396-ФЗ)\n\n5) лица вольнонаемного состава Советской Армии, Военно-Морского Флота, органов внутренних дел и государственной безопасности, занимавшие штатные должности в воинских частях, штабах и учреждениях, входивших в состав действующей армии в период Великой Отечественной войны, либо лица, находившиеся в этот период в городах, участие в обороне которых засчитывается этим лицам в выслугу лет для назначения пенсии на льготных условиях, установленных для военнослужащих частей действующей армии;\n\n6) лица, имеющие право на получение социальной поддержки в соответствии с Законом Российской Федерации от 15 мая 1991 года № 1244-I \"О социальной защите граждан, подвергшихся воздействию радиации вследствие катастрофы на Чернобыльской АЭС\", в соответствии с Федеральным законом от 26 ноября 1998 года № 175-ФЗ \"О социальной защите граждан Российской Федерации, подвергшихся воздействию радиации вследствие аварии в 1957 году на производственном объединении \"Маяк\" и сбросов радиоактивных отходов в реку Теча\" и Федеральным законом от 10 января 2002 года № 2-ФЗ \"О социальных гарантиях гражданам, подвергшимся радиационному воздействию вследствие ядерных испытаний на Семипалатинском полигоне\";\n\n7) военнослужащие, а также граждане, уволенные с военной службы по достижении предельного возраста пребывания на военной службе, состоянию здоровья или в связи с организационно-штатными мероприятиями, имеющие общую продолжительность военной службы 20 лет и более;\n\n8) лица, принимавшие непосредственное участие в составе подразделений особого риска в испытаниях ядерного и термоядерного оружия, ликвидации аварий ядерных установок на средствах вооружения и военных объектах;\n\n9) члены семей военнослужащих, потерявших кормильца, признаваемые таковыми в соответствии с Федеральным законом от 27 мая 1998 года № 76-ФЗ \"О статусе военнослужащих\"; (В редакции Федерального закона от 29.12.2015 № 396-ФЗ)\n\n91) лица, принимающие (принимавшие) участие в специальной военной операции:\n\nлица, проходящие службу в войсках национальной гвардии Российской Федерации и имеющие специальные звания полиции, сотрудники органов внутренних дел Российской Федерации;\n\nграждане, заключившие контракт о пребывании в добровольческом формировании (о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации) либо заключившие контракт (имеющие иные правоотношения) с организациями, содействующими выполнению задач, возложенных на Вооруженные Силы Российской Федерации;\n\n(Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n92) лица, выполняющие (выполнявшие) возложенные на них задачи на территориях Украины, Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области в период проведения специальной военной операции:\n\nсотрудники Следственного комитета Российской Федерации, федеральной противопожарной службы Государственной противопожарной службы, уголовно-исполнительной системы Российской Федерации, органов принудительного исполнения Российской Федерации;\n\nсотрудники органов внутренних дел Российской Федерации;\n\nпрокурорские работники;\n\n(Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n93) лица, проходящие службу в войсках национальной гвардии Российской Федерации и имеющие специальные звания полиции, сотрудники органов внутренних дел Российской Федерации, выполняющие (выполнявшие) задачи по оказанию содействия органам федеральной службы безопасности на участках, примыкающих к районам проведения специальной военной операции; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n94) члены семей:\n\nлиц, указанных в подпунктах 91 - 93 настоящего пункта;\n\nграждан, призванных на военную службу по мобилизации в Вооруженные Силы Российской Федерации;\n\nвоеннослужащих, принимающих (принимавших) участие в специальной военной операции;\n\nвоеннослужащих спасательных воинских формирований федерального органа исполнительной власти, уполномоченного на решение задач в области гражданской обороны, выполняющих (выполнявших) возложенные на них задачи на территориях Украины, Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области в период проведения специальной военной операции;\n\nвоеннослужащих органов федеральной службы безопасности, непосредственно выполняющих (выполнявших) задачи по обеспечению безопасности Российской Федерации на участках, примыкающих к районам проведения специальной военной операции;\n\nвоеннослужащих войск национальной гвардии Российской Федерации, выполняющих (выполнявших) задачи по оказанию содействия органам федеральной службы безопасности на участках, примыкающих к районам проведения специальной военной операции;\n\nвоеннослужащих органов федеральной службы безопасности, органов государственной охраны, проходящих военную службу по контракту в воинских частях, органах, организациях, учреждениях и подразделениях, дислоцированных (расположенных) на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области, либо направленных (командированных) на срок не менее трех месяцев для временного исполнения обязанностей по вакантным воинским должностям в этих воинских частях, органах, организациях, учреждениях и подразделениях;\n\n(Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n95) члены семей:\n\nлиц, указанных в подпунктах 91 - 93 настоящего пункта, лиц, относящихся к ветеранам боевых действий в соответствии с подпунктами 23 и 9 пункта 1 статьи 3 Федерального закона от 12 января 1995 года № 5-ФЗ \"О ветеранах\", погибших (умерших) в период участия в специальной военной операции (при выполнении задач в период проведения специальной военной операции). К числу погибших относятся также лица, умершие до истечения одного года со дня их увольнения с военной службы (увольнения со службы, прекращения трудового договора или иных правоотношений), вследствие увечья (ранения, травмы, контузии) или заболевания, полученных ими в период проведения специальной военной операции (при выполнении задач в период проведения специальной военной операции);\n\nлиц, погибших (умерших) в связи с участием в боевых действиях в составе Вооруженных Сил Донецкой Народной Республики, Народной милиции Луганской Народной Республики, воинских формирований и органов Донецкой Народной Республики и Луганской Народной Республики начиная с 11 мая 2014 года;\n\n(Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n10) пенсионеры, получающие пенсии, назначаемые в порядке, установленном пенсионным законодательством, а также лица, достигшие возраста 60 и 55 лет (соответственно мужчины и женщины), которым в соответствии с законодательством Российской Федерации выплачивается ежемесячное пожизненное содержание;\n\n101) физические лица, соответствующие условиям, необходимым для назначения пенсии в соответствии с законодательством Российской Федерации, действовавшим на 31 декабря 2018 года; (Дополнение подпунктом - Федеральный закон от 30.10.2018 № 378-ФЗ)\n\n11) граждане, уволенные с военной службы или призывавшиеся на военные сборы, выполнявшие интернациональный долг в Афганистане и других странах, в которых велись боевые действия;\n\n12) физические лица, получившие или перенесшие лучевую болезнь или ставшие инвалидами в результате испытаний, учений и иных работ, связанных с любыми видами ядерных установок, включая ядерное оружие и космическую технику;\n\n13) родители и супруги военнослужащих и государственных служащих, погибших при исполнении служебных обязанностей;\n\n14) физические лица, осуществляющие профессиональную творческую деятельность, - в отношении специально оборудованных помещений, сооружений, используемых ими исключительно в качестве творческих мастерских, ателье, студий, а также жилых домов, квартир, комнат, используемых для организации открытых для посещения негосударственных музеев, галерей, библиотек, - на период такого их использования; (В редакции Федерального закона от 30.09.2017 № 286-ФЗ)\n\n15) физические лица - в отношении хозяйственных строений или сооружений, площадь каждого из которых не превышает 50 квадратных метров и которые расположены на земельных участках для ведения личного подсобного хозяйства, огородничества, садоводства или индивидуального жилищного строительства. (В редакции Федерального закона от 29.09.2019 № 321-ФЗ)\n\n12. Членам семей лиц, указанных в подпункте 94 пункта 1 настоящей статьи, соответствующая налоговая льгота предоставляется только за период участия указанных лиц в специальной военной операции (при выполнении задач в период проведения специальной военной операции).\n\nПериодом участия в специальной военной операции (при выполнении задач в период проведения специальной военной операции) для целей настоящей статьи признается налоговый период, в течение которого лицо было привлечено к участию в специальной военной операции (при выполнении задач в период проведения специальной военной операции) независимо от срока такого участия (выполнения задач) в течение налогового периода.\n\n(Дополнение пунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n2. Налоговая льгота предоставляется в размере подлежащей уплате налогоплательщиком суммы налога в отношении объекта налогообложения, находящегося в собственности налогоплательщика и не используемого налогоплательщиком в предпринимательской деятельности.\n\n3. При определении подлежащей уплате налогоплательщиком суммы налога налоговая льгота предоставляется в отношении одного объекта налогообложения каждого вида по выбору налогоплательщика вне зависимости от количества оснований для применения налоговых льгот.\n\n4. Налоговая льгота предоставляется в отношении следующих видов объектов налогообложения:\n\n1) квартира, часть квартиры или комната; (В редакции Федерального закона от 03.08.2018 № 334-ФЗ)\n\n2) жилой дом или часть жилого дома; (В редакции Федерального закона от 03.08.2018 № 334-ФЗ)\n\n3) помещение или сооружение, указанные в подпункте 14 пункта 1 настоящей статьи;\n\n4) хозяйственное строение или сооружение, указанные в подпункте 15 пункта 1 настоящей статьи;\n\n5) гараж или машино-место.\n\nПредставление заявления о предоставлении налоговой льготы, подтверждение права налогоплательщика на налоговую льготу, рассмотрение налоговым органом такого заявления, направление налогоплательщику уведомления о предоставлении налоговой льготы либо сообщения об отказе от предоставления налоговой льготы осуществляются в порядке, аналогичном порядку, предусмотренному пунктом 3 статьи 3611 настоящего Кодекса. (В редакции федеральных законов от 15.04.2019 № 63-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nФорма заявления о предоставлении налоговой льготы и порядок ее заполнения, формат представления такого заявления в электронной форме, формы уведомления о предоставлении налоговой льготы, сообщения об отказе от предоставления налоговой льготы утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nВ случае, если налогоплательщик, имеющий право на налоговую льготу, не представил в налоговый орган заявление о предоставлении налоговой льготы или не сообщил об отказе от применения налоговой льготы, налоговая льгота предоставляется на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами, начиная с налогового периода, в котором у налогоплательщика возникло право на налоговую льготу. (Дополнение абзацем - Федеральный закон от 15.04.2019 № 63-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.09.2017 № 286-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nУведомление о выбранном объекте налогообложения рассматривается налоговым органом в течение 30 дней со дня его получения. В случае направления налоговым органом запроса в соответствии с пунктом 13 статьи 85 настоящего Кодекса в связи с отсутствием сведений, необходимых для рассмотрения уведомления о выбранном объекте налогообложения, руководитель (заместитель руководителя) налогового органа вправе продлить срок рассмотрения такого уведомления не более чем на 30 дней, уведомив об этом налогоплательщика. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nПри выявлении оснований, препятствующих предоставлению налоговой льготы в соответствии с уведомлением о выбранном объекте налогообложения, налоговый орган информирует об этом налогоплательщика. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nПри непредставлении налогоплательщиком, имеющим право на налоговую льготу, уведомления о выбранном объекте налогообложения налоговая льгота предоставляется в отношении одного объекта налогообложения каждого вида с максимальной исчисленной суммой налога.\n\nФорма уведомления утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.","article_title":"Статья 407. Налоговые льготы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3104bf14a6ef2afc481bfe2e3a1bb2582ac65f4c30d6f9e65db0ef6b29946594"},{"code_id":"NK_RF_2","article_number":"408","version_date":"2000-07-31","article_text":"1. Сумма налога исчисляется налоговыми органами по истечении налогового периода отдельно по каждому объекту налогообложения как соответствующая налоговой ставке процентная доля налоговой базы с учетом особенностей, установленных настоящей статьей.\n\nВ случае, если документы, подтверждающие факт гибели или уничтожения объекта налогообложения, в налоговом органе отсутствуют, в том числе не представлены налогоплательщиком самостоятельно, налоговый орган по информации, указанной в заявлении налогоплательщика о гибели или уничтожении объекта налогообложения, запрашивает сведения, подтверждающие факт гибели или уничтожения объекта налогообложения, у органов и иных лиц, у которых имеются эти сведения.\n\nОрган или иное лицо, получившие запрос налогового органа о представлении сведений, подтверждающих факт гибели или уничтожения объекта налогообложения, исполняет указанный запрос в течение семи дней со дня его получения или в тот же срок сообщает в налоговый орган о причинах неисполнения запроса.\n\nНалоговый орган в течение трех дней со дня получения указанного сообщения обязан проинформировать налогоплательщика о неполучении по запросу сведений, подтверждающих факт гибели или уничтожения объекта налогообл\n\nожения, и о необходимости представления налогоплательщиком подтверждающих документов в налоговый орган.\n\nЗаявление о гибели или уничтожении объекта налогообложения рассматривается налоговым органом в течение 30 дней со дня его получения. В случае направления налоговым органом запроса, предусмотренного настоящим пунктом, руководитель (заместитель руководителя) налогового органа вправе продлить срок рассмотрения такого заявления не более чем на 30 дней, уведомив об этом налогоплательщика. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nПо результатам рассмотрения заявления о гибели или уничтожении объекта налогообложения налоговый орган направляет налогоплательщику способом, указанным в этом заявлении, уведомление о прекращении исчисления налога в связи с гибелью или уничтожением объекта налогообложения либо сообщение об отсутствии основания для прекращения исчисления налога в связи с гибелью или уничтожением объекта налогообложения. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nВ уведомлении о прекращении исчисления налога в связи с гибелью или уничтожением объекта налогообложения должны быть указаны основания прекращения исчисления налога, объекты налогообложения и период, начиная с которого исчисление налога прекращается. В сообщении об отсутствии основания для прекращения исчисления налога в связи с гибелью или уничтожением объекта налогообложения должны быть указаны основания для отказа в прекращении исчисления налога и объекты налогообложения. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nФорма заявления о гибели или уничтожении объекта налогообложения, порядок ее заполнения, формат представления такого заявления в электронной форме, формы уведомления о прекращении исчисления налога в связи с гибелью или уничтожением объекта налогообложения, сообщения об отсутствии основания для прекращения исчисления налога в связи с гибелью или уничтожением объекта налогообложения утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nВ случае, если налогоплательщик не представил в налоговый орган заявление о гибели или уничтожении объекта налогообложения, исчисление налога прекращается с 1-го числа месяца гибели или уничтожения такого объекта на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nВ случае, если объект налогообложения находится в общей совместной собственности, налог исчисляется в соответствии с пунктом 1 настоящей статьи с учетом положений пункта 8 настоящей статьи для каждого из участников совместной собственности в равных долях.\n\nЕсли возникновение права собственности на имущество произошло до 15-го числа соответствующего месяца включительно или прекращение права собственности на имущество произошло после 15-го числа соответствующего месяца, за полный месяц принимается месяц возникновения (прекращения) указанного права.\n\nЕсли возникновение права собственности на имущество произошло после 15-го числа соответствующего месяца или прекращение указанного права произошло до 15-го числа соответствующего месяца включительно, месяц возникновения (прекращения) указанного права не учитывается при определении коэффициента, указанного в настоящем пункте.\n\nАбзац. (Утратил силу - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nН = (Н1 - Н2) х К + Н2,\n\nгде Н - сумма налога, подлежащая уплате. В случае прекращения у налогоплательщика в течение налогового периода права собственности на указанный объект налогообложения, возникновения (прекращения) права на налоговую льготу, изменения доли в праве общей собственности на объект налогообложения исчисление суммы налога (Н) производится с учетом положений пунктов 4 - 6 настоящей статьи;\n\nН1 - сумма налога, исчисленная в порядке, предусмотренном пунктом 1 настоящей статьи, исходя из налоговой базы, определенной в соответствии со статьей 403 настоящего Кодекса, без учета положений пунктов 4 - 6 настоящей статьи;\n\nН2 - сумма налога, исчисленная исходя из инвентаризационной стоимости объекта налогообложения (без учета положений пунктов 4 - 6 настоящей статьи) за последний налоговый период, в котором в отношении такого объекта налогообложения применялся порядок определения налоговой базы исходя из его инвентаризационной стоимости; (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nК - коэффициент, равный:\n\n0,2 - применительно к первому налоговому периоду, в котором налоговая база определяется в соответствующем муниципальном образовании (городе федерального значения Москве, Санкт-Петербурге или Севастополе) в соответствии со статьей 403 настоящего Кодекса;\n\n0,4 - применительно ко второму налоговому периоду, в котором налоговая база определяется в соответствующем муниципальном образовании (городе федерального значения Москве, Санкт-Петербурге или Севастополе) в соответствии со статьей 403 настоящего Кодекса;\n\n0,6 - применительно к третьему налоговому периоду, в котором налоговая база определяется в соответствующем муниципальном образовании (городе федерального значения Москве, Санкт-Петербурге или Севастополе) в соответствии со статьей 403 настоящего Кодекса;\n\nабзац. (Утратил силу - Федеральный закон от 03.08.2018 № 334-ФЗ)\n\nНачиная с четвертого налогового периода, в котором налоговая база определяется в соответствующем муниципальном образовании (городе федерального значения Москве, Санкт-Петербурге или Севастополе) в соответствии со статьей 403 настоящего Кодекса, исчисление суммы налога производится в соответствии с настоящей статьей без учета положений настоящего пункта. (В редакции Федерального закона от 03.08.2018 № 334-ФЗ)\n\nПредусмотренная настоящим пунктом формула не применяется при исчислении налога в отношении объектов налогообложения, включенных в перечень, определяемый в соответствии с пунктом 7 статьи 3782 настоящего Кодекса, а также объектов налогообложения, предусмотренных абзацем вторым пункта 10 статьи 3782 настоящего Кодекса, за исключением гаражей и машино-мест, расположенных в таких объектах налогообложения. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 366-ФЗ) (В редакции федеральных законов от 03.08.2018 № 334-ФЗ; от 29.09.2019 № 325-ФЗ)\n\nПоложения настоящего пункта применяются при исчислении налога начиная с третьего налогового периода, в котором налоговая база определяется в соответствующем муниципальном образовании (городе федерального значения Москве, Санкт-Петербурге или Севастополе) в соответствии со статьей 403 настоящего Кодекса.\n\nПоложения настоящего пункта не применяются при исчислении налога с учетом положений пункта 51 настоящей статьи, а также при исчислении налога в отношении объектов налогообложения, включенных в перечень, определяемый в соответствии с пунктом 7 статьи 3782 настоящего Кодекса, а также объектов налогообложения, предусмотренных абзацем вторым пункта 10 статьи 3782 настоящего Кодекса, за исключением гаражей и машино-мест, расположенных в таких объектах налогообложения. (В редакции федеральных законов от 29.09.2019 № 325-ФЗ, от 29.11.2021 № 382-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 334-ФЗ)\n\nПоложения настоящего пункта не применяются при исчислении налога в отношении объектов налогообложения, включенных в перечень, определяемый в соответствии с пунктом 7 статьи 3782 настоящего Кодекса, а также объектов налогообложения, предусмотренных абзацем вторым пункта 10 статьи 3782 настоящего Кодекса, за исключением гаражей и машино-мест, расположенных в таких объектах налогообложения.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n10. Налогоплательщики при наличии предусмотренных законодательством о налогах и сборах оснований, влекущих перерасчет суммы ранее исчисленного налога, вправе представить в налоговый орган по своему выбору заявление о перерасчете суммы ранее исчисленного налога.\n\nПредставление заявления о перерасчете суммы ранее исчисленного налога, рассмотрение налоговым органом такого заявления, направление налогоплательщику уведомления о перерасчете суммы ранее исчисленного налога, сообщения об отказе в перерасчете суммы ранее исчисленного налога, налогового уведомления в связи с перерасчетом суммы ранее исчисленного налога осуществляются в порядке, аналогичном порядку, предусмотренному пунктом 8 статьи 362 настоящего Кодекса.\n\nФорма заявления о перерасчете суммы ранее исчисленного налога, порядок ее заполнения, формат представления такого заявления в электронной форме, формы уведомления о перерасчете суммы ранее исчисленного налога, сообщения об отказе в перерасчете суммы ранее исчисленного налога утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если налогоплательщик не представил в налоговый орган заявление о перерасчете суммы ранее исчисленного налога, перерасчет суммы ранее исчисленного налога осуществляется на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами, начиная с налогового периода, в котором возникло основание для данного перерасчета, если иное не предусмотрено настоящим Кодексом.\n\nВ случае, если заявление о перерасчете суммы ранее исчисленного налога представлено при наличии оснований, предусмотренных пунктом 21 настоящей статьи и пунктами 6, 7 статьи 407 настоящего Кодекса, рассмотрение такого заявления осуществляется в соответствии с настоящим пунктом без учета положений пункта 21 настоящей статьи и пунктов 6, 7 статьи 407 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n11. Орган или иное лицо, уполномоченные федеральным органом исполнительной власти, федеральным государственным органом, в которых федеральными законами предусмотрена военная служба (приравненная к ней служба), обязаны представлять в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, сведения о лицах, указанных в подпунктах 91 - 95 пункта 1 статьи 407 настоящего Кодекса, с учетом требований законодательства Российской Федерации о персональных данных, о государственной и иной охраняемой законом тайне ежегодно до 1 марта года, следующего за годом, за который представляются указанные сведения.\n\nФорма представления сведений, предусмотренных настоящим пунктом, порядок ее заполнения, формат и порядок представления указанных сведений утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с федеральными органами исполнительной власти, федеральными государственными органами, в которых федеральными законами предусмотрена военная служба (приравненная к ней служба).\n\nСведения, предусмотренные настоящим пунктом, представляются также органом или иным лицом, уполномоченными федеральным органом исполнительной власти, федеральным государственным органом, в которых федеральными законами предусмотрена военная служба (приравненная к ней служба), в налоговый орган по его запросу в течение пяти дней со дня получения соответствующего запроса.\n\nСведения, предусмотренные настоящим пунктом, представляются в налоговые органы бесплатно.\n\n(Дополнение пунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)","article_title":"Статья 408. Порядок исчисления суммы налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"db2ffa01720a80763be25fecece70f86f01062d590d376bd5cacfbea58ac7923"},{"code_id":"NK_RF_2","article_number":"409","version_date":"2000-07-31","article_text":"Налог, исчисленный по результатам перерасчета суммы ранее исчисленного налога, подлежит уплате налогоплательщиками в срок не позднее 28-го числа третьего месяца, следующего за месяцем, в котором сформировано налоговое уведомление в связи с данным перерасчетом. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nГЛАВА 33. ТОРГОВЫЙ СБОР\n\n(Дополнение главой - Федеральный закон от 29.11.2014 № 382-ФЗ)","article_title":"Статья 409. Порядок и сроки уплаты налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"505c604793dccf129ed41d35b8b41ad955cd29b57f6e2c09df179b1fa0c30668"},{"code_id":"NK_RF_2","article_number":"410","version_date":"2000-07-31","article_text":"1. Торговый сбор (далее в настоящей главе - сбор) устанавливается настоящим Кодексом и нормативными правовыми актами представительных органов муниципальных образований, вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и нормативными правовыми актами представительных органов муниципальных образований и обязателен к уплате на территориях этих муниципальных образований.\n\nВ городах федерального значения Москве, Санкт-Петербурге и Севастополе сбор устанавливается настоящим Кодексом и законами указанных субъектов Российской Федерации, вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и законами указанных субъектов Российской Федерации и обязателен к уплате на территориях этих субъектов Российской Федерации.\n\n2. Устанавливая сбор, представительные (законодательные) органы муниципальных образований (городов федерального значения Москвы, Санкт-Петербурга и Севастополя) определяют ставку сбора в пределах, установленных настоящей главой.\n\n3. Нормативными правовыми актами представительных органов муниципальных образований (законами городов федерального значения Москвы, Санкт-Петербурга и Севастополя) могут также устанавливаться льготы, основания и порядок их применения.","article_title":"Статья 410. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"18f2daa4aabd5857bfc98ad53e831c8b8abdcac5971b6e2fc5421bb1991e1bf5"},{"code_id":"NK_RF_2","article_number":"411","version_date":"2000-07-31","article_text":"1. Плательщиками сбора признаются организации и индивидуальные предприниматели, осуществляющие виды предпринимательской деятельности на территории муниципального образования (городов федерального значения Москвы, Санкт-Петербурга и Севастополя), в отношении которых нормативным правовым актом этого муниципального образования (законами городов федерального значения Москвы, Санкт-Петербурга и Севастополя) установлен указанный сбор, с использованием объектов движимого и (или) недвижимого имущества на территории этого муниципального образования (городов федерального значения Москвы, Санкт-Петербурга и Севастополя).\n\n2. От уплаты сбора по видам предпринимательской деятельности, в отношении которых нормативным правовым актом муниципального образования (законами городов федерального значения Москвы, Санкт-Петербурга и Севастополя) установлен сбор, освобождаются индивидуальные предприниматели, применяющие патентную систему налогообложения, и налогоплательщики, применяющие систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог), в отношении этих видов предпринимательской деятельности с использованием соответствующих объектов движимого или недвижимого имущества.","article_title":"Статья 411. Плательщики сбора","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4ffd441c315ea03d8a5d659acbc79a86905b2808c0b5e182d04198957233f47a"},{"code_id":"NK_RF_2","article_number":"412","version_date":"2000-07-31","article_text":"1. Объектом обложения сбором признается использование объекта движимого или недвижимого имущества (далее в настоящей главе - объект осуществления торговли) для осуществления плательщиком сбора вида предпринимательской деятельности, в отношении которого установлен сбор, хотя бы один раз в течение квартала.\n\n2. В целях настоящей главы используются следующие понятия:\n\n1) дата возникновения о\n\nбъекта обложения сбором - дата начала использования объекта осуществления торговли для осуществления вида предпринимательской деятельности, в отношении которого установлен сбор;\n\n2) дата прекращения объекта обложения сбором - дата прекращения использования объекта осуществления торговли для осуществления вида предпринимательской деятельности, в отношении которого установлен сбор.","article_title":"Статья 412. Объект обложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d81bca012828f8fc5d5ca0bfd02d80f1809bd6f4e6177e019ac3c8936d7efc7b"},{"code_id":"NK_RF_2","article_number":"413","version_date":"2000-07-31","article_text":"1. Сбор устанавливается в отношении осуществления торговой деятельности на объектах осуществления торговли.\n\n2. В целях настоящей главы к торговой деятельности относятся следующие виды торговли:\n\n1) торговля через объекты стационарной торговой сети, не имеющие торговых залов (за исключением объектов стационарной торговой сети, не имеющих торговых залов, являющихся автозаправочными станциями);\n\n2) торговля через объекты нестационарной торговой сети;\n\n3) торговля через объекты стационарной торговой сети, имеющие торговые залы;\n\n4) торговля, осуществляемая путем отпуска товаров со склада.\n\n3. В целях настоящей главы к торговой деятельности приравнивается деятельность по организации розничных рынков.\n\n4. В целях настоящей главы используются следующие понятия:\n\n1) объект осуществления торговли:\n\nв отношении видов торговли, указанных в пункте 2 настоящей статьи, - здание, сооружение, помещение, стационарный или нестационарный торговый объект или торговая точка, с использованием которых плательщиком осуществляется вид деятельности, в отношении которого установлен сбор;\n\nв отношении деятельности по организации розничных рынков - объект недвижимого имущества, с использованием которого управляющая рынком компания осуществляет указанную деятельность;\n\n2) торговля - вид предпринимательской деятельности, связанный с розничной, мелкооптовой и оптовой куплей-продажей товаров, осуществляемый через объекты стационарной торговой сети, нестационарной торговой сети, а также через товарные склады;\n\n3) деятельность по организации розничных рынков - деятельность управляющих рынком компаний, определяемая в соответствии с положениями Федерального закона от 30 декабря 2006 года № 271-ФЗ \"О розничных рынках и о внесении изменений в Трудовой кодекс Российской Федерации\".","article_title":"Статья 413. Виды предпринимательской деятельности, в отношении которых устанавливается сбор","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93f213465fe0a16a00b8604745e23e74480b42fd93bd66322ca9e27bf3a799e2"},{"code_id":"NK_RF_2","article_number":"414","version_date":"2000-07-31","article_text":"Периодом обложения сбором признается квартал.","article_title":"Статья 414. Период обложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8890f847a5d2f051e3e38e1db98cfef13d107881b8cae70cc8824f5a3f48df1c"},{"code_id":"NK_RF_2","article_number":"415","version_date":"2000-07-31","article_text":"1. Ставки сбора устанавливаются нормативными правовыми актами муниципальных образований (законами городов федерального значения Москвы, Санкт-Петербурга и Севастополя) в рублях за квартал в расчете на объект осуществления торговли или на его площадь.\n\nПри этом с учетом особенностей, предусмотренных настоящей статьей, ставка сбора не может превышать расчетную сумму налога, подлежащую уплате в соответствующем муниципальном образовании (городе федерального значения Москве, Санкт-Петербурге или Севастополе) в связи с применением патентной системы налогообложения на основании патента по соответствующему виду деятельности, выданного на три месяца.\n\n2. В целях определения предельных ставок сбора в соответствии с пунктом 1 настоящей статьи не учитываются ограничения для применения патентной системы налогообложения по деятельности в виде розничной торговли, установленные подпунктом 1 пункта 3 статьи 34643 настоящего Кодекса.","article_title":"Статья 415. Ставки сбора","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b16a198802e90a0d3e0c03856092f152af8dc603aa892955bc0dfc84cfa114e1"},{"code_id":"NK_RF_2","article_number":"416","version_date":"2000-07-31","article_text":"1. Постановка на учет, снятие с учета организации или индивидуального предпринимателя в качестве плательщика сбора в налоговом органе осуществляются на основании соответствующего уведомления плательщика сбора, представляемого им в налоговый орган, либо на основании информации, представленной указанным в пункте 2 статьи 418 настоящего Кодекса уполномоченным органом в налоговый орган.\n\nВ уведомлении указывается информация об объекте обложения сбором: вид предпринимательской деятельности; объект осуществления торговли, с использованием которого осуществляется (прекращается) указанная предпринимательская деятельность; характеристики (количество и (или) площадь) объекта осуществления торговли, необходимые для определения суммы сбора.\n\n2. Плательщик сбора представляет соответствующее уведомление не позднее пяти дней с даты возникновения объекта обложения сбором.\n\nОсуществление вида предпринимательской деятельности, в отношении которого установлен сбор, без направления указанного уведомления приравнивается к ведению деятельности организацией или индивидуальным предпринимателем без постановки на учет в налоговом органе.\n\nПлательщик сбора обязан уведомить налоговый орган о прекращении использования объекта осуществления торговли, а также о каждом изменении показателей объекта осуществления торговли, которое влечет за собой изменение суммы сбора, не позднее пяти дней со дня соответствующего изменения или прекращения торговли. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nДатой снятия с учета организации или индивидуального предпринимателя в качестве плательщика сбора является дата прекращения осуществления плательщиком сбора вида деятельности, указанная в уведомлении.\n\nПлательщик сбора представляет указанное уведомление не позднее пяти дней с даты прекращения осуществления предпринимательской деятельности, в отношении которой установлен сбор. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nпо месту нахождения объекта недвижимого имущества - в случае, если предпринимательская деятельность, в отношении которой установлен сбор, осуществляется с использованием объекта недвижимого имущества;\n\nпо месту нахождения организации (месту жительства индивидуального предпринимателя) - в иных случаях.\n\nВ случае, если несколько объектов осуществления видов предпринимательской деятельности, в отношении которых установлен сбор, находятся в одном муниципальном образовании (городе федерального значения Москве, Санкт-Петербурге или Севастополе) на территориях, подведомственных разным налоговым органам, постановка на учет плательщика сбора осуществляется налоговым органом по месту нахождения того объекта, сведения о котором поступили от плательщика сбора ранее, чем о других объектах.","article_title":"Статья 416. Учет плательщиков сбора","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef2cff454b3277e0663b5d252e2c5bf5fd211d6dedb561fa91570954c61370b6"},{"code_id":"NK_RF_2","article_number":"417","version_date":"2000-07-31","article_text":"1. Если иное не установлено настоящей статьей, сумма сбора определяется плательщиком самостоятельно для каждого объекта обложения сбором начиная с периода обложения, в котором возник объект обложения сбором, как произведение ставки сбора в отношении соответствующего вида предпринимательской деятельности и фактического значения физической характеристики соответствующего объекта осуществления торговли.","article_title":"Статья 417. Порядок исчисления и уплаты сбора","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a19b51a21d6a8948dc50553142766d02bd43a01d8f62e7f9966258ea009df17d"},{"code_id":"NK_RF_2","article_number":"417.1","version_date":"2000-07-31","article_text":"1. В случае осуществления вида предпринимательской деятельности, в отношении которого установлен сбор, в рамках договора простого товарищества (договора о совместной деятельности) плательщиками сбора признаются участники товарищества, использующие объект движимого и (или) недвижимого имущества для осуществления указанной деятельности.\n\nВ случае совместного использования участниками договора простого товарищества (договора о совместной деятельности) одного объекта осуществления торговли сумма сбора в отношении такого объекта определяется каждым участником как произведение ставки сбора в отношении осуществляемого вида предпринимательской деятельности и фактического значения физического показателя соответствующего объекта осуществления торговли, определяемого пропорционально стоимости вкладов товарищей (внесенным товарищами долям имущества) в общее дело либо установленного (распределенного) в отношении каждого товарища договором о совместной деятельности или дополнительным соглашением товарищей.\n\n2. В случае осуществления вида предпринимательской деятельности, в отношении которого установлен сбор, в рамках договора комиссии обязанности плательщика сбора, установленные настоящей главой, возлагаются на комиссионера.\n\n3. В случае осуществления вида предпринимательской деятельности, в отношении которого установлен сбор, агентом от имени и за счет принципала в рамках агентского договора обязанности плательщика сбора, установленные настоящей главой, возлагаются на принципала.\n\nВ случае осуществления вида предпринимательской деятельности, в отношении которого установлен сбор, агентом от своего имени, но за счет принципала в рамках агентского договора обязанности плательщика сбора, установленные настоящей главой, возлагаются на агента.\n\n4. В случае осуществления вида предпринимательской деятельности, в отношении которого установлен сбор, в рамках договора поручения обязанности плательщика сбора, установленные настоящей главой, возлагаются на доверителя.\n\n5. В случае осуществления вида предпринимательской деятельности, в отношении которого установлен сбор, в рамках договора доверительного управления обязанности плательщика сбора, установленные настоящей главой, возлагаются на доверительного управляющего.\n\n(Дополнение статьей - Федеральный закон от 29.09.2019 № 325-ФЗ)","article_title":"Статья 417.1. Особенности исчисления и уплаты сбора при осуществлении деятельности в соответствии с договором простого товарищества (договором о совместной деятельности), договором комиссии, агентским договором, договором поручения, договором доверительного управления","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2378064a1c7e6e6711af2ba1824dcef2e8e2d5f529c5a4e2042732b5ebc61079"},{"code_id":"NK_RF_2","article_number":"418","version_date":"2000-07-31","article_text":"1. Органы местного самоуправления (органы государственной власти городов федерального значения Москвы, Санкт-Петербурга и Севастополя) осуществляют полномочия по сбору, обработке и передаче налоговым органам сведений об объектах обложения сбором в пределах, установленных настоящей статьей.\n\n2. Нормативным правовым актом представительного органа муниципального образования (законами городов федерального значения Москвы, Санкт-Петербурга и Севастополя) определяется орган, осуществляющий полномочия, указанные в пункте 1 настоящей статьи (далее в настоящей статье - уполномоченный орган).\n\n3. Уполномоченный орган в соответствии с законодательством осуществляет контроль за полнотой и достоверностью информации об объектах обложения сбором на территории своего муниципального образования (города федерального значения Москвы, Санкт-Петербурга или Севастополя).\n\n4. При выявлении объектов обложения сбором, в отношении которых в налоговый орган не представлено уведомление или в отношении которых в уведомлении указаны недостоверные сведения, уполномоченный орган в течение пяти дней составляет акт о выявлении нового объекта обложения сбором или акт о выявлении недостоверных сведений в отношении объекта обложения сбором и направляет указанную информацию в налоговый орган по форме (формату) и в порядке, которые определяются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nУполномоченный орган информирует плательщика сбора о направлении информации в налоговый орган в течение пяти дней с даты направления информации, указанной в абзаце первом настоящего пункта, с приложением копии соответствующего акта. (В редакции  Федерального закона от 26.03.2022 № 67-ФЗ)\n\nАкты, указанные в настоящем пункте, могут быть обжалованы плательщиком сбора в порядке, установленном законодательством Российской Федерации. В случае отмены соответствующего акта сведения об этом направляются уполномоченным органом в налоговый орган в порядке, предусмотренном абзацем первым настоящего пункта.\n\nГЛАВА 331. ТУРИСТИЧЕСКИЙ НАЛОГ\n\n(Дополнение главой - Федеральный закон от 12.07.2024 № 176-ФЗ)","article_title":"Статья 418. Полномочия органов местного самоуправления (органов государственной власти городов федерального значения Москвы, Санкт-Петербурга и Севастополя)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a6b9e799c9c7a724016026ac3460f3e2115bee29236d7e1bcdcfc1fa51f78f7d"},{"code_id":"NK_RF_2","article_number":"418.1","version_date":"2000-07-31","article_text":"1. Туристический налог (далее в настоящей главе также - налог) устанавливается настоящим Кодексом и нормативными правовыми актами представительных органов муниципальных образований, вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и нормативными правовыми актами представительных органов муниципальных образований и обязателен к уплате на территориях этих муниципальных образований.\n\nВ городах федерального значения Москве, Санкт-Петербурге и Севастополе налог устанавливается настоящим Кодексом и законами указанных субъектов Российской Федерации, вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и законами указанных субъектов Российской Федерации и обязателен к уплате на территориях указанных субъектов Российской Федерации.\n\nВ федеральной территории \"Сириус\" налог устанавливается настоящим Кодексом и нормативными правовыми актами представительного органа федеральной территории \"Сириус\", вводится в действие и прекращает действовать в соответствии с настоящим Кодексом и нормативными правовыми актами представительного органа федеральной территории \"Сириус\" и обязателен к уплате в федеральной территории \"Сириус\".\n\n2. Устанавливая налог, представительные органы муниципальных образований (законодательные органы городов федерального значения Москвы, Санкт-Петербурга и Севастополя, представительный орган федеральной территории \"Сириус\") определяют налоговую ставку в пределах, установленных настоящей главой.\n\nНормативными правовыми актами представительных органов муниципальных образований (законами городов федерального значения Москвы, Санкт-Петербурга и Севастополя, нормативными правовыми актами представительного органа федеральной территории \"Сириус\") могут также устанавливаться налоговые льготы, основания и порядок их применения налогоплательщиками.","article_title":"Статья 418.1. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3458453c30561bda8539a5df1f1afffed12db4f0c215920c88c4fecc44f1ea89"},{"code_id":"NK_RF_2","article_number":"418.2","version_date":"2000-07-31","article_text":"Налогоплательщиками налога признаются организации и физические лица, оказывающие услуги, признаваемые объектом налогообложения в соответствии со статьей 4183 настоящего Кодекса.","article_title":"Статья 418.2. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"284fe5beb3b4b43e8b2dbedade52f8de10346a18be524bf7820a9c354748bb72"},{"code_id":"NK_RF_2","article_number":"418.3","version_date":"2000-07-31","article_text":"ласти города федерального значения Москвы, Санкт-Петербурга или Севастополя, исполнительно-распорядительный орган федеральной территории \"Сириус\") (далее в настоящей статье - уполномоченный орган) вправе направить в налоговый орган по соответствующему субъекту Российской Федерации сведения о расположенных на его территории средствах размещения с одновременным направлением этих сведений в орган исполнительной власти субъекта Российской Федерации, уполномоченный на осуществление регионального государственного контроля (надзора) в сфере туристской индустрии, и в территориальный орган федерального органа исполнительной власти, уполномоченного Правительством Российской Федерации на организацию формирования и ведения единого реестра объектов классификации в сфере туристской индустрии.\n\nСведения, предусмотренные абзацем первым настоящего пункта, подлежат размещению уполномоченным органом на его официальном сайте или на официальном сайте муниципального образования (города федерального значения Москвы, Санкт-Петербурга или Севастополя, федеральной территории \"Сириус\") в информационно-телекоммуникационной сети \"Интернет\" в день направления этих сведений. Для целей настоящей главы средства размещения, указанные в направленных сведениях, признаются включенными в реестр классифицированных средств размещения со дня размещения сведений о них на соответствующем официальном сайте, если сведения об этих средствах размещения не содержатся в реестре классифицированных средств размещения.\n\nСведения, предусмотренные абзацем первым настоящего пункта, направляются в налоговый орган по субъекту Российской Федерации по форме и форматам, которые рекомендованы федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2024 № 416-ФЗ)","article_title":"Статья 418.3. Объект налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f165c25f6449a14eed16e9bcb1793065aef87a3affb54ce3fe1717447db87ebc"},{"code_id":"NK_RF_2","article_number":"418.4","version_date":"2000-07-31","article_text":"1. Если иное не предусмотрено настоящей статьей, налоговая база определяется как стоимость оказываемой услуги по предоставлению мест для временного проживания физических лиц в средстве размещения (его части) (далее в настоящей главе - услуга по временному проживанию) без учета сумм налога и налога на добавленную стоимость.\n\n2. При условии предоставления налогоплательщику документов, подтверждающих соответствующий статус физического лица, в налоговую базу не включается стоимость услуги по временному проживанию, оказываемой следующим категориям физических лиц:\n\n1) лица, удостоенные званий Героя Советского Союза, Героя Российской Федерации или являющиеся полными кавалерами ордена Славы;\n\n2) лица, удостоенные званий Героя Социалистического Труда, Героя Труда Российской Федерации или награжденные орденом Трудовой Славы трех степеней;\n\n3) участники и инвалиды Великой Отечественной войны;\n\n4) лица, принимающие (принимавшие) участие в специальной военной операции, лица, выполняющие (выполнявшие) возложенные на них задачи на территориях Украины, Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области в период проведения специальной военной операции, указанные в пункте 61 статьи 210 настоящего Кодекса;\n\n5) ветераны и инвалиды боевых действий;\n\n6) лица, награжденные знаком \"Жителю блокадного Ленинграда\", лица, награжденные знаком \"Житель осажденного Севастополя\", лица, награжденные знаком \"Житель осажденного Сталинграда\";\n\n7) лица, работавшие в период Великой Отечественной войны на объектах противовоздушной обороны, местной противовоздушной обороны, на строительстве оборонительных сооружений, военно-морских баз, аэродромов и других военных объектов в пределах тыловых границ действующих фронтов, операционных зон действующих флотов, на прифронтовых участках железных и автомобильных дорог, а также члены экипажей судов транспортного флота, интернированных в начале Великой Отечественной войны в портах других государств;\n\n8) инвалиды I и II групп, инвалиды с детства, дети-инвалиды.\n\n3. Представительные органы муниципальных образований (законодательные органы городов федерального значения Москвы, Санкт-Петербурга и Севастополя, представительный орган федеральной территории \"Сириус\") вправе устанавливать дополнительные категории физических лиц, стоимость услуг по временному проживанию которых не включается в налоговую базу.","article_title":"Статья 418.4. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d3b8703be073cfe53f02f771b4c2f279fbeb5ad87496109f81127552b22b13fc"},{"code_id":"NK_RF_2","article_number":"418.5","version_date":"2000-07-31","article_text":"1. Налоговые ставки устанавливаются нормативными правовыми актами представительных органов муниципальных образований (законами городов федерального значения Москвы, Санкт-Петербурга и Севастополя, нормативными правовыми актами представительного органа федеральной территории \"Сириус\") в размерах, не превышающих в 2025 году 1 процента, в 2026 году - 2 процентов, в 2027 году - 3 процентов, в 2028 году - 4 процентов, начиная с 2029 года - 5 процентов от налоговой базы.\n\n2. Налоговые ставки могут быть дифференцированы с учетом сезонности и (или) категории средства размещения.","article_title":"Статья 418.5. Налоговая ставка","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e537964f5f63db3b58694cb26cac65f3a84c134d481000bb4e32e2f93bd6d498"},{"code_id":"NK_RF_2","article_number":"418.6","version_date":"2000-07-31","article_text":"Налоговым периодом по налогу признается квартал.","article_title":"Статья 418.6. Налоговый период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ca2c47ced6f73c5991ecca64627fd41b25a299d38fbc6c0b0f01a2b47929cd6"},{"code_id":"NK_RF_2","article_number":"418.7","version_date":"2000-07-31","article_text":"1. Если иное не установлено настоящим пунктом, сумма налога исчисляется налогоплательщиком как соответствующая налоговой ставке процентная доля налоговой базы применительно к услуге по временному проживанию в момент осуществления полного расчета с лицом, приобретающим такую услугу.\n\nВ случае, если исчисленная в соответствии с абзацем первым настоящего пункта сумма налога менее суммы минимального налога, рассчитанной как произведение 100 рублей и количества суток проживания, сумма налога определяется в размере минимального налога.\n\nАбзац. (Утратил силу - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\nНалогоплательщики, оказывающие услуги по временному проживанию в составе услуг по санаторно-курортному лечению, исчисляют налог в отношении таких услуг в размере минимального налога. При этом минимальный налог не исчисляется в отношении услуг по временному проживанию в составе услуг по санаторно-курортному лечению, предоставляемых при наличии медицинских показаний, оплата которых осуществляется в рамках государственных заданий за счет бюджетных ассигнований федерального бюджета, государственных внебюджетных фондов, бюджетов субъектов Российской Федерации, местных бюджетов. (Дополнение абзацем - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\n2. Общая сумма налога, подлежащая уплате в бюджет, исчисляется по итогам налогового периода как сумма, полученная в результате сложения сумм налогов, исчисленных в соответствии с пунктом 1 настоящей статьи по услугам, оказанным за налоговый период во всех средствах размещения, принадлежащих налогоплательщику, расположенных на территории муниципального образования (на территориях городов федерального значения Москвы, Санкт-Петербурга и Севастополя, федеральной территории \"Сириус\").","article_title":"Статья 418.7. Порядок исчисления налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5a80f9a2ca9a639e027e98a26d3f41e7eb4df557ac1823caba78698a841c3221"},{"code_id":"NK_RF_2","article_number":"418.8","version_date":"2000-07-31","article_text":"Налог уплачивается в бюджет по месту нахождения средства размещения в срок не позднее 28-го числа месяца, следующего за истекшим налоговым периодом.","article_title":"Статья 418.8. Порядок и сроки уплаты налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"75b1355ffc2910f95616c25bf620e5b00ff19756dfaf0184f9cb273836a086ee"},{"code_id":"NK_RF_2","article_number":"418.9","version_date":"2000-07-31","article_text":"1. По итогам налогового периода налогоплательщики представляют налоговую декларацию в налоговый орган по месту нахождения средства размещения в срок не позднее 25-го числа месяца, следующего за истекшим налоговым периодом, по форме (формату), которая утверждена федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. В случае учета налогоплательщика в нескольких налоговых органах по месту нахождения средств размещения, расположенных на территории муниципального образования (на территориях городов федерального значения Москвы, Санкт-Петербурга и Севастополя, федеральной территории \"Сириус\"), налогоплательщик вправе выбрать налоговый орган на территории муниципального образования (на территориях городов федерального значения Москвы, Санкт-Петербурга и Севастополя, федеральной территории \"Сириус\"), в который представляется налоговая декларация, направив уведомление о выборе налогового органа в налоговые органы по месту нахождения средств размещения на территории муниципального образования (на территориях городов федерального значения Москвы, Санкт-Петербурга и Севастополя, федеральной территории \"Сириус\").\n\nУказанное в абзаце первом настоящего пункта уведомление представляется налогоплательщиком в срок не позднее 30 дней до установленного срока представления налоговой декларации однократно, за исключением случаев реализации (иного выбытия из владения налогоплательщика) средства (средств) размещения, по месту нахождения которого (которых) выбран налоговый орган, в который представляется налоговая декларация.\n\nФорма уведомления о выборе налогового органа, в который представляется налоговая декларация, порядок заполнения, формат представления уведомления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nРАЗДЕЛ XI. СТРАХОВЫЕ ВЗНОСЫ В РОССИЙСКОЙ ФЕДЕРАЦИИ\n\n(Дополнение разделом - Федеральный закон от 03.07.2016 № 243-ФЗ)\n\nГЛАВА 34. СТРАХОВЫЕ ВЗНОСЫ","article_title":"Статья 418.9. Налоговая декларация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8dc4c0ade352e8dd1a55094ef31054a7219cf0520a03d8e31cd04cb9a3de7742"},{"code_id":"NK_RF_2","article_number":"419","version_date":"2000-07-31","article_text":"1. Плательщиками страховых взносов (далее в настоящей главе - плательщики) признаются следующие лица, являющиеся страхователями в соответствии с федеральными законами о конкретных видах обязательного социального страхования:\n\n1) лица, производящие выплаты и иные вознаграждения физическим лицам:\n\nорганизации;\n\nиндивидуальные предприниматели;\n\nфизические лица, не являющиеся индивидуальными предпринимателями;\n\n2) индивидуальные предприниматели, адвокаты, медиаторы, нотариусы, занимающиеся частной практикой, арбитражные управляющие, оценщики, патентные поверенные и иные лица, занимающиеся в установленном законодательством Российской Федерации порядке частной практикой (далее - плательщики, не производящие выплаты и иные вознаграждения физическим лицам). (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n2. Если плательщик относится одновременно к нескольким категориям, указанным в пункте 1 настоящей статьи, он исчисляет и уплачивает страховые взносы отдельно по каждому основанию.","article_title":"Статья 419. Плательщики страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8df966ce5726bbea63eef085c44ad0ff16b98ed264d107340626beb47e174715"},{"code_id":"NK_RF_2","article_number":"420","version_date":"2000-07-31","article_text":"1. Объектом обложения страховыми взносами для плательщиков, указанных в абзацах втором и третьем подпункта 1 пункта 1 статьи 419 настоящего Кодекса, если иное не предусмотрено настоящей статьей, признаются выплаты и иные вознаграждения в пользу физических лиц, подлежащих обязательному социальному страхованию в соответствии с федеральными законами о конкретных видах обязательного социального страхования (за исключением вознаграждений, выплачиваемых лицам, указанным в подпункте 2 пункта 1 статьи 419 настоящего Кодекса):\n\n1) в рамках трудовых отношений (в том числе вознаграждения в рамках трудовых договоров в пользу членов совета многоквартирного дома, включая председателя совета многоквартирного дома, избранных собственниками помещений в многоквартирном доме в соответствии с положениями Жилищного кодекса Российской Федерации, начисляемые уполномоченной управляющей организацией на основании решения общего собрания собственников помещений в многоквартирном доме); (В редакции  федеральных законов от 31.07.2023 № 389-ФЗ, от 29.10.2024 № 362-ФЗ)\n\n11) по гражданско-правовым договорам, предметом которых являются выполнение работ, оказание услуг, в том числе вознаграждения по гражданско-правовым договорам членам совета многоквартирного дома, включая председателя совета многоквартирного дома, избранным собственниками помещений в многоквартирном доме в соответствии с положениями Жилищного кодекса Российской Федерации, начисляемые уполномоченной управляющей организацией на основании решения общего собрания собственников помещений в многоквартирном доме; (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ) (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\n2) по договорам авторского заказа в пользу авторов произведений;\n\n3) по договорам об отчуждении исключительного права на результаты интеллектуальной деятельности, указанные в подпунктах 1 - 12 пункта 1 статьи 1225 Гражданского кодекса Российской Федерации, издательским лицензионным договорам, лицензионным договорам о предоставлении права использования результатов интеллектуальной деятельности, указанных в подпунктах 1 - 12 пункта 1 статьи 1225 Гражданского кодекса Российской Федерации, в том числе вознаграждения, начисляемые организациями по управлению правами на коллективной основе в пользу авторов произведений по договорам, заключенным с пользователями. (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)","article_title":"Статья 420. Объект обложения страховыми взносами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ca15af77971f4a170914a750d86cbc696a59e5ec069162473ca1a453171330d2"},{"code_id":"NK_RF_2","article_number":"421","version_date":"2000-07-31","article_text":"1. База для исчисления страховых взносов для плательщиков, указанных в абзацах втором и третьем подпункта 1 пункта 1 статьи 419 настоящего Кодекса, определяется по истечении каж\n\nдого календарного месяца как сумма выплат и иных вознаграждений, предусмотренных пунктом 1 статьи 420 настоящего Кодекса, начисленных отдельно в отношении каждого физического лица с начала расчетного периода нарастающим итогом, за исключением сумм, указанных в статье 422 настоящего Кодекса.\n\n2. База для исчисления страховых взносов для плательщиков, указанных в абзаце четвертом подпункта 1 пункта 1 статьи 419 настоящего Кодекса, определяется по истечении каждого календарного месяца как сумма выплат и иных вознаграждений, предусмотренных пунктом 2 статьи 420 настоящего Кодекса, начисленных отдельно в отношении каждого физического лица с начала расчетного периода нарастающим итогом, за исключением сумм, указанных в статье 422 настоящего Кодекса.\n\nв 2017 году - 1,9;\n\nв 2018 году - 2,0;\n\nв 2019 году - 2,1;\n\nв 2020 году - 2,2;\n\nв 2021 году - 2,3.\n\nПоложение настоящего пункта не применяется при исчислении страховых взносов по дополнительным тарифам на обязательное пенсионное страхование, установленным статьей 428 настоящего Кодекса, и страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности, установленных статьей 429 настоящего Кодекса.\n\nУстановленная в соответствии с настоящим пунктом предельная величина базы для исчисления страховых взносов на обязательное пенсионное страхование в 2022 году подлежит индексации с учетом роста средней заработной платы в Российской Федерации. (В редакции  Федерального закона от 21.11.2022 № 443-ФЗ)\n\nС сумм выплат и иных вознаграждений в пользу физического лица, превышающих установленную на соответствующий расчетный период единую предельную величину базы для исчисления страховых взносов, определяемую нарастающим итогом с начала расчетного периода, страховые взносы не взимаются, если иное не установлено настоящей главой.\n\nПоложение настоящего пункта не применяется при исчислении страховых взносов по дополнительным тарифам на обязательное пенсионное страхование, установленным статьей 428 настоящего Кодекса, и страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности, установленных статьей 429 настоящего Кодекса.\n\nС 1 января 2023 года единая предельная величина базы для исчисления страховых взносов устанавливается с учетом определенного на соответствующий год размера средней заработной платы в Российской Федерации, увеличенного в двенадцать раз, и примененного к нему коэффициента 2,3. (В редакции  Федерального закона от 21.11.2022 № 443-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\nПри этом в стоимость таких товаров (работ, услуг) включается соответствующая сумма налога на добавленную стоимость, акцизов и исключается частичная оплата физическим лицом стоимости полученных им товаров, выполненных для него работ, оказанных ему услуг.\n\n1) на создание литературных произведений, в том числе для театра, кино, эстрады и цирка, - 20 процентов;\n\n2) на создание художественно-графических произведений, фоторабот для печати, произведений архитектуры и дизайна - 30 процентов;\n\n3) на создание произведений скульптуры, монументально-декоративной живописи, декоративно-прикладного и оформительского искусства, станковой живописи, театрально- и кинодекорационного искусства и графики, выполненных в различной технике, - 40 процентов;\n\n4) на создание аудиовизуальных произведений (видео-, теле- и кинофильмов), фонограмм, сообщений в эфир или по кабелю радио- или телепередач - 30 процентов; (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\n5) на создание музыкально-сценических произведений (опер, балетов, музыкальных комедий), симфонических, хоровых, камерных произведений, произведений для духового оркестра, оригинальной музыки для кино-, теле-, видеофильмов и театральных постановок - 40 процентов;\n\n6) на создание других музыкальных произведений, в том числе произведений, подготовленных к опубликованию, - 25 процентов;\n\n7) на исполнение произведений литературы и искусства - 20 процентов;\n\n8) на создание научных трудов и разработок, программ для ЭВМ, баз данных - 20 процентов; (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\n9) на открытия, селекционные достижения, изобретения, создание полезных моделей, промышленных образцов, секретов производства (ноу-хау), топологий интегральных микросхем (процент суммы дохода, полученного за первые два года использования) - 30 процентов. (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)","article_title":"Статья 421. База для исчисления страховых взносов для плательщиков, производящих выплаты и иные вознаграждения физическим лицам","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad1f60c3669069d9246125bc11d1458651ed157713be0855147d6a313ab2565b"},{"code_id":"NK_RF_2","article_number":"422","version_date":"2000-07-31","article_text":"1. Не подлежат обложению страховыми взносами для плательщиков, указанных в подпункте 1 пункта 1 статьи 419 настоящего Кодекса:\n\n1) государственные пособия, выплачиваемые в соответствии с законодательством Российской Федерации, законодательными актами субъектов Российской Федерации, решениями представительных органов местного самоуправления, в том числе пособия по безработице, а также пособия и иные виды обязательного страхового обеспечения по обязательному социальному страхованию;\n\n2) все виды установленных законодательством Российской Федерации, законодательными актами субъектов Российской Федерации, решениями представительных органов местного самоуправления компенсационных выплат (в пределах норм, установленных в соответствии с законодательством Российской Федерации), связанных:\n\nс возмещением вреда, причиненного увечьем или иным повреждением здоровья;\n\nс возмещением расходов на оплату жилого помещения, питания и продуктов, топлива, или их оплатой, или их бесплатным предоставлением, а также с возмещением расходов на оплату коммунальных услуг или их оплатой; (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nс оплатой стоимости и (или) выдачей полагающегося натурального довольствия, а также с выплатой денежных средств взамен этого довольствия;\n\nс оплатой стоимости питания, спортивного снаряжения, оборудования, спортивной и парадной формы, получаемых спортсменами и работниками физкультурно-спортивных организаций для тренировочного процесса и участия в спортивных соревнованиях, а также спортивными судьями для участия в спортивных соревнованиях;\n\nс увольнением работников, за исключением компенсации за неиспользованный отпуск, суммы выплат в виде выходного пособия и среднего месячного заработка на период трудоустройства в части, превышающей в целом трехкратный размер среднего месячного заработка или шестикратный размер среднего месячного заработка для работников, уволенных из организаций, расположенных в районах Крайнего Севера и приравненных к ним местностях, а также компенсации руководителю, заместителям руководителя и главному бухгалтеру организации в части, превышающей трехкратный размер среднего месячного заработка;\n\nс возмещением расходов на профессиональную подготовку, переподготовку и повышение квалификации работников;\n\nабзац; (Утратил силу - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nс трудоустройством работников, уволенных в связи с осуществлением мероприятий по сокращению численности или штата работников, реорганизацией или ликвидацией организации, в связи с прекращением физическими лицами деятельности в качестве индивидуальных предпринимателей, прекращением полномочий нотариусами, занимающимися частной практикой, и прекращением статуса адвоката, а также в связи с прекращением деятельности иными физическими лицами, чья профессиональная деятельность в соответствии с федеральными законами подлежит государственной регистрации и (или) лицензированию;\n\nс возмещением расходов дистанционных работников, связанных с использованием ими для выполнения трудовой функции принадлежащих им или арендованных ими оборудования, программно-технических средств, средств защиты информации и иных средств, в сумме, определяемой коллективным договором, локальным нормативным актом, трудовым договором, дополнительным соглашением к трудовому договору, но не более 35 рублей за каждый день выполнения трудовой функции дистанционно, либо в сумме документально подтвержденных расходов работника; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nс выполнением физическим лицом трудовых обязанностей, в том числе в связи с переездом на работу в другую местность, за исключением выплат в денежной форме за работу с тяжелыми, вредными и (или) опасными условиями труда, кроме компенсационных выплат в размере, эквивалентном стоимости молока или других равноценных пищевых продуктов, выплат в иностранной валюте взамен суточных, предусмотренных пунктом 1 статьи 217 настоящего Кодекса, российскими судоходными компаниями членам экипажей судов заграничного плавания, выплат в иностранной валюте личному составу экипажей российских воздушных судов, выполняющих международные рейсы, а также компенсационных выплат за неиспользованный отпуск, не связанных с увольнением работников; (В редакции Федерального закона от 17.06.2019 № 147-ФЗ)\n\n3) суммы единовременной материальной помощи, оказываемой плательщиками:\n\nфизическим лицам в связи со стихийным бедствием или другим чрезвычайным обстоятельством в целях возмещения причиненного им материального ущерба или вреда их здоровью, а также физическим лицам, пострадавшим от террористических актов на территории Российской Федерации;\n\nработнику в связи со смертью члена (членов) его семьи;\n\nработникам (родителям, усыновителям, опекунам) при рождении (усыновлении (удочерении) ребенка, установлении опеки над ребенком, выплачиваемой в течение первого года после рождения (усыновления (удочерения), установления опеки, но не более 50 000 рублей на каждого ребенка;\n\n4) доходы (за исключением оплаты труда работников), получаемые членами зарегистрированных в установленном порядке семейных (родовых) общин коренных малочисленных народов Севера, Сибири и Дальнего Востока Российской Федерации, занимающихся традиционной хозяйственной деятельностью, от реализации продукции, полученной в результате ведения ими традиционных видов промысла; (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n5) суммы страховых платежей (взносов) по обязательному страхованию работников, осуществляемому плательщиком в порядке, установленном законодательством Российской Федерации, суммы платежей (взносов) плательщика по договорам добровольного личного страхования работников, заключаемым на срок не менее одного года, предусматривающим оплату страховщиками медицинских расходов этих застрахованных лиц, суммы платежей (взносов) плательщика по договорам на оказание медицинских услуг работникам, заключаемым на срок не менее одного года с медицинскими организациями, имеющими соответствующие лицензии на осуществление медицинской деятельности, предоставленные в соответствии с законодательством Российской Федерации, суммы платежей (взносов) плательщика по договорам добровольного личного страхования работников, заключаемым исключительно на случай наступления смерти застрахованного лица и (или) причинения вреда здоровью застрахованного лица, а также суммы пенсионных взносов плательщика по договорам негосударственного пенсионного обеспечения; (В редакции Федерального закона от 29.11.2021 № 383-ФЗ)\n\n6) взносы работодателя, уплаченные плательщиком в соответствии с Федеральным законом от 30 апреля 2008 года № 56-ФЗ \"О дополнительных страховых взносах на накопительную пенсию и государственной поддержке формирования пенсионных накоплений\", в размере уплаченных взносов, но не более 12 000 рублей в год в расчете на каждого работника, в пользу которого уплачивались взносы работодателя, а также в размере уплаченных в расчетном периоде сберегательных взносов работодателя по договору долгосрочных сбережений в пользу работника, являющегося одновременно вкладчиком по такому договору и участником такого договора, но не более 12 процентов от базы для исчисления страховых взносов в отношении этого работника за соответствующий расчетный период; (В редакции  Федерального закона от 17.11.2025 № 418-ФЗ)\n\n7) стоимость проезда работника к месту использования отпуска и обратно и стоимость провоза багажа весом до 30 килограммов, а также стоимость проезда неработающих членов его семьи (мужа, жены, несовершеннолетних детей, фактически проживающих с работником) и стоимость провоза ими багажа, оплачиваемые плательщиком страховых взносов лицам, работающим и проживающим в районах Крайнего Севера и приравненных к ним местностях, в соответствии с законодательством Российской Федерации, законодательными актами субъектов Российской Федерации, решениями представительных органов местного самоуправления, трудовыми договорами и (или) коллективными договорами. В случае использования отпуска за пределами территории Российской Федерации не подлежит обложению страховыми взносами стоимость проезда или перелета работника и неработающих членов его семьи (включая стоимость провоза ими багажа весом до 30 килограммов), рассчитанная от места отправления до пункта пропуска через Государственную границу Российской Федерации, в том числе международного аэропорта, в котором работник и неработающие члены его семьи проходят пограничный контроль в пункте пропуска через Государственную границу Российской Федерации; (В редакции Федерального закона от 03.08.2018 № 300-ФЗ)\n\n8) суммы, выплачиваемые физическим лицам избирательными комиссиями, комиссиями референдума, а также из средств избирательных фондов кандидатов на должность Президента Российской Федерации, кандидатов в депутаты Государственной Думы, кандидатов в депутаты законодательного органа субъекта Российской Федерации, кандидатов на должность в ином органе государственной власти субъекта Российской Федерации, предусмотренном конституцией, уставом субъекта Российской Федерации, избираемых непосредственно гражданами, кандидатов в депутаты представительного органа муниципального образования, кандидатов на должность главы муниципального образования, на иную должность, предусмотренную уставом муниципального образования и замещаемую посредством прямых выборов, избирательных фондов избирательных объединений, избирательных фондов региональных отделений политических партий, не являющихся избирательными объединениями, из средств фондов референдума инициативной группы по проведению референдума Российской Федерации, референдума субъекта Российской Федерации, местного референдума, инициативной агитационной группы референдума Российской Федерации, иных групп участников референдума субъекта Российской Федерации, местного референдума за выполнение этими лицами работ, непосредственно связанных с проведением избирательных кампаний, кампаний референдума; (В редакции  федеральных законов от 30.11.2016 № 401-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n81) суммы, выплачиваемые членам избирательных комиссий с правом решающего голоса, работающим в комиссиях не на постоянной (штатной) основе, работникам Федерального центра информатизации при Центральной избирательной комиссии Российской Федерации, а также гражданам, работающим по гражданско-правовым договорам, за выполненные ими работы, оказанные услуги, непосредственно связанные с подготовкой и проведением общероссийского голосования; (Дополнение подпунктом - Федеральный закон от 26.03.2020 № 68-ФЗ)\n\n9) стоимость форменной одежды и обмундирования, выдаваемых работникам в соответствии с законодательством Российской Федерации, а также государственным служащим федеральных органов государственной\n\nвласти бесплатно или с частичной оплатой и остающихся в их личном постоянном пользовании;\n\n10) стоимость льгот по проезду, предоставляемых законодательством Российской Федерации отдельным категориям работников;\n\n11) суммы материальной помощи, оказываемой работодателями своим работникам, не превышающие 4 000 рублей на одного работника за расчетный период;\n\n12) суммы платы за обучение работников по основным профессиональным образовательным программам и дополнительным профессиональным программам;\n\n13) суммы, выплачиваемые плательщиками своим работникам на возмещение затрат по уплате процентов по займам (кредитам) на приобретение и (или) строительство жилого помещения;\n\n14) суммы денежного довольствия, продовольственного и вещевого обеспечения и иных выплат, получаемых военнослужащими, сотрудниками органов внутренних дел, учреждений и органов уголовно-исполнительной системы, органов принудительного исполнения Российской Федерации, федеральной противопожарной службы Государственной противопожарной службы, таможенных органов Российской Федерации, лицами начальствующего состава органов федеральной фельдъегерской связи, лицами, проходящими службу в войсках национальной гвардии Российской Федерации и имеющими специальные звания полиции, в связи с исполнением обязанностей военной службы и службы в указанных войсках, учреждениях и органах в соответствии с законодательством Российской Федерации; (В редакции федеральных законов от 29.05.2019 № 108-ФЗ, от 27.12.2019 № 460-ФЗ)\n\n15) (Подпункт утратил силу - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\n16) суммы, выплачиваемые плательщиком на возмещение фактически произведенных и документально подтвержденных расходов физического лица, связанных с выполнением работ, оказанием услуг по договорам гражданско-правового характера, а также оплата плательщиком таких расходов; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n17) суммы выплат работникам в размере, не превышающем 12 792 рублей на одного работника, выплаченные работодателями, получившими субсидии из федерального бюджета, предоставляемые субъектам малого и среднего предпринимательства и социально ориентированным некоммерческим организациям в условиях ухудшения ситуации в результате распространения новой коронавирусной инфекции в целях частичной компенсации их затрат, связанных с осуществлением ими деятельности в условиях нерабочих дней в октябре и ноябре 2021 года, а также с проведением в 2021 году мероприятий по адаптации к требованиям о посещении предприятий в отдельных сферах экономики при условии наличия QR-кодов и (или) к иным ограничениям деятельности, направленным на недопущение распространения новой коронавирусной инфекции. Доходы, указанные в настоящем подпункте исключаются из базы для исчисления страховых взносов однократно в календарном месяце получения такой субсидии или в следующем за ним календарном месяце; (Дополнение подпунктом - Федеральный закон от 29.11.2021 № 382-ФЗ)\n\n18) выплаты плательщиками в виде безвозмездно переданных денежных средств и (или) иного имущества работникам, призванным на военную службу по мобилизации в Вооруженные Силы Российской Федерации или проходящим военную службу по контракту, заключенному в соответствии с пунктом 7 статьи 38 Федерального закона от 28 марта 1998 года № 53-ФЗ \"О воинской обязанности и военной службе\", либо по контракту о пребывании в добровольческом формировании (о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации, войска национальной гвардии Российской Федерации), при условии, что указанные в настоящем подпункте выплаты связаны с прохождением военной службы по мобилизации или с указанными контрактами. (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ) (В редакции  Федерального закона от 25.12.2023 № 643-ФЗ)\n\nПри выплате плательщиками в соответствии с законодательством Российской Федерации сумм суточных или полевого довольствия работникам, постоянная работа которых осуществляется в пути или имеет разъездной характер, и работникам, работающим в полевых условиях или участвующим в работах экспедиционного характера, а также надбавки за вахтовый метод работы взамен суточных лицам, выполняющим работы вахтовым методом, за каждый календарный день пребывания в местах производства работ в период вахты и за фактические дни нахождения в пути от места нахождения работодателя (пункта сбора) до места выполнения работы и обратно указанные суммы не подлежат обложению страховыми взносами в размере, не превышающем размера соответствующих выплат, предусмотренного пунктом 1 статьи 217 настоящего Кодекса. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n1) (Подпункт утратил силу - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\n3) суммы выплат (вознаграждений), указанные в пункте 70 статьи 217 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)","article_title":"Статья 422. Суммы, не подлежащие обложению страховыми взносами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"265a3c422eff2a85de686e2f5e1a18e0442db7131b6a500e47e904634bb4848c"},{"code_id":"NK_RF_2","article_number":"423","version_date":"2000-07-31","article_text":"1. Расчетным периодом признается календарный год.\n\n2. Отчетными периодами признаются первый квартал, полугодие, девять месяцев календарного года.","article_title":"Статья 423. Расчетный период. Отчетный период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"035c2e45ad5b093d8f9a930d7df3a10280b4e2ba8fd4a91eb11bc13439e3ba7b"},{"code_id":"NK_RF_2","article_number":"424","version_date":"2000-07-31","article_text":"Дата осуществления выплат и иных вознаграждений определяется как:\n\n1) день начисления выплат и иных вознаграждений в пользу работника (физического лица, в пользу которого осуществляются выплаты и иные вознаграждения) - для выплат и иных вознаграждений, начисленных плательщиками, указанными в абзацах втором и третьем подпункта 1 пункта 1 статьи 419 настоящего Кодекса;\n\n2) день осуществления выплат и иных вознаграждений в пользу физического лица - для плательщиков, указанных в абзаце четвертом подпункта 1 пункта 1 статьи 419 настоящего Кодекса.","article_title":"Статья 424. Определение даты осуществления выплат и иных вознаграждений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"147f7b7a1fa254d0f659fcd16240f2f80ca078ed762831cc5ae44a8f32af4c33"},{"code_id":"NK_RF_2","article_number":"425","version_date":"2000-07-31","article_text":"1. Тариф страхового взноса представляет собой величину страхового взноса на единицу измерения базы для исчисления страховых взносов, если иное не предусмотрено настоящей главой.\n\n1) на обязательное пенсионное страхование:\n\nв пределах установленной предельной величины базы для исчисления страховых взносов по данному виду страхования - 22 процента;\n\nсвыше установленной предельной величины базы для исчисления страховых взносов по данному виду страхования - 10 процентов;\n\n(Подпункт в редакции Федерального закона от 03.08.2018 № 303-ФЗ)\n\n2) на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством в пределах установленной предельной величины базы для исчисления страховых взносов по данному виду страхования - 2,9 процента;\n\nна обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством в отношении выплат и иных вознаграждений в пользу иностранных граждан и лиц без гражданства, временно пребывающих в Российской Федерации (за исключением высококвалифицированных специалистов в соответствии с Федеральным законом от 25 июля 2002 года № 115-ФЗ \"О правовом положении иностранных граждан в Российской Федерации\"), в пределах установленной предельной величины базы по данному виду страхования - 1,8 процента;\n\n3) на обязательное медицинское страхование - 5,1 процента.\n\n1) в пределах установленной единой предельной величины базы для исчисления страховых взносов - 30 процентов;\n\n2) свыше установленной единой предельной величины базы для исчисления страховых взносов - 15,1 процента.\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\n1) на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством в пределах установленной единой предельной величины базы для исчисления страховых взносов - 2,9 процента;\n\n2) на обязательное медицинское страхование - 5,1 процента.\n\nПлательщики страховых взносов, производящие выплаты и иные вознаграждения в пользу прокуроров, сотрудников Следственного комитета Российской Федерации, судей федеральных судов, мировых судей, страховые взносы на обязательное пенсионное страхование с указанных выплат не исчисляют.\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 239-ФЗ)","article_title":"Статья 425. Тарифы страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe5d046408ee91bea4e293ce58cf53c9c3d9cd81d8baa0400ddec41fc1f234db"},{"code_id":"NK_RF_2","article_number":"426","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 03.08.2018 № 303-ФЗ)","article_title":"Статья 426. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed7dd8f53b32182eecf0cec260327547f56bacb4702dabcafc7c5d17ffb7e395"},{"code_id":"NK_RF_2","article_number":"427","version_date":"2000-07-31","article_text":"1. Пониженные тарифы страховых взносов для плательщиков, указанных в подпункте 1 пункта 1 статьи 419 настоящего Кодекса, применяются:\n\n1) для хозяйственных обществ и хозяйственных партнерств, деятельность которых заключается в практическом применении (внедрении) результатов интеллектуальной деятельности (программ для электронных вычислительных машин, баз данных, изобретений, полезных моделей, промышленных образцов, селекционных достижений, топологий интегральных микросхем, секретов производства (ноу-хау), исключительные права на которые принадлежат учредителям, участникам (в том числе совместно с другими лицами) таких хозяйственных обществ, участникам таких хозяйственных партнерств - бюджетным научным учреждениям и автономным научным учреждениям либо образовательным организациям высшего образования, являющимся бюджетными учреждениями, автономными учреждениями;\n\n2) для организаций и индивидуальных предпринимателей, заключивших с органами управления особыми экономическими зонами соглашения об осуществлении технико-внедренческой деятельности и производящих выплаты физическим лицам, работающим в технико-внедренческой особой экономической зоне или промышленно-производственной особой экономической зоне, для организаций и индивидуальных предпринимателей, заключивших соглашения об осуществлении туристско-рекреационной деятельности и производящих выплаты физическим лицам, работающим в туристско-рекреационных особых экономических зонах, объединенных решением Правительства Российской Федерации в кластер;\n\n3) для российских организаций, осуществляющих деятельность в области информационных технологий; (В редакции  Федерального закона от 14.07.2022 № 321-ФЗ)\n\n4) для плательщиков, производящих выплаты и иные вознаграждения членам экипажей судов, зарегистрированных в Российском международном реестре судов (за исключением судов, используемых для хранения и перевалки нефти, нефтепродуктов и сжиженного природного газа в морских портах Российской Федерации), за исполнение трудовых обязанностей члена экипажа судна, - в отношении данных выплат и вознаграждений; (В редакции Федерального закона от 11.06.2021 № 198-ФЗ)\n\n5) для организаций и индивидуальных предпринимателей, применяющих упрощенную систему налогообложения, основным видом экономической деятельности (классифицируемым на основании кодов видов деятельности в соответствии с Общероссийским классификатором видов экономической деятельности) которых являются:\n\nпроизводство пищевых продуктов;\n\nпроизводство безалкогольных напитков, производство минеральных вод и прочих питьевых вод в бутылках;\n\nпроизводство текстильных изделий;\n\nпроизводство одежды;\n\nпроизводство кожи и изделий из кожи;\n\nобработка древесины и производство изделий из дерева и пробки, кроме мебели, производство изделий из соломки и материалов для плетения;\n\nпроизводство бумаги и бумажных изделий;\n\nпроизводство химических веществ и химических продуктов;\n\nпроизводство лекарственных средств и материалов, применяемых в медицинских целях;\n\nпроизводство резиновых и пластмассовых изделий;\n\nпроизводство прочей неметаллической минеральной продукции;\n\nпроизводство профилей с помощью холодной штамповки или гибки;\n\nпроизводство проволоки методом холодного волочения;\n\nпроизводство готовых металлических изделий, кроме машин и оборудования;\n\nпроизводство компьютеров, электронных и оптических изделий;\n\nпроизводство электрического оборудования;\n\nпроизводство машин и оборудования, не включенных в другие группировки;\n\nпроизводство автотранспортных средств, прицепов и полуприцепов;\n\nпроизводство прочих транспортных средств и оборудования;\n\nпроизводство мебели;\n\nпроизводство музыкальных инструментов;\n\nпроизводство спортивных товаров;\n\nпроизводство игр и игрушек;\n\nпроизводство медицинских инструментов и оборудования;\n\nпроизводство изделий, не включенных в другие группировки;\n\nремонт и монтаж машин и оборудования;\n\nсбор и обработка сточных вод;\n\nсбор, обработка и утилизация отходов; обработка вторичного сырья;\n\nстроительство зданий;\n\nстроительство инженерных сооружений;\n\nработы строительные специализированные;\n\nтехническое обслуживание и ремонт автотранспортных средств;\n\nторговля розничная лекарственными средствами в специализированных магазинах (аптеках);\n\nторговля розничная изделиями, применяемыми в медицинских целях, ортопедическими изделиями в специализированных магазинах;\n\nдеятельность сухопутного и трубопроводного транспорта;\n\nдеятельность водного транспорта;\n\nдеятельность воздушного и космического транспорта;\n\nскладское хозяйство и вспомогательная транспортная деятельность;\n\nдеятельность почтовой связи и курьерская деятельность;\n\nпроизводство кинофильмов, видеофильмов и телевизионных программ;\n\nдеятельность в области телевизионного и радиовещания;\n\nдеятельность в сфере телекоммуникаций;\n\nразработка компьютерного программного обеспечения, консультационные услуги в данной области и другие сопутствующие услуги, за исключением организаций и индивидуальных предпринимателей, указанных в подпунктах 2 и 3 настоящего пункта;\n\nдеятельность в области информационных технологий, за исключением организаций и индивидуальных предпринимателей, указанных в подпунктах 2 и 3 настоящего пункта;\n\nуправление недвижимым имуществом за вознаграждение или на договорной основе;\n\nнаучные исследования и разработки;\n\nдеятельность ветеринарная;\n\nдеятельность туристических агентств и прочих организаций, предоставляющих услуги в сфере туризма;\n\nдеятельность по обслуживанию зданий и территорий;\n\nобразование;\n\nдеятельность в области здравоохранения;\n\nдеятельность по уходу с обеспечением проживания;\n\nпредоставление социальных услуг без обеспечения проживания;\n\nдеятельность учреждений культуры и искусства;\n\nдеятельность библиотек, архивов, музеев и прочих объектов культуры;\n\nдеятельность спортивных объектов;\n\nдеятельность спортивных клубов;\n\nдеятельность фитнес-центров;\n\nдеятельность в области спорта прочая;\n\nремонт компьютеров, предметов личного потребления и хозяйственно-бытового назначения;\n\nдеятельность по предоставлению прочих персональных услуг;\n\n(Подпункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\n6) для налогоплательщиков единого налога на вмененный доход для отдельных видов деятельности - аптечных организаций и индивидуальных предпринимателей, имеющих лицензию на фармацевтическую деятельность, - в отношении выплат и вознаграждений, производимых физическим лицам, которые в соответствии с Федеральным законом от 21 ноября 2011 года № 323-ФЗ \"Об основах охраны здоровья граждан в Российской Федерации\" имеют право на занятие фармацевтической деятельностью или допущены к ее осуществлению;\n\n7) для некоммерческих организаций (за исключением государственных (муниципальных) учреждений), зарегистрированных в установленном законодательством Российской Федерации порядке, применяющих упрощенную систему налогообложения и осуществляющих в соответствии с учредительными документами деятельность в области социального обслуживания граждан, научных исследований и разработок, образования, здравоохранения, культуры и искусства (деятельность театров, библиотек, музеев и архивов) и массового спорта (за исключением профессионального);\n\n8) для благотворительных организаций, зарегистрированных в установленном законодательством Российской Федерации порядке и применяющих упрощенную систему налогообложения;\n\n9) для индивидуальных предпринимателей, применяющих патентную систему налогообложения, - в отношении выплат и вознаграждений, начисленных в пользу физических лиц, занятых в виде экономической деятельности, указанном в патенте (за исключением индивидуальных предпринимателей, осуществляющих виды предпринимательской деятельности, указанные в подпунктах 19, 45 - 48 пункта 2 статьи 34643 настоящего Кодекса);\n\n10) для организаций, получивших статус участников проекта по осуществлению исследований, разработок и коммерциализации их результатов в соответствии с Федеральным законом от 28 сентября 2010 года № 244-ФЗ \"Об инновационном центре \"Сколково\", либо участников проекта в соответствии с Федеральным законом от 29 июля 2017 года № 216-ФЗ \"Об инновационных научно-технологических центрах и о внесении изменений в отдельные законодательные акты Российской Федерации\", либо для организаций, получивших статус участников Технополиса и созданных начиная с 1 января календарного года, предшествующего календарному году, в котором этими организациями подана заявка на внесение сведений в реестр участников Технополиса. Организации, получившие статус участника Технополиса, применяют единый пониженный тариф страховых взносов при условии, что они не применяют специальных налоговых режимов, предусмотренных настоящим Кодексом; (В редакции  Федерального закона от 23.11.2024 № 399-ФЗ)\n\n11) для организаций и индивидуальных предпринимателей, получивших статус участника свободной экономической зоны в соответствии с Федеральным законом от 29\n\nноября 2014 года № 377-ФЗ \"О развитии Республики Крым и города федерального значения Севастополя и свободной экономической зоне на территориях Республики Крым и города федерального значения Севастополя\" (далее - участник свободной экономической зоны), в отношении выплат и иных вознаграждений в пользу физических лиц, занятых в реализации инвестиционного проекта в свободной экономической зоне, информация о котором содержится в инвестиционной декларации, соответствующей требованиям, установленным Федеральным законом от 29 ноября 2014 года № 377-ФЗ \"О развитии Республики Крым и города федерального значения Севастополя и свободной экономической зоне на территориях Республики Крым и города федерального значения Севастополя\" (далее - физические лица, занятые в реализации инвестиционного проекта в свободной экономической зоне).\n\nВ целях настоящего подпункта физическим лицом, занятым в реализации инвестиционного проекта в свободной экономической зоне, признается лицо, заключившее трудовой договор с плательщиком - участником свободной экономической зоны, а его трудовые обязанности непосредственно связаны с реализацией инвестиционного проекта, указанного в абзаце первом настоящего подпункта, в том числе с эксплуатацией объектов основных средств, созданных в результате реализации инвестиционного проекта.\n\nПеречень рабочих мест физических лиц, занятых в реализации инвестиционного проекта в свободной экономической зоне, утверждается плательщиком - участником свободной экономической зоны по согласованию с высшим исполнительным органом Республики Крым или высшим исполнительным органом города федерального значения Севастополя (в зависимости от места нахождения такого плательщика). (В редакции  федеральных законов от 13.07.2020 № 204-ФЗ, от 19.12.2023 № 595-ФЗ)\n\nВысший исполнительный орган Республики Крым и высший исполнительный орган города федерального значения Севастополя в течение трех рабочих дней после внесения в единый реестр участников свободной экономической зоны записи о включении плательщика в указанный реестр либо записи о заключении с плательщиком, имеющим статус участника свободной экономической зоны, другого договора об условиях деятельности в свободной экономической зоне представляют в электронном виде в налоговые органы информацию о согласованном с таким плательщиком перечне рабочих мест физических лиц, занятых в реализации соответствующего инвестиционного проекта в свободной экономической зоне. В случае внесения участником свободной экономической зоны изменений в перечень рабочих мест физических лиц, занятых в реализации инвестиционного проекта в свободной экономической зоне, указанная информация должна быть представлена высшим исполнительным органом Республики Крым или высшим исполнительным органом города федерального значения Севастополя в электронном виде в налоговые органы в течение трех рабочих дней после согласования таких изменений; (Дополнение абзацем - Федеральный закон от 13.07.2020 № 204-ФЗ) (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\n(Подпункт в редакции Федерального закона от 03.08.2018 № 297-ФЗ)\n\n12) для организаций и индивидуальных предпринимателей, получивших статус резидента территории опережающего развития в соответствии с Федеральным законом от 29 декабря 2014 года № 473-ФЗ \"О территориях опережающего развития в Российской Федерации\" (далее - резидент территории опережающего развития); (В редакции  Федерального закона от 14.07.2022 № 334-ФЗ)\n\n13) для организаций и индивидуальных предпринимателей, получивших статус резидента свободного порта Владивосток в соответствии с Федеральным законом от 13 июля 2015 года № 212-ФЗ \"О свободном порте Владивосток\" (далее - резидент свободного порта Владивосток);\n\n14) для организаций, включенных в единый реестр резидентов Особой экономической зоны в Калининградской области в соответствии с Федеральным законом \"Об Особой экономической зоне в Калининградской области и о внесении изменений в некоторые законодательные акты Российской Федерации\". Плательщики, указанные в настоящем подпункте, применяют пониженные тарифы страховых взносов с учетом особенностей, установленных пунктом 11 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 353-ФЗ)\n\n15) для российских организаций, осуществляющих производство и реализацию произведенной ими анимационной аудиовизуальной продукции независимо от вида договора и (или) оказание услуг (выполнение работ) по созданию анимационной аудиовизуальной продукции. В целях настоящей статьи под анимационной аудиовизуальной продукцией понимается фильм, состоящий из специально созданных и двигающихся на экране рисованных или объемно-кукольных образов и объектов, создаваемых в том числе с использованием компьютерной графики; (Дополнение подпунктом - Федеральный закон от 23.04.2018 № 95-ФЗ)\n\n16) для плательщиков, получивших статус участника специального административного района в соответствии с Федеральным законом от 3 августа 2018 года № 291-ФЗ \"О специальных административных районах на территориях Калининградской области и Приморского края\", производящих выплаты и иные вознаграждения членам экипажей судов, зарегистрированных в Российском открытом реестре судов указанными плательщиками, за исполнение трудовых обязанностей члена экипажа судна, - в отношении данных выплат и вознаграждений; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n17) для плательщиков страховых взносов, признаваемых субъектами малого или среднего предпринимательства в соответствии с Федеральным законом от 24 июля 2007 года № 209-ФЗ \"О развитии малого и среднего предпринимательства в Российской Федерации\" в отношении части выплат в пользу физического лица, определяемой по итогам каждого календарного месяца как превышение над величиной полуторакратного минимального размера оплаты труда, установленного федеральным законом на начало расчетного периода; (Дополнение подпунктом - Федеральный закон от 01.04.2020 № 102-ФЗ) (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\n18) для российских организаций, которые включены в реестр организаций, осуществляющих деятельность в сфере радиоэлектронной промышленности, формирование и ведение которого осуществляются федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов; (Дополнение подпунктом - Федеральный закон от 31.07.2020 № 265-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\n19) для организаций, зарегистрированных на территории Курильских островов; (Дополнение подпунктом - Федеральный закон от 09.03.2022 № 50-ФЗ)\n\n20) для плательщиков страховых взносов, производящих выплаты и иные вознаграждения в пользу обучающихся в профессиональных образовательных организациях, образовательных организациях высшего образования по очной форме обучения за деятельность, осуществляемую в студенческих отрядах (включенных в федеральный или региональный реестр молодежных и детских объединений, пользующихся государственной поддержкой) по трудовым договорам или по гражданско-правовым договорам, предметом которых являются выполнение работ и (или) оказание услуг, - в отношении данных выплат и вознаграждений; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\n21) для организаций, которые включены в реестр организаций, являющихся участниками промышленных кластеров, подтвердивших соответствие требованиям к промышленным кластерам, установленным Правительством Российской Федерации, являющихся одновременно сторонами специальных инвестиционных контрактов, стороной которых является Российская Федерация, заключенных в соответствии со статьей 16 Федерального закона от 31 декабря 2014 года № 488-ФЗ \"О промышленной политике в Российской Федерации\" (далее - реестр участников промышленных кластеров). Федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, осуществляются формирование и ведение реестра участников промышленных кластеров, а также устанавливается порядок формирования и ведения реестра участников промышленных кластеров, в том числе основания для включения организации в указанный реестр и исключения из него; (Дополнение подпунктом - Федеральный закон от 18.03.2023 № 64-ФЗ)\n\n22) для организаций и индивидуальных предпринимателей, получивших статус участника свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях в соответствии с Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\", в отношении выплат и иных вознаграждений в пользу физических лиц, занятых в реализации инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, информация о котором содержится в инвестиционной декларации, соответствующей требованиям, установленным Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\" (далее - физические лица, занятые в реализации инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях). (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nВ целях настоящего подпункта физическим лицом, занятым в реализации инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, признается лицо, заключившее трудовой договор с плательщиком - участником свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, а его трудовые обязанности непосредственно связаны с реализацией инвестиционного проекта, указанного в абзаце первом настоящего подпункта, в том числе с эксплуатацией объектов основных средств, созданных в результате реализации инвестиционного проекта. (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nПеречень рабочих мест физических лиц, занятых в реализации инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, утверждается плательщиком - участником свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях по согласованию с управляющей компанией либо высшими исполнительными органами субъектов Российской Федерации, осуществляющими деятельность в соответствии с Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\". (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nУправляющая компания либо высшие исполнительные органы субъектов Российской Федерации, осуществляющие деятельность в соответствии с Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\", в течение трех рабочих дней после внесения в единый реестр участников свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области или реестр участников свободной экономической зоны, осуществляющих деятельность на прилегающей территории, записи о включении плательщика в соответствующий реестр либо записи о заключении с таким плательщиком другого договора об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях представляют в электронной форме в налоговые органы информацию о согласованном с таким плательщиком перечне рабочих мест физических лиц, занятых в реализации соответствующего инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях. В случае внесения участником свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях изменений в данный перечень указанная информация должна быть представлена управляющей компанией либо высшими исполнительными органами субъектов Российской Федерации, осуществляющими деятельность в соответствии с Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\", в электронной форме в налоговые органы в течение трех рабочих дней после согласования таких изменений; (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 24.06.2023 № 268-ФЗ)\n\n23) для централизованных религиозных организаций и религиозных организаций, входящих в структуру централизованных религиозных организаций. (Дополнение подпунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n1) для плательщиков, указанных в подпунктах 1 и 2 пункта 1 настоящей статьи: (В редакции Федерального закона от 28.12.2016 № 475-ФЗ)\n\nна обязательное пенсионное страхование в 2017 году - 8,0 процента, 2018 году - 13,0 процента, 2019 году - 20,0 процента;\n\nна обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством в 2017 году - 2,0 процента, 2018 году - 2,9 процента, 2019 году - 2,9 процента;\n\nна обязательное социальное страхование на случай временной нетрудоспособности в отношении выплат и иных вознаграждений в пользу иностранных граждан и лиц без гражданства, временно пребывающих в Российской Федерации (за исключением высококвалифицированных специалистов в соответствии с Федеральным законом от 25 июля 2002 года № 115-ФЗ \"О правовом положении иностранных граждан в Российской Федерации\"), - 1,8 процента;\n\nна обязательное медицинское страхование в 2017 году - 4,0 процента, 2018 году - 5,1 процента, 2019 году - 5,1 процента;\n\n11) для плательщиков, указанных в подпункте 3 пункта 1 настоящей статьи:\n\nна обязательное пенсионное страхование в течение 2017 - 2020 годов - 8,0 процента, в течение 2021 и 2022 годов - 6,0 процента; (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nна обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством в течение 2017 - 2020 годов - 2,0 процента, в течение 2021 и 2022 годов - 1,5 процента; (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nна обязательное социальное страхование на случай временной нетрудоспособности в отношении выплат и иных вознаграждений в пользу иностранных граждан и лиц без гражданства, временно пребывающих в Российской Федерации (за исключением высококвалифицированных специалистов в соответствии с Федеральным законом от 25 июля 2002 года № 115-ФЗ \"О правовом положении иностранных граждан в Российской Федерации\"), в течение 2017 - 2020 годов - 1,8 процента, в течение 2021 и 2022 годов - 1,5 процента; (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nна обязательное медицинское страхование в течение 2017 - 2020 годов - 4,0 процента, в течение 2021 и 2022 годов - 0,1 процента; (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 28.12.2016 № 475-ФЗ) (В редакции Федерального закона от 31.07.2020 № 265-ФЗ)\n\n2) для плательщиков, указанных в подпункте 4 пункта 1 настоящей статьи, тарифы страховых взносов на обязательное пенсионное страхование, на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, на обязательное медицинское страхование в течение 2017 - 2022 годов устанавливаются в размере 0 процентов; (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n3) для плательщиков, указанных в подпунктах 5 - 9 пункта 1 настоящей статьи, в течение 2017 - 2018 годов тарифы страховых взносов на обязательное пенсионное страхование устанавливаются в размере 20,0 процента, на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, на обязательное медицинское страхование - 0 процентов.\n\nУказанные в настоящем подпункте тарифы страховых взносов распространяются на плательщиков, применяющих упрощенную систему налогообложения, указанных в подпункте 5 пункта 1 настоящей статьи, если их доходы за налоговый период не превышают 79 млн. рублей. (В редакции Федерального закона от 03.08.2018 № 303-ФЗ)\n\nДля плательщиков, указанных в подпунктах 7 и 8 пункта 1 настоящей статьи, в течение 2019 - 2022 годов тарифы страховых взносов на обязательное пенсионное страхование устанавливаются в размере 20,0 процента, на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, на обязательное медицинское страхование - 0 процентов; (Дополнение абзацем - Федеральный закон от 03.08.2018 № 303-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n4) для плательщиков, указанных в подпункте 10 пункта 1 настоящей статьи, тарифы страховых взносов на обязательное пенсионное страхование устанавливаются в размере 14,0 процента, на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, на обязательное медицинское страхование - 0 процентов на период до 2022 года включительно; (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n5) для плательщиков, указанных в подпунктах 11 - 14, 19 пункта 1 настоящей статьи, тарифы страховых взносов на обязательное пенсионное страхование устанавливаются в размере 6,0 процента, на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством - 1,5 процента, на обязательное медицинское страхование - 0,1 процента на период до 2022 года включительно; (В редакции  федеральных законов от 27.11.2017 № 353-ФЗ, от 09.03.2022 № 50-ФЗ, от 14.07.2022 № 239-ФЗ)\n\n6) для плательщиков, указанных в подпункте 15 пункта 1 настоящей статьи, в течение 2018 - 2022 годов: (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nна обязательное пенсионное страхование - 8,0 процента;\n\nна обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством - 2,0 процента;\n\nна обязательное социальное страхование на случай временной нетрудоспособности в отношении в\n\nыплат и иных вознаграждений в пользу иностранных граждан и лиц без гражданства, временно пребывающих в Российской Федерации (за исключением высококвалифицированных специалистов в соответствии с Федеральным законом от 25 июля 2002 года № 115-ФЗ \"О правовом положении иностранных граждан в Российской Федерации\"), - 1,8 процента;\n\nна обязательное медицинское страхование - 4,0 процента;\n\n(Дополнение подпунктом - Федеральный закон от 23.04.2018 № 95-ФЗ)\n\n7) для плательщиков, указанных в подпункте 16 пункта 1 настоящей статьи, тарифы страховых взносов на обязательное пенсионное страхование, на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, на обязательное медицинское страхование устанавливаются в размере 0 процентов на период до 2022 года включительно; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n8) для плательщиков, указанных в подпункте 18 пункта 1 настоящей статьи, в течение 2021 и 2022 годов: (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nна обязательное пенсионное страхование - 6,0 процента;\n\nна обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством - 1,5 процента;\n\nна обязательное медицинское страхование - 0,1 процента.\n\n(Дополнение подпунктом - Федеральный закон от 31.07.2020 № 265-ФЗ)\n\n1) на обязательное пенсионное страхование:\n\nв пределах установленной предельной величины базы для исчисления страховых взносов по данному виду страхования - 10,0 процента;\n\nсвыше установленной предельной величины базы для исчисления страховых взносов по данному виду страхования - 10,0 процента;\n\n2) на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством - 0,0 процента;\n\n3) на обязательное медицинское страхование - 5,0 процента.\n\n(Дополнение пунктом - Федеральный закон от 01.04.2020 № 102-ФЗ)\n\n22-1. Для плательщиков, указанных в подпунктах 3 и 18 пункта 1 настоящей статьи, начиная с 2025 года применяются единый пониженный тариф страховых взносов в размере 7,6 процента свыше единой предельной величины базы для исчисления страховых взносов и единый пониженный тариф страховых взносов в размере 7,6 процента в пределах установленной единой предельной величины базы для исчисления страховых взносов. (Дополнение пунктом - Федеральный закон от 29.11.2024 № 416-ФЗ)\n\nосуществление научно-исследовательских и опытно-конструкторских работ и практическое применение (внедрение) результатов интеллектуальной деятельности. Под научно-исследовательскими и опытно-конструкторскими работами подразумеваются работы по созданию новой или усовершенствованию производимой продукции (товаров, работ, услуг), в частности изобретательство;\n\nприменение упрощенной системы налогообложения;\n\nвнесение в реестр учета уведомлений о создании хозяйственных обществ и хозяйственных партнерств.\n\nРеестр учета уведомлений о создании хозяйственных обществ и хозяйственных партнерств ведется уполномоченным Правительством Российской Федерации федеральным органом исполнительной власти и передается в налоговые органы не позднее 1-го числа месяца, следующего за отчетным периодом, в порядке, установленном федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если по итогам расчетного (отчетного) периода применительно к указанному расчетному (отчетному) периоду организация не выполняет условия, установленные настоящим пунктом, такая организация лишается права применять пониженные тарифы страховых взносов, предусмотренные подпунктом 1 пункта 2 настоящей статьи, с начала расчетного периода, в котором допущено несоответствие условиям, указанным в настоящем пункте.\n\nполучение в установленном порядке документа о государственной аккредитации организации, осуществляющей деятельность в области информационных технологий, или свидетельства, удостоверяющего регистрацию организации в качестве резидента технико-внедренческой особой экономической зоны или промышленно-производственной особой экономической зоны;\n\nпо итогам отчетного (расчетного) периода в сумме всех доходов организации, осуществляющей деятельность в области информационных технологий, учитываемых при определении налоговой базы по налогу на прибыль организаций в соответствии с главой 25 настоящего Кодекса, не менее 70 процентов составляют доходы:\n\nот реализации экземпляров разработанных, адаптированных и (или) модифицированных данной организацией либо лицом, входящим в одну группу лиц с данной организацией, программ для ЭВМ, баз данных (далее в настоящей статье - собственные программы для ЭВМ, базы данных);\n\nот передачи исключительных прав на собственные программы для ЭВМ, базы данных;\n\nот предоставления данной организацией прав использования собственных программ для ЭВМ, баз данных, в том числе путем предоставления удаленного доступа к собственным программам для ЭВМ, базам данных, включая обновления к ним и дополнительные функциональные возможности, через информационно-телекоммуникационную сеть, в том числе через информационно-телекоммуникационную сеть \"Интернет\" (далее в настоящей статье - сеть \"Интернет\") (за исключением доходов от предоставления прав использования программ для ЭВМ, баз данных (в том числе путем предоставления удаленного доступа к ним через сеть \"Интернет\"), если такие права состоят в получении возможности размещать предложения о приобретении (реализации) товаров (работ, услуг), имущественных прав в сети \"Интернет\", осуществлять поиск информации о потенциальных покупателях (продавцах) и (или) заключать сделки);\n\nот предоставления данной организацией прав использования собственных программ для ЭВМ, баз данных, в том числе путем предоставления удаленного доступа к собственным программам для ЭВМ, базам данных, включая обновления к ним и дополнительные функциональные возможности, через информационно-телекоммуникационную сеть, в том числе через информационно-телекоммуникационную сеть \"Интернет\" (далее в настоящей статье - сеть \"Интернет\") (за исключением доходов от предоставления указанных прав, если указанные права состоят в получении возможности в отношении определенного товара разместить в сети \"Интернет\" предложение, объявление о заключении договора купли-продажи товара и заключить договор купли-продажи, произвести предварительную оплату такого товара, при этом данная организация также обеспечивает возможность хранения, упаковки, доставки, выдачи такого товара покупателю с использованием недвижимого имущества и (или) транспортных средств, находящихся у нее на праве собственности, аренды или на ином праве, либо с привлечением данной организацией по гражданско-правовому договору взаимозависимого лица, которое признается таковым в соответствии с пунктом 2 статьи 1051 настоящего Кодекса и у которого эти объекты находятся на праве собственности, аренды или на ином праве; в получении возможности участвовать в процедуре закупок, предусмотренных Федеральным законом от 5 апреля 2013 года № 44-ФЗ \"О контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд\" и Федеральным законом от 18 июля 2011 года № 223-ФЗ \"О закупках товаров, работ, услуг отдельными видами юридических лиц\"; в получении возможности участвовать в организованных торгах на товарном рынке; в получении возможности инициировать и осуществлять операции по безналичному переводу денежных средств; в получении банковских, финансовых услуг, в том числе услуг финансирования под уступку денежного требования, услуг на рынке ценных бумаг (дилерская деятельность, брокерская деятельность, деятельность форекс-дилеров), предоставляемых (оказываемых) банками, кредитными организациями, небанковскими кредитными организациями и иными организациями; в получении услуг, связанных с совершением сделок с недвижимым имуществом, в отношении объектов недвижимости продавцов и (или) застройщиков и (или) объектов долевого строительства; в получении возможности разместить информацию о потенциальном спросе на услуги по перевозке пассажиров и багажа легковым такси, а также в получении возможности ознакомиться с информацией о предложениях лиц, оказывающих услуги в указанной сфере, и осуществить поиск таких предложений по заданным пользователем параметрам; в получении возможности разместить информацию об услугах общественного питания, предложение заключить договор о реализации определенного товара (блюда), изготовленного лицом, оказывающим услуги общественного питания, заключить договор купли-продажи, произвести предварительную оплату такого товара (блюда), при этом организация-плательщик также обеспечивает возможность доставки, выдачи такого товара (блюда) покупателю; в получении возможности формировать средства идентификации (коды маркировки), предоставляемой оператором государственной информационной системы мониторинга за оборотом товаров, подлежащих обязательной маркировке средствами идентификации; в получении возможности осуществлять хранение данных в центрах обработки данных; в получении возможности получать услуги связи по передаче данных в целях передачи голосовой информации, предоставляемой оператором связи); (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nот оказания услуг (выполнения работ) по разработке, адаптации и модификации программ для ЭВМ, баз данных (программных средств и информационных продуктов вычислительной техники) (далее в настоящей статье - заказные программы для ЭВМ, базы данных);\n\nот оказания услуг (выполнения работ) по установке, тестированию и сопровождению собственных программ для ЭВМ, баз данных и заказных программ для ЭВМ, баз данных;\n\nот оказания услуг (выполнения работ) по разработке (включая тестирование и сопровождение) программно-аппаратных комплексов при наличии документа, подтверждающего отнесение предусмотренных договором услуг (работ) к разработке программно-аппаратных комплексов и выданного федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере информационных технологий, в порядке, установленном указанным федеральным органом исполнительной власти, а также по адаптации, модификации, тестированию и сопровождению программно-аппаратных комплексов, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных; (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nот реализации разработанных данной организацией программно-аппаратных комплексов, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных;\n\nот оказания данной организацией услуг с использованием собственных программ для ЭВМ, баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных (либо в случае, если составная часть собственной программы для ЭВМ включена в единый реестр российских программ для электронных вычислительных машин и баз данных), по распространению рекламной информации в сети \"Интернет\" и (или) получению доступа к такой информации;\n\nот оказания услуг с использованием собственных программ для ЭВМ, баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных (либо в случае, если составная часть собственной программы для ЭВМ включена в единый реестр российских программ для электронных вычислительных машин и баз данных), по предоставлению доступа к аудиовизуальным произведениям и (или) сообщениям телепередач на аудиовизуальном сервисе, включенном в реестр аудиовизуальных сервисов;\n\nот оказания услуг и (или) предоставления прав использования, заключающихся в предоставлении доступа к отдельным фонограммам, совокупности фонограмм, объектам авторского и смежных прав, связанных с фонограммами, с использованием собственных программ для ЭВМ, баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных (либо в случае, если составная часть собственной программы для ЭВМ включена в единый реестр российских программ для электронных вычислительных машин и баз данных);\n\nот оказания услуг в сети \"Интернет\" с использованием собственных программ для ЭВМ, баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных (либо в случае, если составная часть собственной программы для ЭВМ включена в единый реестр российских программ для электронных вычислительных машин и баз данных), по размещению и (или) продвижению предложений, объявлений о приобретении (реализации) товаров (работ, услуг), имущественных прав, предложений о трудоустройстве, услуг по осуществлению поиска таких предложений, объявлений (доступа к таким предложениям, объявлениям) и (или) по заключению договоров (за исключением доходов от оказания услуг, указанных в настоящем абзаце, если эти услуги состоят в предоставлении возможности в отношении определенного товара разместить в сети \"Интернет\" предложение, объявление о заключении договора купли-продажи товара и заключить договор купли-продажи, произвести предварительную оплату такого товара, при этом данная организация также обеспечивает возможность хранения, упаковки, доставки, выдачи такого товара покупателю с использованием недвижимого имущества и (или) транспортных средств, находящихся у нее на праве собственности, аренды или на ином праве, либо с привлечением данной организацией по гражданско-правовому договору взаимозависимого лица, которое признается таковым в соответствии с пунктом 2 статьи 1051 настоящего Кодекса и у которого эти объекты находятся на праве собственности, аренды или на ином праве; от оказания данной организацией услуг, указанных в настоящем абзаце, если такие услуги состоят в получении возможности разместить информацию о потенциальном спросе на услуги по перевозке пассажиров и багажа легковым такси, а также в получении возможности ознакомиться с информацией о предложениях лиц, оказывающих услуги в указанной сфере и осуществить поиск таких предложений по заданным параметрам; в получении возможности разместить информацию об услугах общественного питания, заключить договор о реализации определенного товара (блюда), изготовленного лицом, оказывающим услуги общественного питания, заключить договор купли-продажи, произвести предварительную оплату такого товара (блюда), при этом организация-плательщик также обеспечивает возможность доставки, выдачи такого товара (блюда) покупателю; в получении возможности участвовать в процедуре закупок, предусмотренных Федеральным законом от 5 апреля 2013 года № 44-ФЗ \"О контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд\" и Федеральным законом от 18 июля 2011 года № 223-ФЗ \"О закупках товаров, работ, услуг отдельными видами юридических лиц\"; в получении возможности участвовать в организованных торгах на товарном рынке; в получении возможности инициировать и осуществлять операции по безналичному переводу денежных средств; в получении банковских, финансовых услуг, в том числе услуг финансирования под уступку денежного требования, услуг на рынке ценных бумаг (дилерская деятельность, брокерская деятельность, деятельность форекс-дилеров), предоставляемых (оказываемых) банками, кредитными организациями, небанковскими кредитными организациями и иными организациями; в получении услуг, связанных с совершением сделок с недвижимым имуществом, в отношении объектов недвижимости продавцов и (или) застройщиков и (или) объектов долевого строительства; в получении возможности формировать средства идентификации (коды маркировки), предоставляемой оператором государственной информационной системы мониторинга за оборотом товаров, подлежащих обязательной маркировке средствами идентификации; в получении возможности осуществлять хранение данных в центрах обработки данных; в получении возможности получать услуги связи по передаче данных в целях передачи голосовой информации, предоставляемой оператором связи); (В редакции  Федерального закона от 08\n\nот оказания данной организацией, имеющей лицензию на осуществление образовательной деятельности, с использованием собственных программ для ЭВМ, баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных (либо в случае, если составная часть собственной программы для ЭВМ включена в единый реестр российских программ для электронных вычислительных машин и баз данных), в том числе путем предоставления удаленного доступа к собственным программам для ЭВМ, базам данных, услуг по предоставлению доступа к электронной образовательной и (или) просветительской информации (сервисам).\n\nВ целях настоящего пункта сумма доходов определяется по данным налогового учета организации в соответствии со статьей 248 настоящего Кодекса, при этом в нее не включаются доходы, указанные в пунктах 2 и 11 части второй статьи 250 и пункте 41 статьи 271 настоящего Кодекса, а также доходы от уступки прав требования долга, возникшего при признании доходов, указанных в настоящем пункте.\n\nВ случае, если по итогам расчетного периода данная организация не выполняет условие о доле доходов, установленное настоящим пунктом, а также в случае лишения ее государственной аккредитации либо статуса резидента технико-внедренческой особой экономической зоны или промышленно-производственной особой экономической зоны данная организация лишается права применять тарифы страховых взносов, предусмотренные подпунктом 11 пункта 2, пунктами 22 и 22-1 настоящей статьи, с начала расчетного периода, в котором допущено несоответствие установленному условию, либо данная организация лишена государственной аккредитации, либо в реестр резидентов особой экономической зоны внесена запись о лишении данной организации статуса резидента технико-внедренческой особой экономической зоны или промышленно-производственной особой экономической зоны. (В редакции  федеральных законов от 21.11.2022 № 442-ФЗ, от 29.11.2024 № 416-ФЗ)\n\nВне зависимости от выполнения иных условий, установленных настоящим пунктом, тарифы страховых взносов, установленные подпунктом 11 пункта 2, пунктами 22 и 22-1 настоящей статьи, не подлежат применению: (В редакции  федеральных законов от 21.11.2022 № 442-ФЗ, от 29.11.2024 № 416-ФЗ)\n\nорганизациями, созданными в результате реорганизации (кроме преобразования) или реорганизованными в форме присоединения к ним другого юридического лица либо выделения из его состава одного или нескольких юридических лиц после 1 июля 2022 года;\n\nорганизациями (в том числе кредитными организациями), в которых прямо и (или) косвенно участвует Российская Федерация и доля такого участия составляет не менее 50 процентов, за исключением организаций, которые соответствуют критериям, установленным Правительством Российской Федерации. (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\nВ целях настоящего пункта лицом, входящим в одну группу лиц с данной организацией, признается лицо, которое прямо участвует в данной организации, либо в котором прямо участвует данная организация, либо в котором и в данной организации прямо участвует третье лицо и доля участия во всех случаях составляет более 50 процентов. Указанным лицом не может быть иностранная организация (за исключением иностранной организации, контролирующим лицом которой является российская организация или гражданин Российской Федерации) либо иностранный гражданин или лицо без гражданства. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 14.07.2022 № 321-ФЗ)\n\nдоходы в виде целевых поступлений на содержание некоммерческих организаций и ведение ими уставной деятельности в соответствии с подпунктом 7 пункта 1 настоящей статьи, определяемых в соответствии с пунктом 2 статьи 251 настоящего Кодекса (далее - целевые поступления);\n\nдоходы в виде грантов, получаемых для осуществления деятельности в соответствии с подпунктом 7 пункта 1 настоящей статьи и определяемых в соответствии с подпунктом 14 пункта 1 статьи 251 настоящего Кодекса (далее - гранты);\n\nдоходы от осуществления видов экономической деятельности, указанных в абзацах сорок седьмом, сорок восьмом, пятьдесят первом - пятьдесят девятом подпункта 5 пункта 1 настоящей статьи; (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nдоходы, получаемые некоммерческими организациями по соглашению о трудоустройстве инвалидов с работодателем, которому установлена квота для приема на работу инвалидов. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nОбщий объем доходов определяется плательщиками, указанными в подпункте 7 пункта 1 настоящей статьи, путем суммирования доходов, указанных в пункте 1 и подпункте 1 пункта 11 статьи 34615 настоящего Кодекса. Контроль за соблюдением условий, установленных настоящим пунктом, осуществляется в том числе на основании отчетности, представляемой некоммерческими организациями в соответствии со статьей 431 настоящего Кодекса. (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nИнформация о случаях несоответствия деятельности некоммерческой организации целям, предусмотренным ее учредительными документами, выявленных по результатам контроля, проводимого федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере регистрации некоммерческих организаций в соответствии со статьей 32 Федерального закона от 12 января 1996 года № 7-ФЗ \"О некоммерческих организациях\", представляется в налоговые органы в форме электронного документа в порядке, определенном соглашением об информационном обмене.\n\nВ случае, если по итогам расчетного (отчетного) периода применительно к указанному периоду организация не выполняет условия, установленные настоящим пунктом, такая организация лишается права применять пониженные тарифы страховых взносов, предусмотренные подпунктом 3 пункта 2 или пунктом 22 настоящей статьи, с начала расчетного периода, в котором допущено несоответствие условиям, указанным в настоящем пункте. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nПри определении объема доходов организации для проверки соответствия выполнения организацией условий, установленных настоящим пунктом, учитываются целевые поступления и гранты, поступившие и не использованные организацией по итогам предыдущих расчетных периодов.\n\nприменения упрощенной системы налогообложения;\n\nсоответствия деятельности благотворительной организации целям, предусмотренным ее учредительными документами.\n\nИнформация о случаях несоответствия деятельности благотворительной организации целям, предусмотренным ее учредительными документами, выявленных по результатам контроля, проводимого федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере регистрации некоммерческих организаций в соответствии со статьей 32 Федерального закона от 12 января 1996 года № 7-ФЗ \"О некоммерческих организациях\", представляется в налоговые органы в форме электронного документа в порядке, определенном соглашением об информационном обмене.\n\nВ случае, если по итогам расчетного (отчетного) периода применительно к указанному периоду организация не выполняет условия, установленные настоящим пунктом, такая организация лишается права применять пониженные тарифы страховых взносов, предусмотренные подпунктом 3 пункта 2 или пунктом 22 настоящей статьи, с начала расчетного периода, в котором допущено несоответствие условиям, указанным в настоящем пункте. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nУчастник Технополиса представляет в налоговый орган по месту учета в электронной форме расчет совокупного размера полученной выручки в порядке, предусмотренном пунктом 4 статьи 1452 настоящего Кодекса, в срок не позднее 20-го января года, следующего за истекшим календарным годом, в котором применялся единый пониженный тариф страховых взносов.\n\nВ случае, если совокупный размер полученной выручки превысил 1 миллиард рублей до истечения соответствующего календарного года, последний расчет совокупного размера полученной выручки представляется не позднее 20-го числа первого месяца квартала, следующего за кварталом, в котором произошло указанное превышение совокупного размера полученной выручки.\n\nПониженные тарифы страховых взносов, предусмотренные подпунктом 4 пункта 2, пунктом 24 настоящей статьи, не применяются для участника проекта с 1-го числа месяца, следующего за месяцем, в котором совокупный размер прибыли участника проекта превысил 300 миллионов рублей. Указанный совокупный размер прибыли рассчитывается в соответствии с главой 25 настоящего Кодекса нарастающим итогом начиная с 1-го числа года, в котором годовой объем выручки от реализации товаров (работ, услуг, имущественных прав), полученной этим участником проекта, превысил 1 миллиард рублей. Информацию о получении и об утрате организациями статуса участника проекта в налоговые органы представляет организация, признаваемая управляющей компанией в соответствии с Федеральным законом от 28 сентября 2010 года № 244-ФЗ \"Об инновационном центре \"Сколково\" либо Федеральным законом от 29 июля 2017 года № 216-ФЗ \"Об инновационных научно-технологических центрах и о внесении изменений в отдельные законодательные акты Российской Федерации\", в порядке, определенном соглашением об информационном обмене.\n\nЕдиный пониженный тариф страховых взносов, предусмотренный пунктом 24 настоящей статьи, не применяется для участника Технополиса с 1-го числа квартала, в котором размер полученной этим участником Технополиса выручки, рассчитанный нарастающим итогом начиная с 1-го числа года, в котором получен статус участника Технополиса, превысил 1 миллиард рублей. В случае утраты статуса участника Технополиса единый пониженный тариф страховых взносов, предусмотренный пунктом 24 настоящей статьи, не применяется для участника Технополиса с 1-го числа месяца, в котором утрачен указанный статус.\n\nИнформацию о получении и об утрате организациями статуса участника Технополиса в налоговые органы представляет специализированная организация, определенная Федеральным законом от 14 июля 2022 года № 253-ФЗ \"О Военном инновационном технополисе \"Эра\" Министерства обороны Российской Федерации и о внесении изменений в отдельные законодательные акты Российской Федерации\", в порядке, определенном соглашением об информационном обмене.\n\nДля организаций, утративших статус участника проекта, пониженные тарифы страховых взносов, предусмотренные подпунктом 4 пункта 2, пунктом 24 настоящей статьи, не применяются с 1-го числа месяца, в котором организация утратила статус участника проекта или участника Технополиса.\n\nСумма страховых взносов, подлежащая уплате за расчетный (отчетный) период, в котором произошло превышение, указанное в абзаце третьем или четвертом настоящего пункта, или в котором плательщик страховых взносов утратил статус участника проекта либо участника Технополиса, за исключением случая утраты плательщиком страховых взносов статуса участника проекта по осуществлению исследований, разработок и коммерциализации их результатов в соответствии с Федеральным законом от 28 сентября 2010 года № 244-ФЗ \"Об инновационном центре \"Сколково\" по истечении десяти лет со дня получения такого статуса, подлежит восстановлению исходя из тарифов страховых взносов, установленных для этого расчетного (отчетного) периода пунктом 2 или 3 статьи 425 настоящего Кодекса, и уплате в установленном порядке с учетом уменьшения на величину уплаченных за этот период страховых взносов с начислением соответствующих сумм пеней.\n\n(Пункт в редакции  Федерального закона от 23.11.2024 № 399-ФЗ)\n\nПлательщики, указанные в подпункте 11 пункта 1 настоящей статьи, получившие статус участника свободной экономической зоны начиная с 1 января 2018 года, применяют пониженные тарифы страховых взносов, предусмотренные подпунктом 5 пункта 2, пунктом 22 настоящей статьи, начиная с 1-го числа месяца, следующего за месяцем, в котором ими был получен такой статус, но не ранее чем с 1 января 2020 года. При этом пониженные тарифы страховых взносов применяются таким участником свободной экономической зоны до окончания срока существования свободной экономической зоны при условии, если разница между суммой страховых взносов, исчисленной исходя из тарифов страховых взносов, установленных пунктом 2 или 3 статьи 425 настоящего Кодекса, и суммой страховых взносов, исчисленной с применением пониженных тарифов страховых взносов, предусмотренных подпунктом 5 пункта 2 или пунктом 22 настоящей статьи соответственно, определяемая участником свободной экономической зоны нарастающим итогом с начала применения пониженных тарифов страховых взносов, не превышает величину, равную объему осуществленных капитальных вложений за аналогичный период, умноженную на коэффициент, размер которого устанавливается Правительством Российской Федерации в зависимости от вида экономической деятельности, осуществляемого участником свободной экономической зоны. С 1-го числа месяца, в котором возникло такое превышение, до 1-го числа месяца, в котором такое превышение устранено, вместо пониженных тарифов страховых взносов, предусмотренных подпунктом 5 пункта 2, пунктом 22 настоящей статьи, применяются тарифы страховых взносов, установленные пунктом 2 или 3 статьи 425 настоящего Кодекса. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nВысший исполнительный орган Республики Крым и высший исполнительный орган города федерального значения Севастополя не позднее 30-го числа месяца, следующего за расчетным (отчетным) периодом, представляют в электронном виде в налоговые органы сведения об осуществленных за каждый из последних трех месяцев расчетного (отчетного) периода плательщиками, получившими статус участника свободной экономической зоны начиная с 1 января 2018 года, капитальных вложениях. При этом в целях настоящего пункта понятие \"капитальные вложения\" используется в значении, указанном в Федеральном законе от 29 ноября 2014 года № 377-ФЗ \"О развитии Республики Крым и города федерального значения Севастополя и свободной экономической зоне на территориях Республики Крым и города федерального значения Севастополя\". (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\nДля плательщиков, утративших статус участника свободной экономической зоны, пониженные тарифы страховых взносов, предусмотренные подпунктом 5 пункта 2, пунктом 22 настоящей статьи, не применяются с 1-го числа месяца, следующего за месяцем, в котором ими был утрачен такой статус. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nВ случае расторжения договора об условиях деятельности в свободной экономической зоне по решению суда сумма страховых взносов подлежит восстановлению исходя из тарифов страховых взносов, установленных для этого расчетного (отчетного) периода пунктом 2 или 3 статьи 425 настоящего Кодекса, и уплате за весь период реализации инвестиционного проекта в свободной экономической зоне без соответствующих пеней в срок не позднее 15-го числа месяца, следующего за месяцем, в котором был расторгнут договор об условиях деятельности в свободной экономической зоне, с учетом уменьшения на величину уплаченных за этот период страховых взносов. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n(Пункт в редакции Федерального закона от 13.07.2020 № 204-ФЗ)\n\nПлательщики страховых взносов, получившие после 1 января 2023 года статус резидента территории опережающего развития, расположенной на территории Дальневосточного федерального округа, или статус резидента свободного порта Владивосток, применяют единые пониженные тарифы страхо\n\nвых взносов, предусмотренные пунктом 22 настоящей статьи, в течение десяти лет начиная с 1-го числа месяца, следующего за месяцем, в котором плательщик уведомил налоговый орган об использовании права на применение единых пониженных тарифов страховых взносов. Плательщик вправе представить в налоговый орган уведомление об использовании права на применение единых пониженных тарифов страховых взносов по форме, формату и в порядке, которые утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в течение трех лет со дня получения статуса резидента территории опережающего развития, расположенной на территории Дальневосточного федерального округа, или статуса резидента свободного порта Владивосток. В случае, если плательщик не представил уведомление об использовании права на применение единых пониженных тарифов страховых взносов до истечения периода представления указанного уведомления, единые пониженные тарифы страховых взносов, предусмотренные пунктом 22 настоящей статьи, применяются таким плательщиком в течение десяти лет начиная с 1-го числа месяца, следующего за месяцем, в котором истекает период представления указанного уведомления. (Дополнение абзацем - Федеральный закон от 21.11.2022 № 442-ФЗ)\n\nПониженные тарифы страховых взносов применяются плательщиками исключительно в отношении базы для исчисления страховых взносов, определенной в отношении физических лиц, занятых на новых рабочих местах. В целях настоящего пункта под новым рабочим местом понимается место, впервые создаваемое резидентом территории опережающего развития или резидентом свободного порта Владивосток при исполнении соглашения об осуществлении деятельности, заключенного в соответствии с Федеральным законом от 29 декабря 2014 года № 473-ФЗ \"О территориях опережающего развития в Российской Федерации\" или Федеральным законом от 13 июля 2015 года № 212-ФЗ \"О свободном порте Владивосток\" (далее в настоящем пункте - соглашение об осуществлении деятельности). При этом физическим лицом, занятым на новом рабочем месте, признается лицо, которое заключило трудовой договор с резидентом территории опережающего развития или резидентом свободного порта Владивосток и трудовые обязанности которого непосредственно связаны с исполнением соглашения об осуществлении деятельности, в том числе с эксплуатацией объектов основных средств, созданных в результате исполнения соглашения об осуществлении деятельности. (В редакции  Федерального закона от 14.07.2022 № 334-ФЗ)\n\nФедеральный орган исполнительной власти, осуществляющий в соответствии с Федеральным законом от 13 июля 2015 года № 212-ФЗ \"О свободном порте Владивосток\" ведение реестра резидентов свободного порта Владивосток, организация, признаваемая управляющей компанией в соответствии с Федеральным законом от 29 декабря 2014 года № 473-ФЗ \"О территориях опережающего развития в Российской Федерации\", федеральный орган исполнительной власти, уполномоченный Правительством Российской Федерации в соответствии с частью 6 статьи 34 Федерального закона от 29 декабря 2014 года № 473-ФЗ \"О территориях опережающего развития в Российской Федерации\", представляют в налоговые органы в порядке, определенном соглашением об информационном обмене, информацию о получении и об утрате плательщиком страховых взносов статуса резидента территории опережающего развития или статуса резидента свободного порта Владивосток, а также информацию об изменении перечня рабочих мест плательщика, относящихся к новым рабочим местам. (В редакции  Федерального закона от 14.07.2022 № 334-ФЗ)\n\nДля плательщиков, утративших статус резидента территории опережающего развития или статус резидента свободного порта Владивосток, пониженные тарифы страховых взносов, предусмотренные подпунктом 5 пункта 2, пунктом 22 настоящей статьи, не применяются с 1-го числа месяца, следующего за месяцем, в котором ими был утрачен соответствующий статус. (В редакции  федеральных законов от 14.07.2022 № 239-ФЗ, от 14.07.2022 № 334-ФЗ)\n\nПониженные тарифы страховых взносов, указанные в подпункте 5 пункта 2, пункте 22 настоящей статьи, применяются в отношении резидента территории опережающего развития (за исключением резидента территории опережающего развития, расположенной на территории Дальневосточного федерального округа), получившего такой статус не позднее чем в течение трех лет со дня создания соответствующей территории опережающего развития, если иное не установлено настоящим пунктом. (В редакции  федеральных законов от 01.05.2022 № 121-ФЗ, от 14.07.2022 № 239-ФЗ, от 14.07.2022 № 334-ФЗ)\n\nПравительство Российской Федерации устанавливает критерии оценки созданных до 1 января 2022 года территорий опережающего развития (за исключением территорий опережающего развития, расположенных на территории Дальневосточного федерального округа) и порядок ее проведения в целях продления до 31 декабря 2024 года включительно периода, в течение которого плательщики страховых взносов, приобретая статус резидента такой территории опережающего развития, получают право на применение пониженных тарифов страховых взносов, указанных в подпункте 5 пункта 2, пункте 22 настоящей статьи. Проведение указанной оценки, утверждение порядка ведения реестра таких территорий опережающего развития (за исключением территорий опережающего развития, расположенных на территории Дальневосточного федерального округа) и ведение указанного реестра осуществляются уполномоченным федеральным органом исполнительной власти в области создания и функционирования территорий опережающего развития в Российской Федерации, за исключением Дальневосточного федерального округа и Арктической зоны Российской Федерации. (Дополнение абзацем - Федеральный закон от 01.05.2022 № 121-ФЗ) (В редакции  федеральных законов от 14.07.2022 № 239-ФЗ, от 14.07.2022 № 334-ФЗ)\n\nПониженные тарифы страховых взносов, указанные в подпункте 5 пункта 2, пункте 22 настоящей статьи, применяются в отношении резидента территории опережающего развития, расположенной на территории Дальневосточного федерального округа, резидента свободного порта Владивосток, получивших соответствующий статус не позднее 31 декабря 2025 года, при условии, что объем инвестиций в соответствии с соглашением об осуществлении деятельности составляет не менее: (В редакции  федеральных законов от 14.07.2022 № 239-ФЗ, от 14.07.2022 № 334-ФЗ)\n\n500 тысяч рублей - для резидента территории опережающего развития, расположенной на территории Дальневосточного федерального округа; (В редакции  Федерального закона от 14.07.2022 № 334-ФЗ)\n\n500 тысяч рублей - для резидента свободного порта Владивосток. (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nПлательщик страховых взносов, получивший до 1 января 2023 года статус резидента территории опережающего развития, расположенной на территории Дальневосточного федерального округа, или статус резидента свободного порта Владивосток и применяющий единые пониженные тарифы страховых взносов, предусмотренные пунктом 22 настоящей статьи, вправе однократно представить в налоговый орган уведомление о приостановлении применения единых пониженных тарифов страховых взносов (далее в настоящем пункте - приостановление) на срок, не превышающий трех лет. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 294-ФЗ)\n\nПриостановление действует начиная с 1-го числа месяца, следующего за месяцем, в котором плательщик представил в налоговый орган соответствующее уведомление. В течение срока действия приостановления плательщик исчисляет страховые взносы исходя из единых тарифов страховых взносов, установленных пунктом 3 статьи 425 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 294-ФЗ)\n\nДо окончания срока действия приостановления плательщик вправе подать в налоговый орган уведомление о возобновлении применения единых пониженных тарифов страховых взносов (далее в настоящем пункте - возобновление). (Дополнение абзацем - Федеральный закон от 08.08.2024 № 294-ФЗ)\n\nПосле окончания срока действия приостановления плательщик применяет единые пониженные тарифы страховых взносов, предусмотренные пунктом 22 настоящей статьи, начиная с 1-го числа месяца, следующего за месяцем, в котором заканчивается срок действия приостановления, указанный в уведомлении о приостановлении, либо начиная с 1-го числа месяца, следующего за месяцем, в котором плательщик представил в налоговый орган уведомление о возобновлении, в течение срока, определяемого как разница между десятью годами и сроком, истекшим со дня получения плательщиком статуса резидента территории опережающего развития, расположенной на территории Дальневосточного федерального округа, или статуса резидента свободного порта Владивосток до начала действия приостановления. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 294-ФЗ)\n\nФорма и формат представления в электронной форме уведомления о приостановлении (возобновлении) применения единых пониженных тарифов страховых взносов утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 294-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 300-ФЗ)\n\n1) пониженные тарифы применяются плательщиками, включенными в единый реестр резидентов Особой экономической зоны в Калининградской области (далее в настоящем пункте - реестр) начиная с 1 января 2018 года; (В редакции Федерального закона от 29.11.2021 № 381-ФЗ)\n\n2) пониженные тарифы применяются плательщиками в течение десяти лет начиная с 1-го числа месяца, следующего за месяцем, в котором такой плательщик был включен в реестр; (В редакции Федерального закона от 29.11.2021 № 381-ФЗ)\n\n3) (Подпункт утратил силу - Федеральный закон от 29.11.2021 № 381-ФЗ)\n\n4) в случае исключения плательщиков из реестра пониженные тарифы не применяются с 1-го числа месяца, следующего за месяцем, в котором плательщик был исключен из реестра. (В редакции Федерального закона от 29.11.2021 № 381-ФЗ)\n\nПри этом в случае исключения плательщика из реестра до получения им свидетельства о выполнении условий инвестиционной декларации сумма страховых взносов подлежит восстановлению и уплате без соответствующих пеней за весь период реализации инвестиционного проекта в Особой экономической зоне в Калининградской области. Сумма страховых взносов, исчисленная исходя из тарифов страховых взносов, установленных пунктом 2 или 3 статьи 425 настоящего Кодекса, с учетом уменьшения на величину уплаченных за этот период страховых взносов подлежит уплате в срок не позднее 15-го числа месяца, следующего за месяцем, в котором плательщик был исключен из реестра; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 381-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n5) пониженные тарифы применяются плательщиками исключительно в отношении базы для исчисления страховых взносов, определенной в отношении физических лиц, занятых на новых рабочих местах. В целях применения настоящего подпункта под новым рабочим местом понимается место, впервые создаваемое организациями, включенными в реестр, при реализации инвестиционного проекта на территории Особой экономической зоны в Калининградской области (далее в настоящем подпункте - новое рабочее место). При этом физическим лицом, занятым на новом рабочем месте, признается лицо, заключившее трудовой договор с организацией, включенной в реестр, а его трудовые обязанности непосредственно связаны с реализацией указанного инвестиционного проекта, в том числе с эксплуатацией объектов основных средств, созданных в результате реализации инвестиционного проекта. Перечень рабочих мест плательщиков, относящихся к новым рабочим местам, утверждается плательщиками до начала применения в отношении физических лиц, занятых на новых рабочих местах, пониженных тарифов страховых взносов по согласованию с администрацией Особой экономической зоны в Калининградской области и налоговым органом по месту нахождения плательщиков.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 353-ФЗ)\n\n1) для вновь созданных организаций:\n\nдоля доходов от реализации экземпляров анимационной аудиовизуальной продукции, передачи исключительных прав на анимационную аудиовизуальную продукцию, предоставления прав использования анимационной аудиовизуальной продукции по лицензионным договорам, от оказания услуг (выполнения работ) по созданию анимационной аудиовизуальной продукции, а также от поступлений денежных средств в виде субсидий и (или) бюджетных ассигнований в рамках целевого финансирования, полученных из федерального бюджета, бюджетов субъектов Российской Федерации, местных бюджетов, предоставляемых на производство, продвижение, прокат и показ анимационной аудиовизуальной продукции, по итогам расчетного (отчетного) периода составляет не менее 90 процентов в сумме всех доходов организации за указанный период;\n\nполучение документа, подтверждающего нахождение плательщика в реестре организаций, осуществляющих производство анимационной аудиовизуальной продукции и (или) оказание услуг (выполнение работ) по созданию анимационной аудиовизуальной продукции. Форма указанного документа утверждается федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере кинематографии;\n\nсреднесписочная численность работников за расчетный (отчетный) период составляет не менее семи человек;\n\nсреднесписочная численность работников за соответствующий расчетный (отчетный) период составляет не менее среднесписочной численности работников за предшествующий ему расчетный (отчетный) период; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\nгодовой объем выручки от реализации произведенной анимационной аудиовизуальной продукции и (или) оказания услуг (выполнения работ) по созданию анимационной аудиовизуальной продукции, исчисленной в соответствии с главой 25 настоящего Кодекса, за соответствующий расчетный период на 10 процентов больше годового объема выручки от реализации произведенной анимационной аудиовизуальной продукции и (или) оказания услуг (выполнения работ) по созданию анимационной аудиовизуальной продукции, исчисленной в соответствии с главой 25 настоящего Кодекса, за предшествующий ему расчетный период; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\n2) для организаций, не являющихся вновь созданными:\n\nдоля доходов от реализации экземпляров анимационной аудиовизуальной продукции, передачи исключительных прав на анимационную аудиовизуальную продукцию, предоставления прав использования анимационной аудиовизуальной продукции по лицензионным договорам, от оказания услуг (выполнения работ) по созданию анимационной аудиовизуальной продукции, а также от поступлений денежных средств в виде субсидий и (или) бюджетных ассигнований в рамках целевого финансирования, полученных из федерального бюджета, бюджетов субъектов Российской Федерации, местных бюджетов, предоставляемых на производство, продвижение, прокат и показ анимационной аудиовизуальной продукции, по итогам девяти месяцев года, предшествующего году перехода организации на уплату страховых взносов по пониженным тарифам, предусмотренным подпунктом 6 пункта 2, пунктом 22 настоящей статьи, составляет не менее 90 процентов в сумме всех доходов организации за указанный период; (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nполучение документа, подтверждающего нахождение плательщика в реестре организаций, осуществляющих производство анимационной аудиовизуальной продукции и (или) оказание услуг (выполнение работ) по созданию анимационной аудиовизуальной продукции. Форма указанного документа утверждается федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере кинематографии;\n\nсредняя численность работников, определяемая в порядке, устанавливаемом федеральным органом исполнительной власти, уполномоченным в области статистики, за девять месяцев года, предшествующего году перехода организации на уплату страховых взносов по пониженным тарифам, предусмотренным подпунктом 6 пункта 2, пунктом 22 настоящей статьи, составляет не менее семи человек; (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nсредняя численность работников, определяемая в порядке, устанавливаемом федеральным органом исполнительной власти, уполномоченным в области статистики, за соответствующий расчетный (отчетный) период составляет не менее средней численности работников за предшествующий ему расчетный (отчетный) период; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\nгодовой объем выручки от реализации произведенной анимационной аудиовизуальной продукции и (или) оказания услуг (выполнения работ) по созданию анимационной аудиовизуальной продукции, исчисленной в соответствии с главой 25 настоящего Кодекса, за соответствующий расчетный период на 10 процентов больше годового объема выручки от реализации произведенной анимационной аудиовизуальной продукции и (или) оказания услуг (выполнения работ) по созданию анимационной аудиовизуальной продукции, исчисленной в соответствии с главой 25 настоящего Кодекса, за предшествующий ему расчетный период. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 23.04.2018 № 95-ФЗ)\n\nРеестр организаций, осуществляющих производство анимационной аудиовизуальной продукции и (или) оказание услуг (выполнение работ) по созданию анимационной аудиовизуальной продукции, ведется федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере кинематографии, в установленном им порядке.\n\nИнформация о нахождении организации, осуществляющей производство анимационной аудиовизуальной продукции и (или) оказание услуг (выполнение работ) по созданию анимационной аудиовизуальной продукции, в указанном реестре представляется в налоговые органы федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере кинематографии, в электронной форме в порядке, определенном соглашением об информационном обмене. Указанная информация передается в налоговые органы не позднее 1-го числа месяца, следующего за расчетным (отчетным) периодом.\n\nВ целях пункта 12 настоящей статьи сумма доходов определяется в соответствии со статьей 248 настоящего Кодекса по данным налогового учета организации, осуществляющей производство анимационной аудиовизуальной продукции и (или) оказание услуг (выполнение работ) по созданию анимационной аудиовизуальной продукции.\n\nВ случае, если по итогам расчетного (отчетного) периода указанная организация не выполняет хотя бы одно условие, установленное пунктом 12 насто\n\nящей статьи, а также в случае исключения ее из реестра организаций, осуществляющих производство анимационной аудиовизуальной продукции и (или) оказание услуг (выполнение работ) по созданию анимационной аудиовизуальной продукции, указанная организация лишается права применять тарифы страховых взносов, предусмотренные подпунктом 6 пункта 2, пунктом 22 настоящей статьи, с начала расчетного периода, в котором допущено несоответствие установленным условиям или произошло исключение из данного реестра. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nПеречень документов, необходимых для включения организации в реестр организаций, осуществляющих производство анимационной аудиовизуальной продукции и (или) оказание услуг (выполнение работ) по созданию анимационной аудиовизуальной продукции, порядок их представления, а также порядок и основания включения (исключения) указанных организаций в реестр организаций, осуществляющих производство анимационной аудиовизуальной продукции и (или) оказание услуг (выполнение работ) по созданию анимационной аудиовизуальной продукции, утверждаются федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере кинематографии.\n\nКонтроль за соблюдением требований, установленных пунктом 12 настоящей статьи, осуществляется в том числе на основании отчетности, представляемой организациями, осуществляющими производство анимационной аудиовизуальной продукции и (или) оказание услуг (выполнение работ) по созданию анимационной аудиовизуальной продукции, в соответствии со статьей 431 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 23.04.2018 № 95-ФЗ)\n\nДеятельность по предоставлению продуктов питания и напитков признается основным видом экономической деятельности, если класс 56 \"Деятельность по предоставлению продуктов питания и напитков\" раздела I \"Деятельность гостиниц и предприятий общественного питания\" Общероссийского классификатора видов экономической деятельности указан в качестве основного вида экономической деятельности плательщика в Едином государственном реестре юридических лиц либо Едином государственном реестре индивидуальных предпринимателей по состоянию на 1-е число месяца внесения сведений о юридических лицах и индивидуальных предпринимателях в единый реестр субъектов малого и среднего предпринимательства.\n\nВ случае несоответствия плательщика хотя бы одному из применимых к нему условий, установленных подпунктом 38 пункта 3 статьи 149 настоящего Кодекса, такой плательщик лишается права на применение пониженных тарифов страховых взносов, предусмотренных пунктами 21, 24 настоящей статьи, с начала расчетного периода, в котором допущено несоответствие установленным условиям. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nПри этом сумма страховых взносов, исчисленная с начала расчетного периода, в котором допущено несоответствие установленным условиям, исходя из тарифов страховых взносов, установленных пунктом 2 или 3 статьи 425 настоящего Кодекса, с учетом уменьшения на величину уплаченных за этот период страховых взносов, подлежит восстановлению и уплате в установленном порядке. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nсоответствующий вид экономической деятельности указан в качестве основного вида экономической деятельности в едином государственном реестре юридических лиц либо едином государственном реестре индивидуальных предпринимателей;\n\nпо итогам календарного года, предшествующего году перехода плательщика на уплату страховых взносов по единому пониженному тарифу страховых взносов, предусмотренному пунктом 25 настоящей статьи, а также по итогам отчетного (расчетного) периода в сумме всех доходов, определяемых в порядке, установленном главой 23, 25 или 262 настоящего Кодекса, не менее 70 процентов составляют доходы от осуществления основного вида экономической деятельности.\n\nВ случае несоответствия плательщика условиям, установленным настоящим пунктом, такой плательщик лишается права на применение единого пониженного тарифа страховых взносов, предусмотренного пунктом 25 настоящей статьи, с начала расчетного периода, в котором допущено несоответствие установленным условиям.\n\n(Дополнение пунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nот реализации услуг (работ) по проектированию и (или) разработке электронной компонентной базы (электронных модулей), электронной (радиоэлектронной) продукции и (или) материалов и технологий для производства электронной компонентной базы (электронных модулей) в соответствии с перечнем таких материалов и технологий, утверждаемым Правительством Российской Федерации;\n\nот реализации услуг (работ) по производству электронной (радиоэлектронной) продукции по перечню, утверждаемому Правительством Российской Федерации, и (или) по производству электронной компонентной базы (электронных модулей);\n\nот передачи исключительного права на результаты интеллектуальной деятельности и (или) предоставления права использования результатов интеллектуальной деятельности, созданных при проектировании и (или) разработке электронной компонентной базы (электронных модулей) и (или) электронной (радиоэлектронной) продукции;\n\nот реализации организацией электронной компонентной базы (электронных модулей), произведенной на основе собственных разработок или разработок лица, входящего в одну группу лиц с данной организацией;\n\nот реализации (передачи в аренду) произведенной на основе собственных разработок электронной (радиоэлектронной) продукции в соответствии с перечнем, утверждаемым Правительством Российской Федерации;\n\nот реализации произведенного организацией оборудования для производства электронной компонентной базы (электронных модулей), электронной (радиоэлектронной) продукции в соответствии с перечнем такого оборудования, утверждаемым Правительством Российской Федерации; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nот реализации услуг (работ) по ремонту и (или) техническому обслуживанию произведенной на основе собственных разработок электронной (радиоэлектронной) продукции в соответствии с перечнем, утверждаемым Правительством Российской Федерации.\n\nВ целях настоящего пункта сумма доходов определяется по данным налогового учета организации в соответствии со статьей 248 настоящего Кодекса, при этом в нее не включаются доходы, указанные в пунктах 2 и 11 части второй статьи 250 и пункте 41 статьи 271 настоящего Кодекса, а также доходы от уступки права требования долга, возникшего при признании доходов, указанных в настоящем пункте.\n\nВ случае, если по итогам расчетного (отчетного) периода организация не выполняет условие, установленное настоящим пунктом, а также в случае ее исключения из реестра организаций, осуществляющих деятельность в сфере радиоэлектронной промышленности, такая организация лишается права применять тарифы страховых взносов, предусмотренные подпунктом 8 пункта 2, пунктами 22 и 22-1 настоящей статьи, с начала расчетного периода, в котором допущено несоответствие установленному условию либо произошло исключение из указанного реестра. (В редакции  федеральных законов от 21.11.2022 № 442-ФЗ, от 29.11.2024 № 416-ФЗ)\n\nВ целях настоящего пункта лицом, входящим в одну группу лиц с данной организацией, признается лицо, которое прямо участвует в данной организации, либо в котором прямо участвует данная организация, либо в котором и в данной организации прямо участвует третье лицо, и при этом доля участия во всех случаях составляет более 50 процентов. Указанным лицом не может быть иностранная организация (за исключением иностранной организации, контролирующим лицом которой является российская организация или гражданин Российской Федерации) либо иностранный гражданин или лицо без гражданства. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nПорядок формирования и ведения реестра организаций, осуществляющих деятельность в сфере радиоэлектронной промышленности, в том числе основания для включения организации в указанный реестр и исключения из него, требования к организациям для целей включения в указанный реестр, устанавливается Правительством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2020 № 265-ФЗ) (В редакции Федерального закона от 14.07.2022 № 323-ФЗ)\n\nВ случае утраты организацией в соответствии с пунктом 3 статьи 2463 настоящего Кодекса права на освобождение от исполнения обязанностей налогоплательщика налога на прибыль организаций такая организация лишается права применять тарифы страховых взносов, установленные подпунктом 5 пункта 2, пунктом 22 настоящей статьи, с начала расчетного периода, в котором утрачено указанное право на освобождение от исполнения обязанностей, и сумма страховых взносов с начала такого расчетного периода подлежит восстановлению исходя из тарифов страховых взносов, установленных пунктом 2 или 3 статьи 425 настоящего Кодекса, и уплате в установленном порядке с учетом уменьшения на величину уплаченных за этот период страховых взносов с уплатой соответствующих пеней. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 09.03.2022 № 50-ФЗ)\n\n16. Плательщики, указанные в подпункте 21 пункта 1 настоящей статьи, применяют единые пониженные тарифы страховых взносов, установленные пунктом 22 настоящей статьи, в отношении базы для исчисления страховых взносов, определенной в отношении физических лиц, занятых в реализации инвестиционного проекта, реализуемого в соответствии со специальным инвестиционным контрактом, при условии ведения раздельного учета выплат в пользу указанных лиц и выплат другим лицам в отношении иной деятельности, к которой применяются единые тарифы страховых взносов, установленные пунктом 3 статьи 425 настоящего Кодекса.\n\nЕдиные пониженные тарифы страховых взносов, установленные пунктом 22 настоящей статьи, применяются начиная с 1-го числа месяца, следующего за месяцем, в котором плательщик был включен в реестр участников промышленных кластеров. При этом единые пониженные тарифы страховых взносов применяются участником промышленного кластера до окончания срока действия специального инвестиционного контракта, но не более семи лет и при условии, что разница между суммой страховых взносов, исчисленной исходя из единых тарифов страховых взносов, установленных пунктом 3 статьи 425 настоящего Кодекса, и суммой страховых взносов, исчисленной с применением единых пониженных тарифов страховых взносов, установленных пунктом 22 настоящей статьи, определяемая участником промышленного кластера нарастающим итогом с начала применения единых пониженных тарифов страховых взносов, не превышает величину, равную объему осуществленных инвестиций на реализацию инвестиционного проекта, реализуемого в соответствии со специальным инвестиционным контрактом, за аналогичный период. С 1-го числа месяца, в котором возникло такое превышение, вместо единых пониженных тарифов страховых взносов, установленных пунктом 22 настоящей статьи, применяются единые тарифы страховых взносов, установленные пунктом 3 статьи 425 настоящего Кодекса.\n\nВ случае исключения плательщика из реестра участников промышленных кластеров единые пониженные тарифы страховых взносов, установленные пунктом 22 настоящей статьи, не применяются с 1-го числа месяца, следующего за месяцем, в котором плательщик был исключен из реестра участников промышленных кластеров.\n\nВ случае расторжения специального инвестиционного контракта в связи с ненадлежащим исполнением (неисполнением) плательщиком обязательств по указанному контракту сумма страховых взносов, не уплаченная в связи с применением единых пониженных тарифов страховых взносов, установленных пунктом 22 настоящей статьи, подлежит восстановлению исходя из единых тарифов страховых взносов, установленных пунктом 3 статьи 425 настоящего Кодекса, и уплате в установленном порядке за весь период реализации инвестиционного проекта, реализуемого в соответствии со специальным инвестиционным контрактом, в срок не позднее 28-го числа месяца, следующего за месяцем, в котором был расторгнут специальный инвестиционный контракт, с учетом уменьшения на величину уплаченных за этот период страховых взносов со взысканием с плательщика соответствующих сумм пеней.\n\n(Дополнение пунктом - Федеральный закон от 18.03.2023 № 64-ФЗ)\n\nначиная с 1-го числа месяца, следующего за месяцем получения ими такого статуса, до 31 декабря (включительно) года, в котором истекают пять последовательных календарных лет, при условии сохранения в течение указанного периода среднеквартальных показателей средней численности работников и среднемесячного размера выплат и иных вознаграждений, начисленных организацией или индивидуальным предпринимателем в пользу этих работников, на уровне не ниже закрепленных в договоре об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях и не ниже соответствующих показателей за первый квартал 2023 года (при их наличии). Порядок определения указанных показателей и выполнения условия, установленного настоящим абзацем, утверждается федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере социально-экономического развития Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области, или уполномоченным Правительством Российской Федерации федеральным органом исполнительной власти в сфере функционирования свободной экономической зоны на прилегающих территориях; (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nначиная с 1-го числа года, следующего за окончанием периода, указанного в абзаце втором настоящего пункта, и до 1-го числа месяца, следующего за отчетным месяцем, в котором величина НТ, рассчитываемая в соответствии с настоящим пунктом, превысила величину, равную объему осуществленных за указанный период капитальных вложений в реализацию инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, информация о котором содержится в инвестиционной декларации, соответствующей требованиям, установленным Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\". (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nВеличина НТ для соответствующего отчетного месяца рассчитывается как сумма определяемых за период с 1-го числа года, следующего за окончанием периода, указанного в абзаце втором настоящего пункта, до последнего числа отчетного периода следующих величин:\n\nв виде разницы между суммой страховых взносов, исчисленной исходя из единых тарифов страховых взносов, установленных пунктом 3 статьи 425 настоящего Кодекса, и суммой страховых взносов, исчисленной с применением единых пониженных тарифов страховых взносов, предусмотренных пунктом 22 настоящей статьи;\n\nв виде разницы между суммами акциза на сталь жидкую, рассчитанными в соответствии с главой 22 настоящего Кодекса без учета положений абзацев девятого - одиннадцатого пункта 13 и (или) абзацев тринадцатого - пятнадцатого пункта 14 статьи 193 настоящего Кодекса, и суммами акциза на сталь жидкую, рассчитанными в соответствии с главой 22 настоящего Кодекса;\n\nв виде разницы между суммами налога на добычу полезных ископаемых при добыче угля и (или) железной руды, рассчитанными в соответствии с главой 26 настоящего Кодекса без учета положений подпункта 22 пункта 1 статьи 342 настоящего Кодекса, и суммами налога на добычу полезных ископаемых при добыче угля и (или) железной руды, рассчитанными в соответствии с главой 26 настоящего Кодекса.\n\nУправляющая компания либо высшие исполнительные органы субъектов Российской Федерации, осуществляющие деятельность в соответствии с Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\", не позднее 30-го числа месяца, следующего за расчетным (отчетным) периодом, представляют в электронной форме в налоговые органы сведения об осуществленных капитальных вложениях за каждый из последних трех месяцев расчетного (отчетного) периода плательщиками, получившими статус участника свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях. При этом в целях настоящего пункта понятие \"капитальные вложения\" используется в значении, указанном в Федеральном законе от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\". (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nДля плательщиков, утративших статус участника свободн\n\nой экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, единые пониженные тарифы страховых взносов, предусмотренные пунктом 22 настоящей статьи, не применяются с 1-го числа месяца, следующего за месяцем, в котором ими был утрачен такой статус. (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nВ случае расторжения договора об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области в одностороннем порядке (в свободной экономической зоне на прилегающих территориях - по соглашению сторон или по решению суда) в соответствии с Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\" сумма страховых взносов подлежит восстановлению исходя из единых тарифов страховых взносов, установленных пунктом 3 статьи 425 настоящего Кодекса, и уплате за весь период реализации инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях без соответствующих пеней в срок не позднее 15-го числа месяца, следующего за месяцем, в котором был расторгнут указанный договор, с учетом уменьшения на величину уплаченных за этот период страховых взносов. (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 24.06.2023 № 268-ФЗ)","article_title":"Статья 427. Пониженные тарифы страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c27b31a93c805a9a98cbe20c3106c9d7a36e138dc255b72f3aabb41e642da8a3"},{"code_id":"NK_RF_2","article_number":"428","version_date":"2000-07-31","article_text":"1. Для плательщиков, указанных в подпункте 1 пункта 1 статьи 419 настоящего Кодекса, в отношении выплат и иных вознаграждений в пользу физических лиц, занятых на видах работ, указанных в пункте 1 части 1 статьи 30 Федерального закона от 28 декабря 2013 года № 400-ФЗ \"О страховых пенсиях\", применяется дополнительный тариф страховых взносов на обязательное пенсионное страхование в размере 9 процентов (за исключением случаев, предусмотренных пунктом 3 настоящей статьи).\n\n2. Для плательщиков, указанных в подпункте 1 пункта 1 статьи 419 настоящего Кодекса, в отношении выплат и иных вознаграждений в пользу физических лиц, занятых на видах работ, указанных в пунктах 2 - 18 части 1 статьи 30 Федерального закона от 28 декабря 2013 года № 400-ФЗ \"О страховых пенсиях\", применяется дополнительный тариф страховых взносов на обязательное пенсионное страхование в размере 6 процентов (за исключением случаев, предусмотренных пунктом 3 настоящей статьи).\n\n3. Для плательщиков, указанных в пунктах 1 и 2 настоящей статьи, в зависимости от установленного по результатам специальной оценки условий труда, проводимой в порядке, установленном законодательством Российской Федерации, класса условий труда взамен установленных в пунктах 1 и 2 настоящей статьи дополнительных тарифов страховых взносов применяются следующие дополнительные тарифы страховых взносов на обязательное пенсионное страхование:\n\nДопустимый\n\nОптимальный","article_title":"Статья 428. Дополнительные тарифы страховых взносов для отдельных категорий плательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e83fd86ea42e1c33804e5987e14cecbce5262eb6f3fdc66cc7e65db250bba232"},{"code_id":"NK_RF_2","article_number":"429","version_date":"2000-07-31","article_text":"1. В отношении выплат и иных вознаграждений, начисленных в пользу членов летных экипажей воздушных судов гражданской авиации, признаваемых объектом обложения страховыми взносами в соответствии с пунктом 1 статьи 420 настоящего Кодекса, применяется тариф страховых взносов на дополнительное социальное обеспечение данных работников в размере 14 процентов.\n\n2. В отношении выплат и иных вознаграждений, начисленных в пользу работников, непосредственно занятых полный рабочий день на подземных и открытых горных работах (включая личный состав горноспасательных частей) по добыче угля и сланца и на строительстве шахт, и работников ведущих профессий - горнорабочих очистного забоя, проходчиков, забойщиков на отбойных молотках, машинистов горных выемочных машин, признаваемых объектом обложения страховых взносов в соответствии с пунктом 1 статьи 420 настоящего Кодекса, применяется тариф страховых взносов на дополнительное социальное обеспечение данных работников в размере 6,7 процента.\n\n3. Перечни плательщиков, применяющих тариф страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности, устанавливаются в порядке, предусмотренном Федеральным законом от 27 ноября 2001 года № 155-ФЗ \"О дополнительном социальном обеспечении членов летных экипажей воздушных судов гражданской авиации\" и Федеральным законом от 10 мая 2010 года № 84-ФЗ \"О дополнительном социальном обеспечении отдельных категорий работников организаций угольной промышленности\" соответственно.","article_title":"Статья 429. Тарифы страховых взносов для отдельных категорий плательщиков на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88268b7202e48d63e619a4b02de787659734d2c0b7a0c8f6b66b848250401580"},{"code_id":"NK_RF_2","article_number":"430","version_date":"2000-07-31","article_text":"1. Плательщики, указанные в подпункте 2 пункта 1 статьи 419 настоящего Кодекса, уплачивают:\n\n1) страховые взносы на обязательное пенсионное страхование в размере, который определяется в следующем порядке, если иное не предусмотрено настоящей статьей:\n\nв случае, если величина дохода плательщика за расчетный период не превышает 300 000 рублей, - в фиксированном размере 32 448 рублей за расчетный период 2021 года, 34 445 рублей за расчетный период 2022 года; (В редакции  федеральных законов от 15.10.2020 № 322-ФЗ, от 14.07.2022 № 239-ФЗ)\n\nв случае, если величина дохода плательщика за расчетный период превышает 300 000 рублей, - в фиксированном размере страховых взносов, установленном абзацем вторым настоящего подпункта, плюс 1,0 процента суммы дохода плательщика, превышающего 300 000 рублей за расчетный период. (В редакции Федерального закона от 15.10.2020 № 322-ФЗ)\n\nПри этом размер страховых взносов на обязательное пенсионное страхование за расчетный период не может быть более восьмикратного фиксированного размера страховых взносов на обязательное пенсионное страхование, установленного абзацем вторым настоящего подпункта;\n\n2) страховые взносы на обязательное медицинское страхование в фиксированном размере 8 426 рублей за расчетный период 2021 года, 8 766 рублей за расчетный период 2022 года. (В редакции  федеральных законов от 15.10.2020 № 322-ФЗ, от 14.07.2022 № 239-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\n11. Для индивидуальных предпринимателей, осуществляющих деятельность в отраслях российской экономики, в наибольшей степени пострадавших в условиях ухудшения ситуации в результате распространения новой коронавирусной инфекции, перечень которых утверждается Правительством Российской Федерации, страховые взносы на обязательное пенсионное страхование в фиксированном размере за расчетный период 2020 года составляют 20 318 рублей.\n\nИндивидуальные предприниматели признаются осуществляющими деятельность в соответствующей отрасли российской экономики, в наибольшей степени пострадавшей в условиях ухудшения ситуации в результате распространения новой коронавирусной инфекции, в порядке, аналогичном порядку, применяемому для определения лиц, в отношении которых предусмотрено продление установленных законодательством о налогах и сборах сроков уплаты налогов (авансовых платежей по налогам), в том числе предусмотренных специальными налоговыми режимами, сборов, страховых взносов в соответствии с подпунктами 2 и 3 пункта 3 статьи 4 настоящего Кодекса, и установленному Правительством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 08.06.2020 № 172-ФЗ)\n\n12. Плательщики, указанные в подпункте 2 пункта 1 статьи 419 настоящего Кодекса, начиная с 2023 года уплачивают:\n\n1) в случае, если величина дохода плательщика за расчетный период не превышает 300 000 рублей, - страховые взносы на обязательное пенсионное страхование, на обязательное медицинское страхование в совокупном фиксированном размере 45 842 рублей за расчетный период 2023 года, 49 500 рублей за расчетный период 2024 года, 53 658 рублей за расчетный период 2025 года, 57 390 рублей за расчетный период 2026 года, 61 154 рублей за расчетный период 2027 года, если иное не предусмотрено настоящей статьей; (В редакции  федеральных законов от 31.07.2023 № 389-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n2) в случае, если величина дохода плательщика за расчетный период превышает 300 000 рублей, - страховые взносы на обязательное пенсионное страхование, на обязательное медицинское страхование в совокупном фиксированном размере, установленном подпунктом 1 настоящего пункта, а также страховые взносы на обязательное пенсионное страхование в размере 1,0 процента суммы дохода плательщика, превышающего 300 000 рублей за расчетный период. При этом размер страховых взносов на обязательное пенсионное страхование с дохода плательщика, превышающего 300 000 рублей за расчетный период, не может быть более 257 061 рубля за расчетный период 2023 года, не может быть более 277 571 рубля за расчетный период 2024 года, не может быть более 300 888 рублей за расчетный период 2025 года, не может быть более 321 818 рублей за расчетный период 2026 года, не может быть более 342 923 рублей за расчетный период 2027 года. (В редакции  федеральных законов от 31.07.2023 № 389-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 239-ФЗ)\n\n2. Главы крестьянских (фермерских) хозяйств уплачивают страховые взносы на обязательное пенсионное страхование и на обязательное медицинское страхование за себя и за каждого члена крестьянского (фермерского) хозяйства.\n\nПри этом размер страховых взносов на обязательное пенсионное страхование в целом по крестьянскому (фермерскому) хозяйству определяется как произведение фиксированного размера страховых взносов, составляющего 32 448 рублей за расчетный период 2021 года, 34 445 рублей за расчетный период 2022 года, и количества всех членов крестьянского (фермерского) хозяйства, включая главу крестьянского (фермерского) хозяйства. (В редакции  федеральных законов от 27.11.2017 № 335-ФЗ, от 15.10.2020 № 322-ФЗ, от 14.07.2022 № 239-ФЗ)\n\nРазмер страховых взносов на обязательное медицинское страхование в целом по крестьянскому (фермерскому) хозяйству определяется за расчетный период как произведение фиксированного размера страховых взносов, составляющего 8 426 рублей за расчетный период 2021 года, 8 766 рублей за расчетный период 2022 года, и количества всех членов крестьянского (фермерского) хозяйства, включая главу крестьянского (фермерского) хозяйства. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции  федеральных законов от 15.10.2020 № 322-ФЗ, от 14.07.2022 № 239-ФЗ)\n\n21. Главы крестьянских (фермерских) хозяйств начиная с 2023 года уплачивают страховые взносы на обязательное пенсионное страхование, на обязательное медицинское страхование в совокупном фиксированном размере за себя и за каждого члена крестьянского (фермерского) хозяйства.\n\nПри этом размер указанных страховых взносов в целом по крестьянскому (фермерскому) хозяйству за расчетный период определяется как произведение совокупного фиксированного размера страховых взносов, установленного подпунктом 1 пункта 12 или пунктом 13 настоящей статьи, и количества всех членов крестьянского (фермерского) хозяйства, включая главу крестьянского (фермерского) хозяйства.\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 239-ФЗ) (В редакции  Федерального закона от 04.08.2023 № 427-ФЗ)\n\n1) для индивидуального предпринимателя календарный месяц, в котором произведена его государственная регистрация в качестве индивидуального предпринимателя;\n\n2) для адвоката, медиатора, нотариуса, занимающегося частной практикой, арбитражного управляющего, оценщика, патентного поверенного и иных лиц, занимающихся в установленном законодательством Российской Федерации порядке частной практикой, - календарный месяц, в котором адвокат, нотариус, занимающийся частной практикой, арбитражный управляющий, занимающийся частной практикой оценщик, патентный поверенный, медиатор и иные лица, занимающиеся в установленном законодательством Российской Федерации порядке частной практикой, поставлены на учет в налоговом органе. (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nЗа неполный месяц деятельности соответствующий фиксированный размер страховых взносов определяется пропорционально количеству календарных дней этого месяца по дату государственной регистрации прекращения физическим лицом деятельности в качестве индивидуального предпринимателя, дату снятия с учета в налоговых органах адвоката, нотариуса, занимающегося частной практикой, арбитражного управляющего, оценщика, медиатора, патентного поверенного и иных лиц, занимающихся в установленном законодательством Российской Федерации порядке частной практикой, включительно.\n\nза периоды, указанные в пункте 1 (в части военной службы по призыву), пунктах 3, 5 - 8, 12 части 1 статьи 12 Федерального закона от 28 декабря 2013 года № 400-ФЗ \"О страховых пенсиях\", периоды прохождения военной службы по контракту, заключенному в соответствии с пунктом 7 статьи 38 Федерального закона от 28 марта 1998 года № 53-ФЗ \"О воинской обязанности и военной службе\", в течение которых ими не осуществлялась соответствующая деятельность, при условии представления ими в налоговый орган по месту учета заявления об освобождении от уплаты страховых взносов и подтверждающих документов в срок не позднее трех лет с даты возникновения права на освобождение от уплаты страховых взносов; (В редакции  федеральных законов от 31.07.2023 № 389-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nза периоды, в которых приостановлен статус адвоката, при условии представления в налоговый орган по месту учета заявления об освобождении от уплаты страховых взносов в срок не позднее трех лет с даты возникновения права на освобождение от уплаты страховых взносов. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nЗа неполный месяц деятельности фиксированный размер страховых взносов определяется пропорционально количеству календарных дней этого месяца, в течение которых плательщиком осуществлялась указанная деятельность. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nного закона от 04.08.2023 № 427-ФЗ)\n\n1) для плательщиков, уплачивающих налог на доходы физических лиц, - в соответствии со статьей 210 настоящего Кодекса (в части дохода от предпринимательской и (или) иной профессиональной деятельности) с учетом уменьшения на профессиональные налоговые вычеты, указанные в статье 221 настоящего Кодекса (за исключением страховых взносов на обязательное пенсионное страхование и страховых взносов на обязательное медицинское страхование); (В редакции  федеральных законов от 28.12.2016 № 475-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n2) для плательщиков, применяющих систему налогообложения для сельскохозяйственных товаропроизводителей (сельскохозяйственный налог), - в соответствии с пунктом 1 статьи 3465 настоящего Кодекса;\n\n3) для плательщиков, применяющих упрощенную систему налогообложения, - в соответствии со статьей 34615 настоящего Кодекса;\n\n4) (Подпункт утратил силу - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n5) для плательщиков, применяющих патентную систему налогообложения, - в соответствии со статьями 34647 и 34651 настоящего Кодекса;\n\n6) для плательщиков, применяющих более одного режима налогообложения, - облагаемые доходы от деятельности суммируются.","article_title":"Статья 430. Размер страховых взносов, уплачиваемых плательщиками, не производящими выплат и иных вознаграждений физическим лицам","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f9f5103551dce4b6ca9ea8df646676bd98703259d15eb349c5d919e018067d44"},{"code_id":"NK_RF_2","article_number":"431","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 04.08.2023 № 427-ФЗ)\n\n1. В течение расчетного периода по итогам каждого календарного месяца плательщики производят исчисление и уплату страховых взносов исходя из базы для исчисления страховых взносов с начала расчетного периода до окончания соответствующего календарного месяца и тарифов страховых взносов за вычетом сумм страховых взносов, исчисленных с начала расчетного периода по предшествующий календарный месяц включительно.\n\n2. Сумма страховых взносов на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством уменьшается плательщиками страховых взносов на сумму произведенных ими расходов на выплату страхового обеспечения по указанному виду обязательного социального страхования в соответствии с законодательством Российской Федерации.\n\n1) на обязательное пенсионное страхование - в размере установленного Бюджетным кодексом Российской Федерации норматива 72,8 процента от суммы страховых взносов, исчисленной по единому тарифу страховых взносов, установленному пунктом 3 статьи 425 настоящего Кодекса, и (или) по единым пониженным тарифам страховых взносов, установленным пунктами 22 - 24 статьи 427 настоящего Кодекса;\n\n2) на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством - в размере установленного Бюджетным кодексом Российской Федерации норматива 8,9 процента от суммы страховых взносов, исчисленной по единому тарифу страховых взносов, установленному пунктом 3 статьи 425 настоящего Кодекса, и (или) по единым пониженным тарифам страховых взносов, установленным пунктами 22 - 24 статьи 427 настоящего Кодекса;\n\n3) на обязательное медицинское страхование - в размере установленного Бюджетным кодексом Российской Федерации норматива 18,3 процента от суммы страховых взносов, исчисленной по единому тарифу страховых взносов, установленному пунктом 3 статьи 425 настоящего Кодекса, и (или) по единым пониженным тарифам страховых взносов, установленным пунктами 22 - 24 статьи 427 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 04.08.2023 № 427-ФЗ)\n\nрасчет по страховым взносам - не позднее 25-го числа месяца, следующего за расчетным (отчетным) периодом;\n\nперсонифицированные сведения о физических лицах, включающие персональные данные физических лиц и сведения о суммах выплат и иных вознаграждений в их пользу за предшествующий календарный месяц, - не позднее 25-го числа каждого месяца, следующего за истекшим.\n\nВ случае, если в представляемом плательщиком расчете сведения по каждому физическому лицу о сумме выплат и иных вознаграждений в пользу физических лиц, базе для исчисления страховых взносов в пределах установленной предельной величины, сумме страховых взносов, исчисленных исходя из базы для исчисления страховых взносов, не превышающей предельной величины, базе для исчисления страховых взносов на обязательное пенсионное страхование по дополнительному тарифу, сумме страховых взносов на обязательное пенсионное страхование по дополнительному тарифу за расчетный (отчетный) период и (или) за каждый из последних трех месяцев расчетного (отчетного) периода содержат ошибки, а также если в представляемом плательщиком расчете суммы одноименных показателей по всем физическим лицам не соответствуют этим же показателям в целом по плательщику страховых взносов и (или) в расчете указаны недостоверные персональные данные, идентифицирующие застрахованных физических лиц, такой расчет считается непредставленным, о чем плательщику не позднее дня, следующего за днем получения расчета в электронной форме (не позднее 10 дней, следующих за днем получения расчета на бумажном носителе), направляется соответствующее уведомление.\n\nВ пятидневный срок с даты направления в электронной форме указанного в абзаце четвертом настоящего пункта уведомления (десятидневный срок с даты направления такого уведомления на бумажном носителе) плательщик страховых взносов обязан представить расчет, в котором устранено указанное несоответствие. В таком случае датой представления указанного расчета считается дата представления расчета, признанного первоначально не представленным.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\nКопии решений о выделении (отказе в выделении) средств на осуществление (возмещение) расходов страхователя на выплату страхового обеспечения, о непринятии к зачету расходов на выплату страхового обеспечения, а также информация об отмене (изменении) указанных решений вышестоящим органом территориального органа Фонда социального страхования Российской Федерации или судом направляется территориальным органом Фонда социального страхования Российской Федерации в налоговый орган в трехдневный срок со дня принятия соответствующего решения органом Фонда социального страхования Российской Федерации (вышестоящим органом территориального органа Фонда социального страхования Российской Федерации или судом).\n\nПорядок представления территориальными органами Фонда социального страхования Российской Федерации вступивших в силу решений по проведенным проверкам правильности расходов на выплату страхового обеспечения на обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, а также информации об отмене (изменении) указанных решений вышестоящим органом территориального органа Фонда социального страхования Российской Федерации или судом в налоговые органы определяется соглашением взаимодействующих сторон.\n\nРазница между суммой страховых взносов, подлежащей уплате в соответствии с указанным расчетом, и суммами страховых взносов, уплаченными плательщиками с начала расчетного периода, подлежит уплате в течение 15 календарных дней со дня подачи такого расчета или возврату плательщику в соответствии со статьей 79 настоящего Кодекса. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 431. Порядок исчисления и уплаты страховых взносов, уплачиваемых плательщиками, производящими выплаты и иные вознаграждения физическим лицам","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c30e92bb226be266cf8c45e8f2cf82b4364c25f322a3d2158ba82d9bb89e5cd"},{"code_id":"NK_RF_2","article_number":"432","version_date":"2000-07-31","article_text":"Суммы страховых взносов на обязательное пенсионное страхование и на обязательное медицинское страхование за расчетный период уплачиваются плательщиками в совокупном фиксированном размере или в размере, исчисленном в соответствии с пунктом 14 статьи 430 настоящего Кодекса, не позднее 28 декабря текущего календарного года, если иное не предусмотрено настоящей статьей. Страховые взносы на обязательное пенсионное страхование, исчисленные с суммы дохода плательщика, превышающей 300 000 рублей за расчетный период, уплачиваются плательщиком не позднее 1 июля года, следующего за истекшим расчетным периодом. (В редакции  федеральных законов от 14.07.2022 № 239-ФЗ, от 04.08.2023 № 427-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nВ случае неуплаты (неполной уплаты) страховых взносов плательщиками, указанными в подпункте 2 пункта 1 статьи 419 настоящего Кодекса, в срок, установленный абзацем вторым настоящего пункта, налоговый орган определяет в соответствии со статьей 430 настоящего Кодекса сумму страховых взносов, подлежащую уплате за расчетный период такими плательщиками.\n\nПри превышении суммы страховых взносов, определенной налоговым органом в соответствии с абзацем вторым настоящего пункта, над суммой страховых взносов, фактически уплаченных плательщиком за расчетный период, налоговый орган выявляет в порядке, установленном настоящим Кодексом, недоимку по страховым взносам.\n\nПрезидент Российской Федерации                              В.Путин\n\nМосква, Кремль\n\n5 августа 2000 года","article_title":"Статья 432. Порядок исчисления и уплаты страховых взносов, уплачиваемых плательщиками, не производящими выплат и иных вознаграждений физическим лицам","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f513f935f8a41dfd9e1fd6ff60f1deff9bddd5a77eb3568757eda6fd2967cfcd"}]$law7v029$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
